window.__qzParts=window.__qzParts||{};window.__qzParts.tin=[{"p":"Bộ phận nào của máy tính dùng để hiển thị hình ảnh và chữ?","o":["Màn hình","Bàn phím","Chuột máy tính","Thân máy"],"a":"Màn hình","h":"Bộ phận trông giống chiếc ti vi.","e":"Màn hình hiển thị hình ảnh, chữ và video để em nhìn thấy.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Bộ phận nào của máy tính chứa các mạch điện và được ví như bộ não xử lí thông tin?","o":["Thân máy","Màn hình","Chuột máy tính","Loa"],"a":"Thân máy","h":"Đây là chiếc hộp lớn nhất trong các bộ phận rời của máy tính để bàn.","e":"Thân máy chứa bộ xử lí trung tâm, được ví như bộ não của máy tính.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Để nhập chữ và số vào máy tính, em dùng bộ phận nào?","o":["Bàn phím","Màn hình","Chuột máy tính","Thân máy"],"a":"Bàn phím","h":"Bộ phận có rất nhiều phím chữ và phím số.","e":"Bàn phím có các phím chữ, phím số để em gõ vào máy tính.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Thao tác nháy đúp chuột là làm gì?","o":["Nhấn nút trái chuột hai lần liên tiếp thật nhanh","Nhấn giữ chuột thật lâu","Kéo chuột đi thật xa","Nhấn nút phải chuột một lần"],"a":"Nhấn nút trái chuột hai lần liên tiếp thật nhanh","h":"Thao tác này gồm hai lần nhấn chuột rất gần nhau.","e":"Nháy đúp là nhấn nút trái chuột hai lần liên tiếp thật nhanh, thường dùng để mở phần mềm.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi ngồi học với máy tính, tư thế nào là đúng?","o":["Ngồi thẳng lưng, mắt cách màn hình vừa phải","Ghé sát mặt vào màn hình","Ngồi cong lưng, cúi sát bàn phím","Nằm dài ra ghế nhìn màn hình"],"a":"Ngồi thẳng lưng, mắt cách màn hình vừa phải","h":"Tư thế đúng giúp em bảo vệ mắt và cột sống.","e":"Ngồi thẳng lưng và giữ khoảng cách vừa phải với màn hình giúp em bảo vệ mắt và cột sống.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Phím nào sau đây thuộc hàng phím cơ sở trên bàn phím?","o":["Phím A","Phím Q","Phím Z","Phím P"],"a":"Phím A","h":"Hàng phím cơ sở là hàng phím ở giữa, nơi em đặt tay khi bắt đầu gõ.","e":"Hàng phím cơ sở gồm các phím A, S, D, F, G, H, J, K, L.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Việc nào sau đây giúp em an toàn khi dùng máy tính?","o":["Không chạm tay ướt vào dây điện và ổ cắm","Vừa ăn uống vừa gõ bàn phím","Để cốc nước ngay cạnh bàn phím","Tự ý tháo nắp thân máy ra xem"],"a":"Không chạm tay ướt vào dây điện và ổ cắm","h":"Hãy nghĩ đến nguy cơ từ điện và nước.","e":"Tay ướt chạm vào điện rất nguy hiểm, em cần giữ tay khô và tránh xa ổ cắm điện.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Thông tin nào sau đây em không nên chia sẻ cho người lạ?","o":["Mật khẩu và địa chỉ nhà của em","Tên bài hát em thích","Màu sắc em yêu thích","Môn học em thích nhất"],"a":"Mật khẩu và địa chỉ nhà của em","h":"Đó là những thông tin riêng tư chỉ em và gia đình biết.","e":"Mật khẩu, địa chỉ nhà, số điện thoại là thông tin cá nhân cần giữ kín.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Để di chuyển một biểu tượng trên màn hình đến vị trí khác, em dùng thao tác nào với chuột?","o":["Kéo thả","Nháy đúp","Nháy chuột phải","Lăn nút cuộn"],"a":"Kéo thả","h":"Em nhấn giữ chuột, đưa biểu tượng đi rồi buông ra.","e":"Kéo thả là nhấn giữ nút trái chuột, di chuyển chuột đến vị trí mới rồi thả ra.","t":"tin-cap1","l":"thu-thach"},{"p":"Em sắp xếp sách vở và đồ dùng gọn gàng, theo đúng chỗ để làm gì?","o":["Để dễ tìm khi cần dùng","Chỉ để trông cho đẹp mắt","Để được bạn bè khen","Để cất được nhiều đồ hơn"],"a":"Để dễ tìm khi cần dùng","h":"Giống như khi em tìm một quyển sách trong cặp đã sắp xếp ngăn nắp.","e":"Sắp xếp đồ vật theo trật tự giúp em tìm nhanh khi cần dùng.","t":"tin-cap1","l":"thu-thach"},{"p":"Để chơi trò chơi ghép hình trên máy tính, em cần mở gì?","o":["Một phần mềm trò chơi","Thân máy","Ổ cắm điện","Bàn học"],"a":"Một phần mềm trò chơi","h":"Trò chơi trên máy tính chạy nhờ một chương trình được cài sẵn.","e":"Trò chơi ghép hình là một phần mềm, em nháy đúp vào biểu tượng của nó để mở và chơi.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi em di chuyển chuột trên mặt bàn, con trỏ chuột trên màn hình sẽ thế nào?","o":["Di chuyển theo","Đứng yên một chỗ","Biến mất","Quay tròn liên tục"],"a":"Di chuyển theo","h":"Con trỏ chuột luôn nghe theo chuyển động của chuột.","e":"Con trỏ chuột di chuyển theo đúng hướng em di chuyển chuột trên mặt bàn.","t":"tin-cap1","l":"thu-thach"},{"p":"Hai phím có gờ nhỏ trên hàng phím cơ sở, giúp em đặt tay đúng mà không cần nhìn, là phím nào?","o":["Phím F và phím J","Phím A và phím L","Phím G và phím H","Phím D và phím K"],"a":"Phím F và phím J","h":"Đó là hai phím dành cho hai ngón tay trỏ.","e":"Phím F và phím J có gờ nhỏ để em định vị hai ngón tay trỏ khi gõ phím.","t":"tin-cap1","l":"thu-thach"},{"p":"Em muốn mở một phần mềm từ màn hình nền (Desktop). Thao tác đúng là gì?","o":["Nháy đúp chuột vào biểu tượng của phần mềm","Nháy chuột một lần vào biểu tượng","Kéo biểu tượng của phần mềm đi chỗ khác","Nhấn nút phải chuột vào biểu tượng"],"a":"Nháy đúp chuột vào biểu tượng của phần mềm","h":"Hãy nhớ thao tác mở phần mềm đã học ở bài chuột máy tính.","e":"Trên màn hình nền, em nháy đúp chuột vào biểu tượng để mở phần mềm.","t":"tin-cap1","l":"kho"},{"p":"Sắp xếp các tệp và thư mục trong máy tính gọn gàng, theo từng nhóm có lợi ích gì?","o":["Giúp em tìm lại tệp nhanh và dễ dàng","Làm máy tính nặng hơn","Làm màn hình sáng hơn","Giúp chuột chạy nhanh hơn"],"a":"Giúp em tìm lại tệp nhanh và dễ dàng","h":"Lợi ích này giống với việc sắp xếp đồ dùng trong phòng của em.","e":"Giống như sắp xếp đồ dùng, sắp xếp tệp ngăn nắp giúp em tìm lại nhanh khi cần.","t":"tin-cap1","l":"kho"},{"p":"Phần cứng của máy tính là gì?","o":["Các bộ phận em có thể nhìn thấy và chạm vào được","Các chương trình chạy trong máy tính","Các trò chơi trên máy tính","Các trang web trên Internet"],"a":"Các bộ phận em có thể nhìn thấy và chạm vào được","h":"Hãy nghĩ đến màn hình, bàn phím và chuột.","e":"Phần cứng gồm các bộ phận vật lí như màn hình, bàn phím, chuột và thân máy.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Phần mềm của máy tính là gì?","o":["Các chương trình giúp máy tính làm việc theo yêu cầu của em","Chiếc hộp chứa các bộ phận máy tính","Sợi dây nối các bộ phận với nhau","Chiếc ghế em ngồi khi học"],"a":"Các chương trình giúp máy tính làm việc theo yêu cầu của em","h":"Phần mềm khác phần cứng ở chỗ em không chạm vào được.","e":"Phần mềm là các chương trình bên trong máy tính, em không sờ hay chạm vào được.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Vật nào sau đây là phần cứng của máy tính?","o":["Bàn phím","Phần mềm vẽ Paint","Phần mềm soạn thảo văn bản","Trò chơi trên máy tính"],"a":"Bàn phím","h":"Chỉ có một lựa chọn là vật thật em cầm được.","e":"Bàn phím là bộ phận vật lí nên thuộc phần cứng, các lựa chọn còn lại là phần mềm.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Internet là gì?","o":["Mạng máy tính khổng lồ kết nối các máy tính trên khắp thế giới","Một loại máy tính mới","Một trò chơi trực tuyến","Một phần mềm vẽ tranh"],"a":"Mạng máy tính khổng lồ kết nối các máy tính trên khắp thế giới","h":"Nhờ có Internet, em xem được thông tin từ rất xa.","e":"Internet kết nối hàng tỉ máy tính trên thế giới để các máy chia sẻ thông tin với nhau.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Thư mục trong máy tính dùng để làm gì?","o":["Chứa và sắp xếp các tệp cho gọn gàng","Để vẽ tranh","Để nghe nhạc","Để gõ văn bản"],"a":"Chứa và sắp xếp các tệp cho gọn gàng","h":"Thư mục giống như một ngăn tủ đựng đồ.","e":"Thư mục giúp em chứa và phân loại các tệp cho gọn gàng, dễ tìm.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn gõ được tiếng Việt có dấu trên máy tính, em cần bật gì?","o":["Phần mềm hỗ trợ gõ tiếng Việt","Phần mềm vẽ tranh","Phần mềm trình chiếu","Phần mềm nghe nhạc"],"a":"Phần mềm hỗ trợ gõ tiếng Việt","h":"Bàn phím không tự tạo được dấu tiếng Việt nếu thiếu phần mềm này.","e":"Em cần bật phần mềm hỗ trợ gõ tiếng Việt thì mới gõ được chữ có dấu.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Sau khi soạn thảo văn bản xong, em cần làm gì để lần sau mở lại được?","o":["Lưu văn bản vào máy tính","Tắt máy ngay lập tức","Xoá hết văn bản vừa gõ","In văn bản ra giấy"],"a":"Lưu văn bản vào máy tính","h":"Việc này giúp bài làm của em không bị mất.","e":"Lưu văn bản giúp em giữ lại bài làm để xem và chỉnh sửa sau này.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Việc nào sau đây thể hiện em tôn trọng bản quyền?","o":["Không sao chép bài làm hay phần mềm của người khác khi chưa được phép","Sao chép tranh của bạn rồi nhận là của mình","Tải phần mềm lậu về dùng","Chép bài của bạn khi làm bài tập"],"a":"Không sao chép bài làm hay phần mềm của người khác khi chưa được phép","h":"Tôn trọng bản quyền nghĩa là tôn trọng công sức của người tạo ra sản phẩm.","e":"Tôn trọng bản quyền là không dùng sản phẩm của người khác khi chưa được cho phép.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em muốn giới thiệu về trường mình trước lớp bằng các trang chiếu có chữ và hình ảnh. Phần mềm trình chiếu giúp em làm gì?","o":["Tạo các trang chiếu có chữ, hình ảnh để trình bày trước lớp","Chỉ dùng để nghe nhạc","Chỉ dùng để luyện gõ phím","Dùng để lưu trữ mọi tệp"],"a":"Tạo các trang chiếu có chữ, hình ảnh để trình bày trước lớp","h":"Hãy nhớ các buổi thuyết trình em từng xem trên lớp.","e":"Phần mềm trình chiếu giúp em tạo các trang chiếu sinh động để trình bày trước lớp.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi đặt tên cho tệp, em nên đặt tên như thế nào?","o":["Tên gợi nhớ nội dung của tệp","Tên thật dài và khó hiểu","Tên không có nghĩa","Tên giống hệt nhau cho mọi tệp"],"a":"Tên gợi nhớ nội dung của tệp","h":"Tên tệp tốt giúp em nhận ra ngay tệp chứa gì.","e":"Đặt tên tệp gợi nhớ nội dung giúp em tìm lại tệp nhanh chóng.","t":"tin-cap1","l":"thu-thach"},{"p":"Muốn chèn một bức ảnh vào trang chiếu, em làm thế nào?","o":["Dùng lệnh chèn ảnh trong phần mềm trình chiếu rồi chọn ảnh","Vẽ lại bức ảnh bằng tay","In ảnh ra rồi dán lên màn hình","Không thể chèn ảnh vào trang chiếu"],"a":"Dùng lệnh chèn ảnh trong phần mềm trình chiếu rồi chọn ảnh","h":"Phần mềm trình chiếu có sẵn lệnh dành riêng cho việc đưa ảnh vào.","e":"Phần mềm trình chiếu có lệnh chèn ảnh, em chọn ảnh từ trong máy tính để đưa vào trang chiếu.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi tìm thông tin trên Internet để làm bài tập, em nên làm gì?","o":["Gõ từ khoá ngắn gọn liên quan đến điều cần tìm","Gõ cả một đoạn văn thật dài vào ô tìm kiếm","Chỉ xem bất kì trang nào hiện ra đầu tiên","Sao chép mọi thứ tìm thấy vào bài làm"],"a":"Gõ từ khoá ngắn gọn liên quan đến điều cần tìm","h":"Từ khoá là những từ quan trọng nhất của điều em cần tìm.","e":"Dùng từ khoá ngắn gọn giúp máy tìm kiếm đưa ra kết quả đúng ý em hơn.","t":"tin-cap1","l":"thu-thach"},{"p":"Ví dụ nào sau đây là phần mềm?","o":["Phần mềm soạn thảo văn bản","Màn hình","Thân máy","Sợi dây cáp nối"],"a":"Phần mềm soạn thảo văn bản","h":"Phần mềm là chương trình, không phải vật em cầm được.","e":"Phần mềm soạn thảo là chương trình trong máy tính, các lựa chọn còn lại đều là phần cứng.","t":"tin-cap1","l":"thu-thach"},{"p":"Em có nhiều tệp ảnh chụp chuyến đi chơi của lớp. Cách sắp xếp nào hợp lí nhất?","o":["Tạo một thư mục riêng cho chuyến đi và đưa các ảnh vào đó","Để tất cả ảnh lẫn với mọi tệp khác","Đặt tất cả các ảnh cùng một tên","Xoá bớt ảnh cho đỡ rối"],"a":"Tạo một thư mục riêng cho chuyến đi và đưa các ảnh vào đó","h":"Hãy gom những tệp liên quan đến nhau vào cùng một chỗ.","e":"Gom các tệp liên quan vào một thư mục giúp em quản lí và tìm kiếm dễ dàng.","t":"tin-cap1","l":"kho"},{"p":"Bạn em bảo em chép lại một phần mềm học tập có bản quyền (phải mua mới được dùng) để mang về cài. Em nên làm gì?","o":["Không sao chép trái phép, chỉ dùng khi được phép hoặc nhờ người lớn mua bản quyền","Cứ chép về dùng thoải mái","Chép rồi chia sẻ cho cả lớp dùng","Đổi tên phần mềm rồi mới dùng"],"a":"Không sao chép trái phép, chỉ dùng khi được phép hoặc nhờ người lớn mua bản quyền","h":"Hãy nhớ bài học về tôn trọng bản quyền.","e":"Sao chép phần mềm có bản quyền khi chưa được phép là vi phạm bản quyền.","t":"tin-cap1","l":"kho"},{"p":"Thư điện tử (email) dùng để làm gì?","o":["Gửi và nhận thư qua Internet","Để vẽ tranh trên máy tính","Để chơi trò chơi","Để nghe nhạc"],"a":"Gửi và nhận thư qua Internet","h":"Email giống như thư tay nhưng được gửi qua mạng.","e":"Email giúp em gửi và nhận thư, kèm tệp đính kèm, qua mạng Internet rất nhanh.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Địa chỉ email luôn có kí tự đặc biệt nào?","o":["Kí tự @","Kí tự #","Kí tự %","Kí tự &"],"a":"Kí tự @","h":"Kí tự này đứng giữa tên người dùng và tên nhà cung cấp dịch vụ thư.","e":"Địa chỉ email gồm tên người dùng, kí tự @ và tên nhà cung cấp dịch vụ.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong phần mềm lập trình Scratch, sân khấu là gì?","o":["Khu vực hiển thị nhân vật và kết quả chạy chương trình","Nơi chứa các khối lệnh để kéo thả","Chỗ để viết thư điện tử","Một phần mềm vẽ tranh"],"a":"Khu vực hiển thị nhân vật và kết quả chạy chương trình","h":"Đó là khu vực lớn nơi nhân vật biểu diễn.","e":"Sân khấu là nơi nhân vật xuất hiện và chương trình của em được trình diễn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khối lệnh vòng lặp trong Scratch giúp em làm gì?","o":["Lặp lại một việc nhiều lần mà không cần xếp lại nhiều khối lệnh giống nhau","Làm nhân vật biến mất","Đổi màu sân khấu","Tắt máy tính"],"a":"Lặp lại một việc nhiều lần mà không cần xếp lại nhiều khối lệnh giống nhau","h":"Nhờ vòng lặp, chương trình của em ngắn gọn hơn.","e":"Vòng lặp giúp các lệnh bên trong được thực hiện lặp lại nhiều lần.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Để chương trình Scratch bắt đầu chạy khi em nháy chuột vào lá cờ xanh, em dùng nhóm khối lệnh nào?","o":["Khối lệnh sự kiện","Khối lệnh âm thanh","Khối lệnh hiển thị","Khối lệnh bút vẽ"],"a":"Khối lệnh sự kiện","h":"Nhóm khối lệnh này có khối lệnh bắt đầu bằng chữ Khi.","e":"Khối lệnh sự kiện Khi bấm vào lá cờ xanh giúp chương trình bắt đầu chạy.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em nhận được thư điện tử từ người lạ mời nhận quà và yêu cầu gửi thông tin cá nhân. Em nên làm gì?","o":["Không trả lời, không làm theo và báo cho người lớn","Gửi ngay thông tin cá nhân của mình","Nhờ bạn bè gửi thông tin giúp","Trả lời thư để hỏi thêm về quà"],"a":"Không trả lời, không làm theo và báo cho người lớn","h":"Thư lạ hứa tặng quà thường là bẫy lừa đảo.","e":"Thư lạ có thể là lừa đảo; em không cung cấp thông tin cá nhân và hãy báo cho người lớn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn bài trình chiếu sinh động hơn khi thuyết trình, em có thể thêm gì vào trang chiếu?","o":["Hiệu ứng cho chữ và hình ảnh","Xoá hết chữ trên trang chiếu","Chỉ để một trang trắng","Tắt loa của máy tính"],"a":"Hiệu ứng cho chữ và hình ảnh","h":"Điều này giúp chữ và hình xuất hiện bắt mắt hơn.","e":"Hiệu ứng giúp chữ và hình ảnh xuất hiện sinh động, thu hút người xem.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong soạn thảo văn bản, bảng (table) giúp em làm gì?","o":["Trình bày thông tin theo hàng và cột cho rõ ràng","Để nghe nhạc","Để vẽ hình tròn","Để đổi màu chữ"],"a":"Trình bày thông tin theo hàng và cột cho rõ ràng","h":"Hãy nghĩ đến thời khoá biểu được kẻ thành ô.","e":"Bảng giúp em sắp xếp thông tin thành hàng và cột, dễ đọc và dễ so sánh.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi tìm kiếm thông tin trên Internet, cách nào giúp em tìm được kết quả đúng và nhanh hơn?","o":["Dùng từ khoá cụ thể, sát với điều cần tìm","Dùng từ khoá thật chung chung","Gõ sai chính tả thật nhiều","Chỉ gõ một chữ cái duy nhất"],"a":"Dùng từ khoá cụ thể, sát với điều cần tìm","h":"Từ khoá càng rõ ràng, máy tìm kiếm càng hiểu đúng ý em.","e":"Từ khoá cụ thể giúp máy tìm kiếm lọc ra đúng thông tin em cần.","t":"tin-cap1","l":"thu-thach"},{"p":"Em muốn gửi kèm một bức ảnh vào thư điện tử cho bạn. Em cần dùng chức năng nào?","o":["Đính kèm tệp","Xoá thư","Chuyển tiếp thư","In thư ra giấy"],"a":"Đính kèm tệp","h":"Chức năng này thường có biểu tượng chiếc kẹp giấy.","e":"Chức năng đính kèm tệp cho phép em gửi ảnh và tài liệu cùng với thư.","t":"tin-cap1","l":"thu-thach"},{"p":"Trong Scratch, muốn nhân vật di chuyển tiến lên phía trước, em dùng khối lệnh nào?","o":["Khối lệnh di chuyển 10 bước","Khối lệnh nói Xin chào","Khối lệnh phát ra âm thanh","Khối lệnh đổi trang phục"],"a":"Khối lệnh di chuyển 10 bước","h":"Khối lệnh này nằm trong nhóm lệnh Chuyển động.","e":"Khối lệnh di chuyển giúp nhân vật tiến lên phía trước theo số bước em đặt.","t":"tin-cap1","l":"thu-thach"},{"p":"Vì sao em nên đối chiếu thông tin tìm được trên Internet từ nhiều nguồn khác nhau?","o":["Vì không phải thông tin nào trên mạng cũng đúng","Vì xem nhiều trang cho vui","Vì máy tính bắt buộc như vậy","Vì để mất nhiều thời gian hơn"],"a":"Vì không phải thông tin nào trên mạng cũng đúng","h":"Trên mạng có cả thông tin đúng và thông tin sai.","e":"Đối chiếu nhiều nguồn giúp em chọn được thông tin đáng tin cậy.","t":"tin-cap1","l":"thu-thach"},{"p":"Việc nào sau đây giúp em an toàn khi sử dụng mạng Internet?","o":["Không chia sẻ mật khẩu và thông tin cá nhân cho người lạ","Kết bạn rồi hẹn gặp mặt người lạ quen qua mạng","Tải mọi phần mềm lạ về máy","Gửi ảnh cá nhân cho người không quen biết"],"a":"Không chia sẻ mật khẩu và thông tin cá nhân cho người lạ","h":"Hãy giữ kín những thông tin riêng tư của mình.","e":"Giữ kín mật khẩu và thông tin cá nhân giúp em an toàn trên môi trường mạng.","t":"tin-cap1","l":"thu-thach"},{"p":"Em lập trình Scratch cho nhân vật vẽ hình vuông: lặp lại 4 lần hai việc di chuyển 100 bước và quay 90 độ. Cách xếp lệnh nào gọn và đúng nhất?","o":["Dùng khối lệnh lặp lại 4 lần chứa hai lệnh di chuyển và quay","Xếp 8 khối lệnh rời nhau giống hệt nhau","Dùng một khối lệnh chờ","Dùng khối lệnh phát âm thanh"],"a":"Dùng khối lệnh lặp lại 4 lần chứa hai lệnh di chuyển và quay","h":"Việc lặp đi lặp lại nhiều lần nên giao cho vòng lặp.","e":"Dùng vòng lặp 4 lần giúp chương trình ngắn gọn mà vẫn vẽ đúng hình vuông.","t":"tin-cap1","l":"kho"},{"p":"Phần mềm có bản quyền và phần mềm miễn phí khác nhau ở điểm nào?","o":["Phần mềm có bản quyền chỉ được dùng và sao chép khi được tác giả cho phép, còn phần mềm miễn phí được dùng miễn phí theo điều kiện của tác giả","Phần mềm miễn phí luôn tốt hơn phần mềm có bản quyền","Phần mềm có bản quyền thì không cần cài đặt","Cả hai loại đều được sao chép thoải mái"],"a":"Phần mềm có bản quyền chỉ được dùng và sao chép khi được tác giả cho phép, còn phần mềm miễn phí được dùng miễn phí theo điều kiện của tác giả","h":"Điểm khác nhau nằm ở quyền sử dụng và sao chép phần mềm.","e":"Dù miễn phí hay có bản quyền, em đều phải tôn trọng điều kiện sử dụng của tác giả phần mềm.","t":"tin-cap1","l":"kho"},{"p":"Thông tin là gì?","o":["Dữ liệu chưa được xử lí","Những hiểu biết của con người về một sự vật, sự kiện","Một thiết bị lưu trữ dữ liệu","Một chương trình máy tính"],"a":"Những hiểu biết của con người về một sự vật, sự kiện","h":"Thông tin gắn với sự hiểu biết của con người.","e":"Thông tin là những hiểu biết của con người về sự vật, sự kiện, thu nhận qua nghe, nhìn, đọc,...","t":"tin-cap1","l":"nhe-nhang"},{"p":"Đơn vị nhỏ nhất để biểu diễn thông tin trong máy tính là gì?","o":["Byte","Bit","KB","MB"],"a":"Bit","h":"Đơn vị này chỉ nhận một trong hai giá trị 0 hoặc 1.","e":"Bit là đơn vị nhỏ nhất biểu diễn thông tin trong máy tính, chỉ gồm kí hiệu 0 hoặc 1.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Một byte bằng bao nhiêu bit?","o":["2 bit","4 bit","8 bit","16 bit"],"a":"8 bit","h":"Hãy nhớ: 1 byte = 8 bit.","e":"Một byte gồm 8 bit và thường dùng để biểu diễn một kí tự.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Vật nào sau đây là thiết bị lưu trữ dữ liệu?","o":["Màn hình","Bàn phím","Thẻ nhớ USB","Loa"],"a":"Thẻ nhớ USB","h":"Thiết bị lưu trữ giúp giữ lại dữ liệu để dùng sau.","e":"Thẻ nhớ USB là thiết bị lưu trữ; màn hình là thiết bị ra, bàn phím là thiết bị vào, loa là thiết bị ra.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Mạng máy tính là gì?","o":["Một máy tính có cấu hình mạnh","Tập hợp các máy tính được kết nối với nhau để trao đổi thông tin và chia sẻ tài nguyên","Một chương trình diệt virus","Một loại cáp kết nối"],"a":"Tập hợp các máy tính được kết nối với nhau để trao đổi thông tin và chia sẻ tài nguyên","h":"Mạng gồm nhiều máy tính liên kết với nhau.","e":"Mạng máy tính là tập hợp các máy tính được kết nối để trao đổi thông tin và chia sẻ tài nguyên như máy in, dữ liệu.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Mạng LAN là loại mạng nào?","o":["Mạng diện rộng, kết nối các quốc gia","Mạng cục bộ, kết nối các máy tính trong phạm vi hẹp như một trường học hay cơ quan","Mạng không dây toàn cầu","Mạng của một nhà cung cấp dịch vụ Internet"],"a":"Mạng cục bộ, kết nối các máy tính trong phạm vi hẹp như một trường học hay cơ quan","h":"LAN viết tắt của Local Area Network.","e":"LAN là mạng cục bộ, phạm vi kết nối hẹp như trong một phòng, một tòa nhà hay một trường học.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong phần mềm soạn thảo văn bản, để in đậm đoạn chữ đã chọn, ta nhấn tổ hợp phím nào?","o":["Ctrl + I","Ctrl + U","Ctrl + B","Ctrl + S"],"a":"Ctrl + B","h":"B là viết tắt của Bold (đậm).","e":"Ctrl + B dùng để in đậm; Ctrl + I in nghiêng, Ctrl + U gạch chân, Ctrl + S lưu văn bản.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Thuật toán là gì?","o":["Một phần mềm soạn thảo văn bản","Dãy các bước rõ ràng, được sắp xếp theo trình tự để giải quyết một vấn đề","Một thiết bị của máy tính","Một trò chơi trên máy tính"],"a":"Dãy các bước rõ ràng, được sắp xếp theo trình tự để giải quyết một vấn đề","h":"Thuật toán giống như một bản hướng dẫn gồm từng bước.","e":"Thuật toán là dãy hữu hạn các bước rõ ràng, thực hiện theo trình tự để giải quyết một vấn đề.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Một KB (kilobyte) bằng bao nhiêu byte?","o":["100 byte","1000 byte","1024 byte","2048 byte"],"a":"1024 byte","h":"Các đơn vị dung lượng tăng theo bội số 1024.","e":"Theo quy ước trong tin học, 1 KB = 1024 byte, 1 MB = 1024 KB.","t":"tin-cap2","l":"thu-thach"},{"p":"Để chèn một bảng (table) vào văn bản, ta sử dụng lệnh trong thẻ (tab) nào?","o":["Home","Insert","Design","View"],"a":"Insert","h":"Insert nghĩa là 'chèn'.","e":"Lệnh Table nằm trong thẻ Insert, dùng để chèn bảng, hình ảnh, hình vẽ vào văn bản.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong sơ đồ khối mô tả thuật toán, hình thoi được dùng để biểu diễn bước nào?","o":["Bước bắt đầu, kết thúc","Bước nhập hoặc xuất dữ liệu","Bước kiểm tra điều kiện","Bước thực hiện phép tính"],"a":"Bước kiểm tra điều kiện","h":"Hình thoi là nơi thuật toán phải 'quyết định' đi đường nào.","e":"Trong sơ đồ khối, hình thoi biểu diễn bước kiểm tra điều kiện để rẽ nhánh; hình ô van là bắt đầu/kết thúc, hình bình hành là nhập/xuất.","t":"tin-cap2","l":"thu-thach"},{"p":"Điểm khác nhau cơ bản giữa mạng WAN và mạng LAN là gì?","o":["WAN dùng cáp, LAN không dùng cáp","WAN có phạm vi kết nối rộng hơn LAN, có thể giữa các thành phố, quốc gia","LAN nhanh hơn mọi mạng WAN trong mọi trường hợp","WAN chỉ gồm đúng hai máy tính"],"a":"WAN có phạm vi kết nối rộng hơn LAN, có thể giữa các thành phố, quốc gia","h":"So sánh về phạm vi địa lí của hai loại mạng.","e":"LAN là mạng cục bộ phạm vi hẹp; WAN là mạng diện rộng, kết nối các mạng LAN ở khoảng cách xa nhau.","t":"tin-cap2","l":"thu-thach"},{"p":"Một tệp ảnh có dung lượng 2 MB. Dung lượng đó bằng bao nhiêu KB?","o":["2000 KB","1024 KB","2048 KB","4096 KB"],"a":"2048 KB","h":"1 MB = 1024 KB, nhân lên với 2.","e":"1 MB = 1024 KB nên 2 MB = 2 × 1024 = 2048 KB.","t":"tin-cap2","l":"kho"},{"p":"Một thư mục chứa ba tệp có dung lượng lần lượt là 512 KB, 1 MB và 256 KB. Tổng dung lượng của thư mục là bao nhiêu KB?","o":["768 KB","1536 KB","1792 KB","2048 KB"],"a":"1792 KB","h":"Đổi 1 MB ra KB rồi cộng cả ba số lại.","e":"1 MB = 1024 KB, vậy tổng là 512 + 1024 + 256 = 1792 KB.","t":"tin-cap2","l":"kho"},{"p":"Thiết bị nào sau đây là thiết bị VÀO của máy tính?","o":["Màn hình","Bàn phím","Máy in","Loa"],"a":"Bàn phím","h":"Thiết bị vào giúp đưa thông tin vào máy tính.","e":"Bàn phím là thiết bị vào; màn hình, máy in và loa là các thiết bị ra.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Chức năng chính của hệ điều hành là gì?","o":["Soạn thảo văn bản","Quản lí và điều khiển mọi hoạt động của máy tính","Lướt web và xem phim","Diệt mọi loại virus"],"a":"Quản lí và điều khiển mọi hoạt động của máy tính","h":"Hệ điều hành là phần mềm nền tảng chạy đầu tiên khi mở máy.","e":"Hệ điều hành quản lí phần cứng, tổ chức lưu trữ dữ liệu và điều phối các chương trình khác hoạt động.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Windows là tên của phần mềm nào?","o":["Trình duyệt web","Hệ điều hành","Phần mềm bảng tính","Phần mềm diệt virus"],"a":"Hệ điều hành","h":"Đây là phần mềm của hãng Microsoft, rất phổ biến trên máy tính cá nhân.","e":"Windows là hệ điều hành thông dụng do Microsoft phát triển.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Địa chỉ ô A5 trong bảng tính có nghĩa là gì?","o":["Ô ở hàng A, cột 5","Ô ở cột A, hàng 5","Ô ở cột 5, hàng A","Ô thứ 5 của trang tính đầu tiên"],"a":"Ô ở cột A, hàng 5","h":"Địa chỉ ô viết theo dạng: chữ cái cột trước, số hàng sau.","e":"Địa chỉ ô gồm tên cột viết trước và số hàng viết sau, nên A5 là ô thuộc cột A, hàng 5.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong phần mềm bảng tính, một công thức luôn bắt đầu bằng kí tự nào?","o":["Dấu +","Dấu =","Dấu #","Dấu @"],"a":"Dấu =","h":"Đây là quy ước bắt buộc để phần mềm hiểu đó là công thức.","e":"Mọi công thức trong bảng tính đều bắt đầu bằng dấu =, sau đó là các toán hạng và phép toán.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Hàm SUM trong phần mềm bảng tính dùng để làm gì?","o":["Tính giá trị trung bình","Tính tổng các số","Tìm số lớn nhất","Đếm số ô có dữ liệu"],"a":"Tính tổng các số","h":"SUM trong tiếng Anh có nghĩa là 'tổng'.","e":"Hàm SUM dùng để tính tổng các giá trị số trong một vùng ô.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Hàm AVERAGE trong phần mềm bảng tính dùng để làm gì?","o":["Tính tổng các số","Tính giá trị trung bình cộng của các số","Tìm số nhỏ nhất","Sắp xếp dữ liệu"],"a":"Tính giá trị trung bình cộng của các số","h":"AVERAGE trong tiếng Anh có nghĩa là 'trung bình'.","e":"Hàm AVERAGE tính trung bình cộng của các giá trị trong vùng ô được chọn.","t":"tin-cap2","l":"thu-thach"},{"p":"Hành vi nào sau đây thể hiện ứng xử văn minh trên mạng xã hội?","o":["Chia sẻ ngay mọi tin tức giật gân chưa kiểm chứng","Dùng lời lẽ xúc phạm người khác khi tranh luận","Kiểm chứng thông tin trước khi chia sẻ và tôn trọng người khác","Đăng ảnh của bạn bè mà không cần hỏi ý kiến"],"a":"Kiểm chứng thông tin trước khi chia sẻ và tôn trọng người khác","h":"Hãy nghĩ về trách nhiệm của mình với mỗi bài đăng.","e":"Ứng xử văn minh trên mạng gồm: kiểm chứng thông tin, tôn trọng người khác và không phát tán tin giả.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong thuật toán, bước 'Nếu điểm kiểm tra từ 5 trở lên thì xếp loại Đạt, ngược lại xếp loại Chưa đạt' thuộc cấu trúc nào?","o":["Cấu trúc tuần tự","Cấu trúc rẽ nhánh","Cấu trúc lặp","Cấu trúc lưu trữ"],"a":"Cấu trúc rẽ nhánh","h":"Thuật toán phải chọn một trong hai hướng tùy theo điều kiện.","e":"Khi việc thực hiện bước tiếp theo phụ thuộc vào một điều kiện đúng hay sai, đó là cấu trúc rẽ nhánh.","t":"tin-cap2","l":"thu-thach"},{"p":"Thiết bị nào sau đây vừa là thiết bị vào, vừa là thiết bị ra?","o":["Chuột máy tính","Màn hình cảm ứng","Máy in","Bàn phím"],"a":"Màn hình cảm ứng","h":"Thiết bị này vừa hiển thị thông tin, vừa nhận lệnh chạm của người dùng.","e":"Màn hình cảm ứng vừa hiển thị thông tin (thiết bị ra) vừa nhận thao tác chạm để đưa lệnh vào (thiết bị vào).","t":"tin-cap2","l":"thu-thach"},{"p":"Trong bảng tính, giá trị của công thức =MAX(3, 7, 5) + MIN(3, 7, 5) là bao nhiêu?","o":["8","10","12","15"],"a":"10","h":"Tìm số lớn nhất và số nhỏ nhất trong ba số rồi cộng lại.","e":"MAX(3, 7, 5) = 7 và MIN(3, 7, 5) = 3, nên kết quả là 7 + 3 = 10.","t":"tin-cap2","l":"kho"},{"p":"Hàm IF trong phần mềm bảng tính dùng để làm gì?","o":["Tính tổng một vùng dữ liệu","Kiểm tra một điều kiện và trả về giá trị tương ứng với điều kiện đúng hoặc sai","Vẽ biểu đồ cho dữ liệu","Định dạng màu cho ô tính"],"a":"Kiểm tra một điều kiện và trả về giá trị tương ứng với điều kiện đúng hoặc sai","h":"IF trong tiếng Anh có nghĩa là 'nếu'.","e":"Hàm IF kiểm tra điều kiện: nếu điều kiện đúng thì trả về một giá trị, nếu sai thì trả về giá trị khác.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Biểu đồ cột thường được dùng với mục đích chính nào?","o":["Thể hiện tỉ lệ phần trăm của một tổng thể","So sánh dữ liệu giữa các đối tượng","Thể hiện sự thay đổi theo thời gian liên tục","Trang trí cho trang tính"],"a":"So sánh dữ liệu giữa các đối tượng","h":"Chiều cao của các cột giúp ta nhìn ra ngay đối tượng nào hơn kém nhau.","e":"Biểu đồ cột dùng để so sánh số liệu giữa các đối tượng; biểu đồ quạt tròn dùng để thể hiện tỉ lệ phần trăm.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Hành vi nào sau đây vi phạm bản quyền trong môi trường số?","o":["Mua phần mềm có bản quyền để sử dụng","Sao chép phần mềm có bản quyền rồi chia sẻ trái phép cho nhiều người","Trích dẫn một đoạn ngắn và ghi rõ nguồn","Sử dụng phần mềm miễn phí theo đúng giấy phép"],"a":"Sao chép phần mềm có bản quyền rồi chia sẻ trái phép cho nhiều người","h":"Hãy tôn trọng công sức và quyền của tác giả sản phẩm số.","e":"Sao chép, phát tán sản phẩm số có bản quyền khi chưa được phép là hành vi vi phạm bản quyền.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Chức năng sắp xếp (Sort) dữ liệu trong bảng tính có tác dụng gì?","o":["Xoá bớt các hàng không cần thiết","Sắp xếp các hàng theo thứ tự tăng dần hoặc giảm dần của một cột dữ liệu","Đổi màu nền của bảng dữ liệu","Tạo biểu đồ từ dữ liệu"],"a":"Sắp xếp các hàng theo thứ tự tăng dần hoặc giảm dần của một cột dữ liệu","h":"Ví dụ: xếp danh sách học sinh theo điểm từ cao xuống thấp.","e":"Sắp xếp dữ liệu là bố trí lại các hàng theo thứ tự tăng dần hoặc giảm dần dựa trên giá trị của một cột.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Chức năng lọc (Filter) dữ liệu trong bảng tính dùng để làm gì?","o":["Tính tổng toàn bộ dữ liệu","Chỉ hiển thị các hàng thoả mãn điều kiện đặt ra, tạm ẩn các hàng còn lại","Sao chép dữ liệu sang trang tính khác","In dữ liệu ra giấy"],"a":"Chỉ hiển thị các hàng thoả mãn điều kiện đặt ra, tạm ẩn các hàng còn lại","h":"Ví dụ: chỉ xem những học sinh có điểm Toán từ 8 trở lên.","e":"Lọc dữ liệu giúp chỉ hiển thị các hàng thoả mãn điều kiện, các hàng không thoả mãn sẽ tạm thời bị ẩn đi.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Hành vi nào sau đây thể hiện đạo đức tốt khi tham gia môi trường số?","o":["Đăng ảnh của người khác khi chưa được đồng ý","Tôn trọng quyền riêng tư của người khác và không phát tán thông tin cá nhân của họ","Dùng tài khoản giả để nói xấu bạn bè","Tải lậu phim và phần mềm để tiết kiệm tiền"],"a":"Tôn trọng quyền riêng tư của người khác và không phát tán thông tin cá nhân của họ","h":"Hãy đối xử với người khác trên mạng như ngoài đời thực.","e":"Tôn trọng quyền riêng tư, không tự ý đăng tải thông tin hay hình ảnh của người khác là biểu hiện của đạo đức số.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Ô B2 chứa công thức =IF(A2>=5, \"Đạt\", \"Chưa đạt\"). Nếu ô A2 có giá trị 7 thì ô B2 hiển thị kết quả gì?","o":["Chưa đạt","Đạt","7","Báo lỗi công thức"],"a":"Đạt","h":"Kiểm tra xem điều kiện A2>=5 đúng hay sai khi A2 bằng 7.","e":"Vì 7 >= 5 là điều kiện đúng nên hàm IF trả về giá trị 'Đạt'.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong Scratch, khối lệnh 'lặp lại 10 lần' (repeat 10) thuộc cấu trúc điều khiển nào?","o":["Cấu trúc tuần tự","Cấu trúc rẽ nhánh","Cấu trúc lặp","Cấu trúc gán"],"a":"Cấu trúc lặp","h":"Khối lệnh này thực hiện một nhóm lệnh nhiều lần.","e":"Khối 'lặp lại' cho phép thực hiện lặp đi lặp lại một nhóm lệnh, thuộc cấu trúc lặp.","t":"tin-cap2","l":"thu-thach"},{"p":"Trực quan hoá dữ liệu là gì?","o":["Nhập dữ liệu vào máy tính bằng bàn phím","Biểu diễn dữ liệu dưới dạng hình ảnh, biểu đồ để dễ quan sát, so sánh và hiểu","Xoá những dữ liệu không cần thiết","Sao lưu dữ liệu lên đám mây"],"a":"Biểu diễn dữ liệu dưới dạng hình ảnh, biểu đồ để dễ quan sát, so sánh và hiểu","h":"Một biểu đồ thường dễ hiểu hơn một bảng số dài.","e":"Trực quan hoá dữ liệu là dùng hình ảnh, biểu đồ để biểu diễn dữ liệu, giúp con người nắm bắt thông tin nhanh và rõ hơn.","t":"tin-cap2","l":"thu-thach"},{"p":"Khi sử dụng một bức ảnh tìm được trên Internet cho bài đăng của mình, việc làm nào là đúng?","o":["Cứ dùng thoải mái vì ảnh đã công khai trên mạng","Ghi rõ nguồn và tôn trọng bản quyền của tác giả","Xoá tên tác giả đi để tránh rắc rối","Bán lại bức ảnh đó cho người khác"],"a":"Ghi rõ nguồn và tôn trọng bản quyền của tác giả","h":"Ảnh trên mạng vẫn thuộc về tác giả của nó.","e":"Khi dùng tác phẩm của người khác cần tôn trọng bản quyền, ghi nguồn rõ ràng hoặc xin phép khi cần thiết.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong lập trình, biểu thức là gì?","o":["Một câu lệnh in kết quả ra màn hình","Tổ hợp các giá trị, biến và phép toán tạo ra một giá trị","Một loại nhân vật trong Scratch","Tên của một chương trình máy tính"],"a":"Tổ hợp các giá trị, biến và phép toán tạo ra một giá trị","h":"Ví dụ: (a + b) × 2 là một biểu thức.","e":"Biểu thức là sự kết hợp của các toán hạng (giá trị, biến) bằng các phép toán và cho ra một giá trị.","t":"tin-cap2","l":"thu-thach"},{"p":"Để đếm số học sinh có điểm từ 8 trở lên trong vùng điểm D2:D31 của bảng tính, ta nên dùng hàm nào?","o":["SUM","COUNTIF","AVERAGE","MAX"],"a":"COUNTIF","h":"Cần một hàm vừa đếm, vừa xét điều kiện 'từ 8 trở lên'.","e":"Hàm COUNTIF đếm số ô thoả mãn một điều kiện cho trước, ví dụ COUNTIF(D2:D31,\">=8\").","t":"tin-cap2","l":"kho"},{"p":"Trong Scratch, để nhân vật di chuyển liên tục cho đến khi chạm vào cạnh sân khấu mới dừng, ta nên dùng cấu trúc nào?","o":["Một lệnh di chuyển duy nhất","Vòng lặp cho đến khi điều kiện đúng (repeat until)","Câu lệnh rẽ nhánh một lần","Lệnh chờ (wait)"],"a":"Vòng lặp cho đến khi điều kiện đúng (repeat until)","h":"Việc di chuyển phải được kiểm tra điều kiện sau mỗi bước đi.","e":"Cấu trúc 'lặp cho đến khi' (repeat until) giúp lặp lại hành động và dừng lại khi điều kiện chạm cạnh được thoả mãn.","t":"tin-cap2","l":"kho"},{"p":"Trong ngôn ngữ lập trình Python, lệnh print() dùng để làm gì?","o":["Nhập dữ liệu từ bàn phím","Hiển thị thông tin ra màn hình","Lưu chương trình vào tệp","Dừng chương trình ngay lập tức"],"a":"Hiển thị thông tin ra màn hình","h":"print trong tiếng Anh có nghĩa là 'in ra'.","e":"Lệnh print() dùng để đưa thông tin, kết quả ra màn hình.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong Python, lệnh input() dùng để làm gì?","o":["In kết quả ra màn hình","Nhận dữ liệu do người dùng nhập vào từ bàn phím","Tạo một biến mới có giá trị bằng 0","Vẽ hình trên màn hình"],"a":"Nhận dữ liệu do người dùng nhập vào từ bàn phím","h":"input trong tiếng Anh có nghĩa là 'đầu vào'.","e":"Lệnh input() tạm dừng để người dùng nhập dữ liệu từ bàn phím và đưa vào chương trình.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong lập trình, biến được dùng để làm gì?","o":["Lưu trữ giá trị để chương trình sử dụng và thay đổi khi cần","Trang trí giao diện chương trình","Kết nối chương trình với Internet","Bảo vệ chương trình khỏi virus"],"a":"Lưu trữ giá trị để chương trình sử dụng và thay đổi khi cần","h":"Biến giống một chiếc hộp có nhãn, chứa một giá trị.","e":"Biến là vùng nhớ được đặt tên, dùng để lưu giá trị phục vụ quá trình xử lí của chương trình.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Mật khẩu mạnh nên có đặc điểm nào sau đây?","o":["Chỉ gồm ngày tháng năm sinh của mình","Dài, gồm chữ hoa, chữ thường, chữ số và kí tự đặc biệt","Giống với tên tài khoản đăng nhập","Càng ngắn càng dễ nhớ"],"a":"Dài, gồm chữ hoa, chữ thường, chữ số và kí tự đặc biệt","h":"Trộn nhiều loại kí tự khiến mật khẩu khó bị đoán hơn.","e":"Mật khẩu mạnh cần đủ dài, kết hợp chữ hoa, chữ thường, số và kí tự đặc biệt, tránh dùng thông tin cá nhân.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Cơ sở dữ liệu là gì?","o":["Một phần mềm soạn thảo văn bản","Tập hợp dữ liệu được tổ chức, lưu trữ có hệ thống để tiện quản lí và khai thác","Một thiết bị phần cứng của máy tính","Một loại mạng máy tính"],"a":"Tập hợp dữ liệu được tổ chức, lưu trữ có hệ thống để tiện quản lí và khai thác","h":"Ví dụ: dữ liệu học sinh của một trường được tổ chức thành các bảng.","e":"Cơ sở dữ liệu là tập hợp dữ liệu có liên quan, được tổ chức và lưu trữ một cách hệ thống phục vụ quản lí, tra cứu.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong một bảng dữ liệu (ví dụ bảng danh sách học sinh), mỗi hàng của bảng thường biểu diễn điều gì?","o":["Một trường dữ liệu","Một bản ghi về một đối tượng cụ thể","Toàn bộ cơ sở dữ liệu","Một cột dữ liệu"],"a":"Một bản ghi về một đối tượng cụ thể","h":"Mỗi hàng ứng với thông tin của đúng một học sinh.","e":"Trong bảng dữ liệu, mỗi hàng là một bản ghi (record) chứa thông tin về một đối tượng, mỗi cột là một trường dữ liệu.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Phần mềm mô phỏng được sử dụng chủ yếu để làm gì?","o":["Soạn thảo văn bản nhanh hơn","Mô hình hoá một hiện tượng hay quá trình để quan sát và thử nghiệm một cách an toàn","Diệt virus cho máy tính","Nén dữ liệu để tiết kiệm bộ nhớ"],"a":"Mô hình hoá một hiện tượng hay quá trình để quan sát và thử nghiệm một cách an toàn","h":"Ví dụ: mô phỏng lái máy bay giúp phi công tập luyện mà không gặp nguy hiểm thật.","e":"Phần mềm mô phỏng tái hiện hiện tượng, quá trình trên máy tính, giúp học tập và thử nghiệm an toàn, tiết kiệm.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Công việc nào sau đây thuộc lĩnh vực nghề nghiệp tin học?","o":["Lập trình viên phát triển phần mềm","Thợ sửa chữa ô tô","Đầu bếp nhà hàng","Kiến trúc sư xây dựng"],"a":"Lập trình viên phát triển phần mềm","h":"Hãy chọn nghề trực tiếp làm việc với phần mềm và máy tính.","e":"Lập trình viên là nghề tiêu biểu trong lĩnh vực tin học, cùng với các nghề như quản trị mạng, phân tích dữ liệu,...","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong Python, giá trị \"Xin chào\" thuộc kiểu dữ liệu nào?","o":["Số nguyên","Số thực","Chuỗi kí tự","Danh sách"],"a":"Chuỗi kí tự","h":"Giá trị này được đặt trong dấu ngoặc kép.","e":"Giá trị văn bản đặt trong dấu ngoặc đơn hoặc ngoặc kép thuộc kiểu chuỗi kí tự (str).","t":"tin-cap2","l":"thu-thach"},{"p":"Trong Python, phép toán 7 // 2 cho kết quả bằng bao nhiêu?","o":["3.5","3","2","1"],"a":"3","h":"Dấu // là phép chia lấy phần nguyên.","e":"Phép toán // chia lấy phần nguyên, 7 chia 2 được 3 dư 1 nên kết quả là 3.","t":"tin-cap2","l":"thu-thach"},{"p":"Dấu hiệu nào sau đây cho thấy một tin nhắn 'trúng thưởng' rất có thể là lừa đảo?","o":["Tin nhắn gửi từ số điện thoại của người thân","Yêu cầu bạn gửi mã OTP hoặc nộp một khoản tiền để được nhận quà","Tin nhắn chỉ thông báo mà không yêu cầu gì thêm","Tên đơn vị gửi tin được viết đúng chính tả"],"a":"Yêu cầu bạn gửi mã OTP hoặc nộp một khoản tiền để được nhận quà","h":"Không một giải thưởng thật nào bắt bạn nộp tiền hay lộ mã OTP.","e":"Kẻ lừa đảo thường yêu cầu nộp 'phí nhận thưởng' hoặc cung cấp mã OTP, mật khẩu — đây là dấu hiệu lừa đảo điển hình.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong bảng dữ liệu học sinh, các cột 'Họ và tên', 'Ngày sinh', 'Lớp' được gọi là gì?","o":["Các bản ghi","Các trường dữ liệu","Các bảng phụ","Các khoá chính"],"a":"Các trường dữ liệu","h":"Mỗi cột mô tả một thuộc tính của đối tượng.","e":"Mỗi cột trong bảng dữ liệu là một trường (field) mô tả một thuộc tính, ví dụ họ tên, ngày sinh, lớp.","t":"tin-cap2","l":"thu-thach"},{"p":"Vòng lặp for trong lập trình thường được sử dụng hiệu quả nhất trong trường hợp nào?","o":["Khi không thể biết chương trình sẽ chạy bao lâu","Khi biết trước số lần cần lặp lại công việc","Khi chỉ cần kiểm tra một điều kiện duy nhất","Khi muốn chương trình dừng ngay lập tức"],"a":"Khi biết trước số lần cần lặp lại công việc","h":"Ví dụ: in bảng cửu chương 5 đúng 10 dòng.","e":"Vòng lặp for phù hợp khi số lần lặp đã biết trước; vòng lặp while phù hợp khi lặp theo điều kiện.","t":"tin-cap2","l":"thu-thach"},{"p":"Cho đoạn chương trình Python: x = 5; x = x + 3; print(x). Chương trình in ra kết quả nào?","o":["5","3","8","x + 3"],"a":"8","h":"Hãy theo dõi giá trị của biến x qua từng lệnh.","e":"Ban đầu x = 5, lệnh x = x + 3 gán lại x = 5 + 3 = 8, nên print(x) in ra 8.","t":"tin-cap2","l":"kho"},{"p":"Ngoài việc đặt mật khẩu mạnh, biện pháp nào sau đây giúp bảo vệ tài khoản trực tuyến tốt nhất?","o":["Đăng nhập tài khoản trên càng nhiều máy càng tốt","Bật xác thực hai yếu tố cho tài khoản","Chia sẻ mật khẩu với bạn thân để nhờ giữ hộ","Tắt mọi thông báo đăng nhập lạ"],"a":"Bật xác thực hai yếu tố cho tài khoản","h":"Thêm một lớp bảo vệ ngoài mật khẩu, ví dụ mã gửi về điện thoại.","e":"Xác thực hai yếu tố thêm một lớp kiểm chứng ngoài mật khẩu, giúp tài khoản an toàn hơn nhiều kể cả khi lộ mật khẩu.","t":"tin-cap2","l":"kho"},{"p":"Trí tuệ nhân tạo (AI) là lĩnh vực khoa học máy tính nhằm giúp máy tính thực hiện được những công việc nào?","o":["Những công việc vốn cần đến trí thông minh của con người","Chỉ những công việc tính toán đơn giản","Việc in ấn tài liệu","Việc lưu trữ tệp tin"],"a":"Những công việc vốn cần đến trí thông minh của con người","h":"Nghĩ tới các việc như nhận diện giọng nói, hình ảnh, trò chuyện.","e":"AI hướng tới giúp máy thực hiện các công việc cần trí thông minh như con người: học, suy luận, nhận dạng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Ví dụ nào sau đây là ứng dụng của Internet vạn vật (IoT) trong đời sống?","o":["Đèn trong nhà được bật, tắt từ xa qua điện thoại","Máy tính để bàn dùng để soạn văn bản","Máy in phun mực in tài liệu","Ổ cứng di động để chép dữ liệu"],"a":"Đèn trong nhà được bật, tắt từ xa qua điện thoại","h":"IoT là các đồ vật kết nối Internet và điều khiển được từ xa.","e":"Đèn thông minh kết nối Internet, nhận lệnh từ điện thoại là một ứng dụng điển hình của IoT.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Dữ liệu lớn (Big Data) thường được nhắc đến với những đặc điểm nào?","o":["Khối lượng rất lớn, tốc độ tạo ra nhanh và dạng dữ liệu đa dạng","Chỉ gồm các con số trong một bảng tính","Luôn được lưu trên một máy tính duy nhất","Không cần qua xử lí vẫn dùng được ngay"],"a":"Khối lượng rất lớn, tốc độ tạo ra nhanh và dạng dữ liệu đa dạng","h":"Nhớ ba chữ V thường được nhắc tới: khối lượng, tốc độ, đa dạng.","e":"Dữ liệu lớn có khối lượng khổng lồ, sinh ra nhanh và đa dạng về dạng (văn bản, hình ảnh, video...).","t":"tin-cap3","l":"nhe-nhang"},{"p":"Mạng cục bộ (LAN) là mạng máy tính có phạm vi kết nối như thế nào?","o":["Trong một khu vực nhỏ như phòng học, văn phòng, cơ quan","Trên phạm vi toàn quốc","Trên phạm vi toàn thế giới","Giữa các châu lục với nhau"],"a":"Trong một khu vực nhỏ như phòng học, văn phòng, cơ quan","h":"Chữ L trong LAN là Local — cục bộ, phạm vi hẹp.","e":"LAN kết nối các máy tính trong phạm vi hẹp như một phòng, một toà nhà hay một cơ quan.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Địa chỉ IP trong mạng máy tính dùng để làm gì?","o":["Định danh một thiết bị khi tham gia vào mạng","Tăng tốc độ xử lí của máy tính","Lưu trữ dữ liệu cho người dùng","Dịch nội dung trang web sang tiếng Việt"],"a":"Định danh một thiết bị khi tham gia vào mạng","h":"Giống như số nhà để thư được gửi đến đúng nơi.","e":"Mỗi thiết bị tham gia mạng có một địa chỉ IP để các thiết bị khác nhận diện và gửi dữ liệu tới.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Hệ điều hành là phần mềm có vai trò gì?","o":["Quản lí, điều khiển phần cứng và làm nền cho các phần mềm khác hoạt động","Dùng để chơi trò chơi điện tử","Dùng để soạn thảo văn bản","Dùng để lướt web và xem video"],"a":"Quản lí, điều khiển phần cứng và làm nền cho các phần mềm khác hoạt động","h":"Windows, Android, iOS đều là các hệ điều hành quen thuộc.","e":"Hệ điều hành quản lí phần cứng, điều phối tài nguyên và tạo môi trường cho các phần mềm ứng dụng chạy.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong ngôn ngữ lập trình Python, để hiển thị kết quả ra màn hình ta dùng lệnh nào?","o":["print()","write()","show()","display()"],"a":"print()","h":"Lệnh này trong tiếng Anh có nghĩa là 'in ra'.","e":"Python dùng hàm print() để đưa dữ liệu ra màn hình.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Hành vi nào sau đây vi phạm bản quyền phần mềm?","o":["Sao chép, chia sẻ phần mềm có bản quyền khi chưa được chủ sở hữu cho phép","Mua phần mềm bản quyền để sử dụng","Dùng phần mềm mã nguồn mở theo đúng giấy phép của nó","Tự viết một phần mềm của riêng mình"],"a":"Sao chép, chia sẻ phần mềm có bản quyền khi chưa được chủ sở hữu cho phép","h":"Bản quyền là quyền của tác giả/chủ sở hữu đối với sản phẩm của họ.","e":"Sao chép và phát tán phần mềm có bản quyền trái phép là hành vi xâm phạm bản quyền.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Hệ thống tên miền DNS có nhiệm vụ chính là gì?","o":["Chuyển đổi tên miền thành địa chỉ IP tương ứng","Bảo vệ máy tính khỏi virus","Nén dữ liệu để truyền nhanh hơn","Tăng dung lượng cho ổ cứng"],"a":"Chuyển đổi tên miền thành địa chỉ IP tương ứng","h":"Nhờ DNS ta chỉ cần nhớ tên như google.com thay vì dãy số IP.","e":"DNS phân giải tên miền (dễ nhớ với con người) thành địa chỉ IP để máy tính kết nối đúng máy chủ.","t":"tin-cap3","l":"thu-thach"},{"p":"Cho đoạn chương trình Python: x = 5; x = x + 3; print(x). Màn hình sẽ hiển thị số nào?","o":["8","5","3","53"],"a":"8","h":"Giá trị của x được cập nhật: lấy x cũ cộng thêm 3.","e":"x ban đầu bằng 5, sau lệnh gán x = x + 3 thì x bằng 8 và được in ra.","t":"tin-cap3","l":"thu-thach"},{"p":"Giao thức trong mạng máy tính được hiểu là gì?","o":["Tập hợp các quy tắc mà các thiết bị tuân theo để trao đổi dữ liệu với nhau","Một loại cáp dùng để nối mạng","Tên gọi của một hãng sản xuất máy tính","Một phần mềm soạn thảo văn bản"],"a":"Tập hợp các quy tắc mà các thiết bị tuân theo để trao đổi dữ liệu với nhau","h":"Giống như hai người muốn nói chuyện thì phải chung một 'luật' giao tiếp.","e":"Giao thức là tập hợp quy tắc, quy ước về định dạng và cách truyền dữ liệu giữa các thiết bị trong mạng.","t":"tin-cap3","l":"thu-thach"},{"p":"Phát biểu nào sau đây đúng về Internet vạn vật (IoT)?","o":["Các đồ vật được gắn cảm biến, kết nối Internet để thu thập và trao đổi dữ liệu","IoT chỉ áp dụng cho máy tính để bàn","IoT hoạt động mà không cần kết nối mạng","IoT là tên một trò chơi trực tuyến nhiều người chơi"],"a":"Các đồ vật được gắn cảm biến, kết nối Internet để thu thập và trao đổi dữ liệu","h":"Hãy nghĩ tới đồng hồ thông minh, camera, nhà thông minh.","e":"IoT kết nối các đồ vật có cảm biến qua Internet để chúng thu thập, trao đổi dữ liệu và phục vụ con người.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong Python, câu lệnh rẽ nhánh (điều kiện) bắt đầu bằng từ khoá nào?","o":["if","when","check","case"],"a":"if","h":"Từ khoá này trong tiếng Anh có nghĩa là 'nếu'.","e":"Python dùng từ khoá if để bắt đầu câu lệnh điều kiện, kèm theo else/elif khi cần.","t":"tin-cap3","l":"thu-thach"},{"p":"Cho đoạn chương trình Python: s = 0; for i in range(1, 5): s = s + i; print(s). Kết quả in ra là bao nhiêu?","o":["10","6","15","4"],"a":"10","h":"Vòng lặp cho i chạy qua các số 1, 2, 3, 4 và cộng dồn vào s.","e":"s = 1 + 2 + 3 + 4 = 10 (range(1, 5) cho các giá trị 1 đến 4).","t":"tin-cap3","l":"kho"},{"p":"Khi một trang web sử dụng giao thức HTTPS thay vì HTTP, điểm khác biệt chính là gì?","o":["Dữ liệu truyền đi được mã hoá nên an toàn hơn","Trang web luôn tải nhanh hơn trong mọi trường hợp","Người dùng không cần mật khẩu khi đăng nhập","Trang web được truy cập hoàn toàn miễn phí"],"a":"Dữ liệu truyền đi được mã hoá nên an toàn hơn","h":"Chữ S trong HTTPS là Secure — an toàn.","e":"HTTPS bổ sung khả năng mã hoá đường truyền, giúp dữ liệu trao đổi giữa người dùng và máy chủ an toàn hơn HTTP.","t":"tin-cap3","l":"kho"},{"p":"Cơ sở dữ liệu (CSDL) là gì?","o":["Tập hợp dữ liệu có liên quan với nhau, được tổ chức và lưu trữ để phục vụ khai thác, quản lí","Một phần mềm dùng để soạn thảo văn bản","Một thiết bị dùng để lưu trữ dữ liệu","Một ngôn ngữ lập trình phổ biến"],"a":"Tập hợp dữ liệu có liên quan với nhau, được tổ chức và lưu trữ để phục vụ khai thác, quản lí","h":"Ví dụ: dữ liệu học sinh của một trường được tổ chức thành các bảng liên quan.","e":"CSDL là tập hợp dữ liệu có liên quan, được tổ chức theo cấu trúc nhất định để lưu trữ và khai thác hiệu quả.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong một bảng dữ liệu của CSDL, mỗi hàng (dòng) của bảng được gọi là gì?","o":["Bản ghi","Trường","Khoá chính","Tệp dữ liệu"],"a":"Bản ghi","h":"Mỗi hàng chứa thông tin về một đối tượng cụ thể, ví dụ một học sinh.","e":"Mỗi hàng trong bảng là một bản ghi, lưu thông tin đầy đủ về một đối tượng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Khoá chính của một bảng dữ liệu có vai trò gì?","o":["Giúp phân biệt các bản ghi với nhau, mỗi bản ghi có giá trị khoá chính riêng","Giúp sắp xếp các bản ghi theo thứ tự bảng chữ cái","Giúp tô màu cho bảng dữ liệu đẹp hơn","Giúp xoá bỏ các dữ liệu không cần thiết"],"a":"Giúp phân biệt các bản ghi với nhau, mỗi bản ghi có giá trị khoá chính riêng","h":"Ví dụ: mã học sinh — mỗi học sinh có một mã duy nhất.","e":"Khoá chính gồm một hoặc một số trường mà giá trị của chúng xác định duy nhất mỗi bản ghi trong bảng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Microsoft Access là phần mềm thuộc loại nào?","o":["Hệ quản trị cơ sở dữ liệu","Trình duyệt web","Phần mềm chỉnh sửa ảnh","Hệ điều hành"],"a":"Hệ quản trị cơ sở dữ liệu","h":"Đây là phần mềm của Microsoft dùng để tạo và quản lí các bảng dữ liệu.","e":"Access là hệ quản trị CSDL phổ biến, cho phép tạo bảng, truy vấn, biểu mẫu và báo cáo.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong Python, một danh sách (list) được viết trong cặp dấu nào?","o":["Dấu ngoặc vuông [ ]","Dấu ngoặc tròn ( )","Dấu ngoặc nhọn { }","Dấu nháy kép \" \""],"a":"Dấu ngoặc vuông [ ]","h":"Ví dụ: diem = [8, 9, 10].","e":"Danh sách trong Python được khai báo bằng cặp dấu ngoặc vuông, các phần tử cách nhau bởi dấu phẩy.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Để định nghĩa một hàm trong Python, ta dùng từ khoá nào?","o":["def","func","function","proc"],"a":"def","h":"Từ khoá này viết tắt của 'define' — định nghĩa.","e":"Python dùng từ khoá def để khai báo hàm, theo sau là tên hàm và các tham số.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Việc đặt mật khẩu mạnh và thường xuyên cập nhật phần mềm đem lại lợi ích gì?","o":["Giúp tăng tính an toàn, bảo mật cho dữ liệu và tài khoản","Giúp máy tính chạy nhanh gấp đôi","Giúp màn hình hiển thị sáng hơn","Giúp tăng dung lượng ổ cứng miễn phí"],"a":"Giúp tăng tính an toàn, bảo mật cho dữ liệu và tài khoản","h":"Mật khẩu dễ đoán và phần mềm lỗi thời là cửa ngõ cho kẻ xấu.","e":"Mật khẩu mạnh khó bị dò đoán; cập nhật phần mềm giúp vá các lỗ hổng bảo mật đã biết.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Công việc nào sau đây thuộc lĩnh vực tin học?","o":["Lập trình viên phát triển phần mềm","Kĩ sư xây dựng cầu đường","Bác sĩ khám chữa bệnh","Đầu bếp nhà hàng"],"a":"Lập trình viên phát triển phần mềm","h":"Hãy chọn công việc gắn trực tiếp với máy tính và phần mềm.","e":"Lập trình viên là nghề tiêu biểu trong lĩnh vực công nghệ thông tin/tin học.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong ngôn ngữ truy vấn SQL, câu lệnh SELECT dùng để làm gì?","o":["Truy xuất (lấy) dữ liệu từ các bảng trong CSDL","Xoá hẳn một bảng dữ liệu","Tạo tài khoản người dùng mới","Sao lưu toàn bộ CSDL ra ổ cứng"],"a":"Truy xuất (lấy) dữ liệu từ các bảng trong CSDL","h":"SELECT trong tiếng Anh có nghĩa là 'chọn/lấy ra'.","e":"SELECT là câu lệnh dùng để chọn và lấy ra những dữ liệu cần thiết từ một hay nhiều bảng.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong bảng dữ liệu, 'trường' (field) được hiểu là gì?","o":["Một cột của bảng, thể hiện một thuộc tính của đối tượng","Một hàng của bảng dữ liệu","Toàn bộ bảng dữ liệu","Một tệp tin chứa dữ liệu"],"a":"Một cột của bảng, thể hiện một thuộc tính của đối tượng","h":"Ví dụ bảng Học sinh có các cột: Họ tên, Ngày sinh, Lớp...","e":"Mỗi cột của bảng là một trường, lưu một thuộc tính chung của tất cả các đối tượng trong bảng.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong Python, biểu thức len(\"Tin hoc\") cho kết quả bằng bao nhiêu?","o":["7","6","8","5"],"a":"7","h":"Hãy đếm từng kí tự trong chuỗi, kể cả dấu cách.","e":"Chuỗi \"Tin hoc\" gồm 7 kí tự: T, i, n, dấu cách, h, o, c.","t":"tin-cap3","l":"thu-thach"},{"p":"Thao tác 'lọc dữ liệu' trong CSDL có nghĩa là gì?","o":["Chọn ra những bản ghi thoả mãn một điều kiện nào đó","Xoá toàn bộ dữ liệu của bảng","In toàn bộ bảng ra giấy","Đổi tên cho bảng dữ liệu"],"a":"Chọn ra những bản ghi thoả mãn một điều kiện nào đó","h":"Ví dụ: chỉ hiện những học sinh có điểm trung bình từ 8 trở lên.","e":"Lọc dữ liệu là hiển thị/chọn ra các bản ghi đáp ứng điều kiện đặt ra, ví dụ điểm ≥ 8.","t":"tin-cap3","l":"thu-thach"},{"p":"Hệ quản trị cơ sở dữ liệu (HQTCSDL) là phần mềm dùng để làm gì?","o":["Tạo lập, lưu trữ, cập nhật và khai thác CSDL","Soạn thảo văn bản và trình chiếu","Nghe nhạc và xem phim","Lướt web và gửi thư điện tử"],"a":"Tạo lập, lưu trữ, cập nhật và khai thác CSDL","h":"Access, MySQL, SQL Server là những ví dụ của loại phần mềm này.","e":"HQTCSDL là phần mềm giúp người dùng tạo lập CSDL, thêm/sửa/xoá dữ liệu và truy vấn khai thác thông tin.","t":"tin-cap3","l":"thu-thach"},{"p":"Cho đoạn chương trình Python: a = [2, 4, 6]; a.append(8); print(len(a)). Kết quả in ra là bao nhiêu?","o":["4","3","5","8"],"a":"4","h":"append() thêm một phần tử vào cuối danh sách.","e":"Danh sách ban đầu có 3 phần tử, thêm số 8 thành 4 phần tử nên len(a) bằng 4.","t":"tin-cap3","l":"kho"},{"p":"Câu truy vấn: SELECT * FROM HOCSINH WHERE Diem >= 8 có tác dụng gì?","o":["Lấy mọi thông tin của những học sinh có điểm từ 8 trở lên","Xoá những học sinh có điểm dưới 8","Sắp xếp học sinh theo thứ tự điểm giảm dần","Thêm một học sinh mới vào bảng"],"a":"Lấy mọi thông tin của những học sinh có điểm từ 8 trở lên","h":"Chú ý mệnh đề WHERE — đó là điều kiện chọn bản ghi.","e":"SELECT * lấy tất cả các trường; WHERE Diem >= 8 chỉ giữ lại các bản ghi có điểm từ 8 trở lên.","t":"tin-cap3","l":"kho"},{"p":"Học máy (Machine Learning) là cách tiếp cận trong đó máy tính làm gì?","o":["Tự học từ dữ liệu để thực hiện nhiệm vụ tốt dần lên mà không cần lập trình chi tiết từng bước","Được con người viết sẵn mọi tình huống có thể xảy ra","Chỉ biết lưu trữ dữ liệu mà không xử lí","Hoạt động hoàn toàn không cần dữ liệu"],"a":"Tự học từ dữ liệu để thực hiện nhiệm vụ tốt dần lên mà không cần lập trình chi tiết từng bước","h":"Ví dụ: cho máy xem nhiều ảnh mèo, máy dần tự nhận ra mèo.","e":"Học máy cho phép máy tính rút ra quy luật từ dữ liệu mẫu để dự đoán, phân loại các dữ liệu mới.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Mã độc (phần mềm độc hại) có thể lây nhiễm vào máy tính qua con đường nào?","o":["Tệp đính kèm lạ, phần mềm không rõ nguồn gốc, USB đã nhiễm độc","Việc gõ bàn phím thường xuyên","Việc tắt máy đúng quy trình","Việc dùng chuột và màn hình chính hãng"],"a":"Tệp đính kèm lạ, phần mềm không rõ nguồn gốc, USB đã nhiễm độc","h":"Hãy cảnh giác với những tệp không rõ nguồn gốc được gửi tới.","e":"Mã độc thường ẩn trong tệp đính kèm lạ, phần mềm bẻ khoá/không rõ nguồn và thiết bị lưu trữ nhiễm độc.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Ứng dụng nào sau đây có sử dụng trí tuệ nhân tạo?","o":["Trợ lí ảo trên điện thoại nhận diện giọng nói để trả lời câu hỏi","Chiếc bút bi thông thường dùng để viết","Đồng hồ cơ đeo tay lên dây cót","Chiếc xe đạp không có thiết bị điện tử"],"a":"Trợ lí ảo trên điện thoại nhận diện giọng nói để trả lời câu hỏi","h":"Ứng dụng AI thường 'nghe, hiểu' hoặc 'nhìn, nhận biết' được.","e":"Trợ lí ảo dùng AI để nhận dạng tiếng nói và hiểu ngôn ngữ tự nhiên của người dùng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong bệnh viện, cơ sở dữ liệu được ứng dụng chủ yếu để làm gì?","o":["Lưu trữ và tra cứu hồ sơ bệnh án của bệnh nhân","Trang trí phòng khám cho đẹp hơn","Thay thế hoàn toàn bác sĩ trong khám bệnh","In hoá đơn bán thuốc lá lẻ"],"a":"Lưu trữ và tra cứu hồ sơ bệnh án của bệnh nhân","h":"Nhờ CSDL, bác sĩ xem lại được tiền sử bệnh của bệnh nhân rất nhanh.","e":"CSDL giúp bệnh viện quản lí hồ sơ bệnh án, lịch khám, kết quả xét nghiệm một cách khoa học và tra cứu nhanh.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Khi sử dụng mạng xã hội, hành vi nào thể hiện văn hoá số đúng đắn?","o":["Kiểm chứng thông tin trước khi chia sẻ cho người khác","Chia sẻ ngay mọi tin giật gân chưa rõ đúng sai","Bình luận xúc phạm người không cùng quan điểm","Đăng công khai thông tin cá nhân của người khác"],"a":"Kiểm chứng thông tin trước khi chia sẻ cho người khác","h":"Tin giả lan nhanh phần lớn do người dùng chia sẻ vội vàng.","e":"Người dùng văn minh cần kiểm chứng nguồn tin, tránh lan truyền tin giả gây hại cho cộng đồng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Phát biểu nào sau đây đúng về hạn chế của trí tuệ nhân tạo hiện nay?","o":["AI chưa thể thay thế hoàn toàn con người trong các công việc cần cảm xúc, kinh nghiệm sống và sáng tạo sâu sắc","AI luôn cho kết quả đúng tuyệt đối trong mọi trường hợp","AI hoạt động không cần bất kì dữ liệu nào","AI hiểu được mọi ngôn ngữ và văn hoá như con người"],"a":"AI chưa thể thay thế hoàn toàn con người trong các công việc cần cảm xúc, kinh nghiệm sống và sáng tạo sâu sắc","h":"AI rất mạnh ở xử lí dữ liệu nhưng còn yếu ở cảm xúc và kinh nghiệm sống.","e":"AI hiện nay mạnh trong các nhiệm vụ có dữ liệu rõ ràng, nhưng còn hạn chế về cảm xúc, kinh nghiệm và phán đoán như con người.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Xác thực hai yếu tố (mật khẩu kèm mã xác nhận gửi về điện thoại) giúp ích gì cho tài khoản trực tuyến?","o":["Tăng độ an toàn, kẻ xấu biết mật khẩu vẫn khó đăng nhập được","Giúp đăng nhập nhanh hơn không cần thao tác gì thêm","Giúp tài khoản không bao giờ bị quên mật khẩu","Giúp tăng dung lượng lưu trữ của tài khoản"],"a":"Tăng độ an toàn, kẻ xấu biết mật khẩu vẫn khó đăng nhập được","h":"Đây là thêm một 'lớp khoá' nữa ngoài mật khẩu.","e":"Xác thực hai yếu tố buộc người đăng nhập có thêm mã xác nhận, nên tài khoản an toàn hơn hẳn.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Người làm việc trong lĩnh vực tin học cần có phẩm chất nào sau đây?","o":["Tư duy logic, cẩn thận và luôn ham học hỏi công nghệ mới","Chỉ cần thuộc lòng một ngôn ngữ lập trình là đủ","Không cần làm việc nhóm hay giao tiếp với ai","Ngại thay đổi, chỉ dùng những gì đã quen"],"a":"Tư duy logic, cẩn thận và luôn ham học hỏi công nghệ mới","h":"Công nghệ thay đổi rất nhanh nên người làm tin học phải liên tục cập nhật.","e":"Tư duy logic, tính cẩn thận và tinh thần tự học là những phẩm chất quan trọng của nghề tin học.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Điểm khác biệt cơ bản giữa học máy và lập trình truyền thống là gì?","o":["Học máy để máy tự rút ra quy luật từ dữ liệu, còn lập trình truyền thống do con người viết sẵn mọi quy tắc","Học máy không dùng đến máy tính","Lập trình truyền thống luôn cho kết quả nhanh hơn học máy","Học máy chỉ dùng cho trò chơi điện tử"],"a":"Học máy để máy tự rút ra quy luật từ dữ liệu, còn lập trình truyền thống do con người viết sẵn mọi quy tắc","h":"Một bên 'dạy bằng ví dụ', một bên 'viết luật chi tiết'.","e":"Trong lập trình truyền thống, con người định sẵn quy tắc; trong học máy, mô hình tự học quy luật từ dữ liệu mẫu.","t":"tin-cap3","l":"thu-thach"},{"p":"'Phần mềm độc hại' (malware) là tên gọi chung cho các chương trình như thế nào?","o":["Được tạo ra với mục đích xấu như đánh cắp dữ liệu, phá hoại hoặc chiếm quyền điều khiển hệ thống","Được cài sẵn theo máy để hỗ trợ người dùng","Dùng để tăng tốc độ mạng cho máy tính","Dùng để sao lưu dữ liệu an toàn"],"a":"Được tạo ra với mục đích xấu như đánh cắp dữ liệu, phá hoại hoặc chiếm quyền điều khiển hệ thống","h":"Virus, sâu máy tính, mã độc tống tiền đều thuộc nhóm này.","e":"Malware là các chương trình có hại như virus, worm, trojan, ransomware... gây tổn hại cho hệ thống và người dùng.","t":"tin-cap3","l":"thu-thach"},{"p":"Biện pháp nào sau đây giúp phòng tránh mã độc hiệu quả?","o":["Cài phần mềm diệt virus, cập nhật hệ điều hành và không mở tệp, đường liên kết lạ","Tắt mọi phần mềm bảo vệ để máy chạy nhẹ hơn","Mở thử mọi tệp đính kèm để kiểm tra nội dung","Dùng chung một mật khẩu đơn giản cho mọi tài khoản"],"a":"Cài phần mềm diệt virus, cập nhật hệ điều hành và không mở tệp, đường liên kết lạ","h":"Phòng bệnh hơn chữa bệnh — hãy nghĩ tới các thói quen an toàn hằng ngày.","e":"Kết hợp phần mềm diệt virus, cập nhật bản vá và thận trọng với tệp/link lạ là cách phòng tránh mã độc hiệu quả.","t":"tin-cap3","l":"thu-thach"},{"p":"Khi sử dụng kết quả do AI tạo ra (bài viết, hình ảnh), trách nhiệm của người dùng là gì?","o":["Kiểm tra lại độ tin cậy của kết quả và chịu trách nhiệm về nội dung mình sử dụng, chia sẻ","Cứ dùng và chia sẻ ngay vì AI luôn đúng","Không cần quan tâm vì lỗi là do AI chịu trách nhiệm","Chỉ cần ghi nguồn 'do AI làm' là đủ mọi trách nhiệm"],"a":"Kiểm tra lại độ tin cậy của kết quả và chịu trách nhiệm về nội dung mình sử dụng, chia sẻ","h":"AI có thể tạo ra thông tin sai trông rất thuyết phục.","e":"Kết quả AI có thể sai hoặc bịa đặt; người dùng phải kiểm chứng và chịu trách nhiệm về nội dung mình dùng.","t":"tin-cap3","l":"thu-thach"},{"p":"Việc ứng dụng cơ sở dữ liệu trong ngân hàng đem lại lợi ích gì nổi bật?","o":["Quản lí thông tin khách hàng, tài khoản và giao dịch chính xác, tra cứu nhanh chóng","Giúp ngân hàng không cần nhân viên nữa","Giúp khách hàng không cần nhớ số tài khoản khi giao dịch ở nhà","Tự động tăng số tiền trong tài khoản khách hàng"],"a":"Quản lí thông tin khách hàng, tài khoản và giao dịch chính xác, tra cứu nhanh chóng","h":"Mỗi ngày ngân hàng xử lí hàng triệu giao dịch — không thể quản lí bằng giấy tờ.","e":"CSDL giúp ngân hàng lưu trữ và xử lí lượng lớn dữ liệu khách hàng, giao dịch một cách chính xác, an toàn và tức thời.","t":"tin-cap3","l":"thu-thach"},{"p":"Một mô hình AI được huấn luyện gần như chỉ bằng ảnh mèo. Khi đưa ảnh chó vào, nó phân loại rất kém. Hiện tượng này cho thấy điều gì?","o":["Chất lượng của mô hình học máy phụ thuộc nhiều vào dữ liệu dùng để huấn luyện","Máy tính bị hỏng phần cứng","AI có thể tự hiểu mọi loài vật mà không cần học","Dữ liệu huấn luyện không ảnh hưởng gì tới kết quả của AI"],"a":"Chất lượng của mô hình học máy phụ thuộc nhiều vào dữ liệu dùng để huấn luyện","h":"Máy chỉ 'biết' những gì đã được học từ dữ liệu.","e":"Mô hình học máy chỉ làm tốt với dữ liệu tương tự dữ liệu huấn luyện; dữ liệu thiếu đa dạng khiến kết quả kém.","t":"tin-cap3","l":"kho"},{"p":"Bạn nhận được thư điện tử lạ giả danh ngân hàng, yêu cầu bấm vào đường liên kết để 'xác minh tài khoản kẻo bị khoá'. Cách xử lí đúng nhất là gì?","o":["Không bấm vào liên kết; tự truy cập trang web chính thức của ngân hàng hoặc gọi tổng đài để kiểm tra","Bấm ngay vào liên kết và nhập mật khẩu cho kịp thời hạn","Chuyển tiếp thư cho bạn bè để mọi người cùng xác minh","Trả lời thư và hỏi lại người gửi có phải ngân hàng thật không"],"a":"Không bấm vào liên kết; tự truy cập trang web chính thức của ngân hàng hoặc gọi tổng đài để kiểm tra","h":"Đây là chiêu lừa đảo 'phishing' rất phổ biến nhằm đánh cắp tài khoản.","e":"Thư giả mạo ngân hàng là hình thức lừa đảo phổ biến; cần liên hệ ngân hàng qua kênh chính thức thay vì làm theo liên kết trong thư.","t":"tin-cap3","l":"kho"},{"p":"Em nghe dự báo thời tiết trên tivi nói chiều nay trời sẽ mưa. Để không bị ướt khi đi học về, em nên làm gì?","o":["Mang theo áo mưa hoặc ô","Mặc thêm áo ấm thật dày","Mang theo quạt cầm tay","Đội mũ lưỡi trai"],"a":"Mang theo áo mưa hoặc ô","h":"Thông tin nghe được sẽ giúp em quyết định mang theo thứ gì cho phù hợp.","e":"Thông tin từ dự báo thời tiết giúp em quyết định mang áo mưa hoặc ô để không bị ướt.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em biết được tin 'ngày mai lớp mình được nghỉ học' là nhờ đâu?","o":["Nghe thầy cô thông báo","Tự đoán trong đầu","Nhìn lên bầu trời","Ngủ mơ thấy"],"a":"Nghe thầy cô thông báo","h":"Ai là người thông báo tin tức của lớp cho em?","e":"Em nhận được thông tin về việc nghỉ học khi nghe thầy cô thông báo.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Mỗi ngày em nghe thầy cô giảng bài, nhìn tranh ảnh và đọc sách. Những điều em thu nhận được như vậy gọi là gì?","o":["Thông tin","Đồ dùng học tập","Trò chơi","Bài tập về nhà"],"a":"Thông tin","h":"Nhờ nghe, nhìn và đọc, em biết thêm nhiều điều mới.","e":"Những gì em thu nhận được qua nghe, nhìn, đọc giúp em hiểu biết về xung quanh được gọi là thông tin.","t":"tin-cap1","l":"thu-thach"},{"p":"Người lái xe nhìn thấy đèn giao thông chuyển sang màu đỏ thì dừng xe lại. Thông tin giúp người lái xe quyết định dừng xe là gì?","o":["Màu đỏ của đèn giao thông","Tiếng còi xe phía sau","Màu sơn của chiếc xe","Số người trên vỉa hè"],"a":"Màu đỏ của đèn giao thông","h":"Người lái xe nhìn thấy điều gì trên cột đèn giao thông?","e":"Đèn đỏ là thông tin báo hiệu phải dừng xe, giúp người lái xe ra quyết định đúng.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi em gõ phím chữ A trên bàn phím, điều gì xảy ra?","o":["Chữ A hiện trên màn hình","Máy tính tự tắt","Chuột tự di chuyển","Loa phát ra nhạc"],"a":"Chữ A hiện trên màn hình","h":"Em hãy nhớ lại mỗi lần gõ phím khi soạn thảo.","e":"Em gõ phím là đưa thông tin vào, máy tính xử lí và cho kết quả là chữ hiện trên màn hình.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em nháy chuột và gõ phím để ra lệnh cho máy tính làm việc. Đó là bước nào trong cách máy tính làm việc?","o":["Đưa thông tin vào máy tính","Máy tính cho ra kết quả","Máy tính đang nghỉ","Tắt máy tính"],"a":"Đưa thông tin vào máy tính","h":"Chuột và bàn phím giúp em gửi lệnh vào trong máy.","e":"Nháy chuột và gõ phím là cách em đưa thông tin, ra lệnh cho máy tính.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Máy tính được coi là đang xử lí thông tin khi nào?","o":["Khi máy tính thực hiện lệnh, tính toán theo yêu cầu của em","Khi máy tính đã tắt hẳn","Khi màn hình bị tối đen","Khi em rời khỏi phòng máy"],"a":"Khi máy tính thực hiện lệnh, tính toán theo yêu cầu của em","h":"Việc xử lí diễn ra sau khi máy nhận được lệnh của em.","e":"Sau khi nhận thông tin vào, máy tính xử lí bằng cách thực hiện lệnh và tính toán để cho ra kết quả.","t":"tin-cap1","l":"thu-thach"},{"p":"Em chọn bài hát yêu thích trên máy tính, loa phát ra tiếng nhạc. Tiếng nhạc từ loa là gì?","o":["Kết quả sau khi máy tính xử lí thông tin","Thông tin em đưa vào","Lệnh em gõ từ bàn phím","Một phần mềm vẽ tranh"],"a":"Kết quả sau khi máy tính xử lí thông tin","h":"Việc chọn bài hát là đưa vào, vậy tiếng nhạc phát ra thuộc bước cuối nào?","e":"Em chọn bài hát là đưa thông tin vào, máy tính xử lí và loa phát ra tiếng nhạc chính là kết quả.","t":"tin-cap1","l":"thu-thach"},{"p":"Máy tính xử lí thông tin theo đúng thứ tự nào?","o":["Nhận thông tin → Xử lí → Cho ra kết quả","Cho ra kết quả → Nhận thông tin → Xử lí","Xử lí → Cho ra kết quả → Nhận thông tin","Nhận thông tin → Cho ra kết quả → Xử lí"],"a":"Nhận thông tin → Xử lí → Cho ra kết quả","h":"Máy phải nhận được lệnh trước, rồi mới làm việc và cho kết quả.","e":"Máy tính luôn làm việc theo ba bước: nhận thông tin vào, xử lí, rồi cho ra kết quả.","t":"tin-cap1","l":"kho"},{"p":"Thiết bị số nào sau đây có thể xử lí thông tin như một chiếc máy tính nhỏ?","o":["Điện thoại thông minh","Chiếc quạt điện","Đèn bàn học","Cái gương soi"],"a":"Điện thoại thông minh","h":"Thiết bị nào có màn hình, chạy được phần mềm và nối mạng được?","e":"Điện thoại thông minh là thiết bị số có khả năng xử lí thông tin, chạy phần mềm giống như máy tính.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Đồng hồ thông minh khác đồng hồ thường ở điểm nào?","o":["Có thể xử lí thông tin, kết nối với điện thoại và hiện nhiều thông tin hơn","Chỉ khác ở màu của dây đeo","Có kim đồng hồ to hơn","Không cần đeo vào tay"],"a":"Có thể xử lí thông tin, kết nối với điện thoại và hiện nhiều thông tin hơn","h":"Chữ 'thông minh' cho thấy chiếc đồng hồ làm được thêm việc gì?","e":"Đồng hồ thông minh có thể xử lí thông tin như đếm bước chân, hiện thông báo và kết nối với điện thoại.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Máy tính bảng và điện thoại thông minh giống nhau ở điểm nào?","o":["Đều có màn hình cảm ứng và xử lí được thông tin","Đều chỉ dùng để gọi điện","Đều không cần sạc pin","Đều to bằng chiếc tivi"],"a":"Đều có màn hình cảm ứng và xử lí được thông tin","h":"Em thao tác trên hai thiết bị này bằng cách chạm tay vào đâu?","e":"Cả máy tính bảng và điện thoại thông minh đều có màn hình cảm ứng và khả năng xử lí thông tin.","t":"tin-cap1","l":"thu-thach"},{"p":"Tivi thông minh (Smart TV) làm được việc gì mà tivi thường khó làm được?","o":["Kết nối Internet để xem phim, video trực tuyến","Tự nấu cơm cho em","Phát ra mùi thơm","Tự di chuyển ra sân"],"a":"Kết nối Internet để xem phim, video trực tuyến","h":"Nhờ kết nối mạng, tivi thông minh xem thêm được những gì?","e":"Tivi thông minh kết nối được Internet nên xem được phim và video trực tuyến theo yêu cầu.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Để chọn và mở các đối tượng trên màn hình, em thường dùng nút chuột nào?","o":["Nút chuột trái","Nút chuột phải","Con lăn chuột","Cả thân chuột"],"a":"Nút chuột trái","h":"Hầu hết thao tác nháy chuột đều dùng nút ở phía bên trái.","e":"Nút chuột trái là nút được dùng phổ biến nhất để chọn và mở đối tượng.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Con lăn (bánh xe cuộn) trên chuột dùng để làm gì?","o":["Cuộn trang lên hoặc xuống","Tắt máy tính","Tăng âm lượng loa","Đổi màu con trỏ chuột"],"a":"Cuộn trang lên hoặc xuống","h":"Khi đọc một trang dài, em lăn bánh xe này để xem tiếp nội dung.","e":"Con lăn chuột giúp em cuộn nội dung trang lên hoặc xuống một cách nhanh chóng.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Phím dài nhất trên bàn phím (phím Space) dùng để làm gì?","o":["Tạo dấu cách giữa các từ","Xoá chữ vừa gõ","Xuống dòng mới","Tắt màn hình"],"a":"Tạo dấu cách giữa các từ","h":"Giữa hai từ trong một câu luôn có một khoảng trống.","e":"Phím Space dùng để tạo khoảng cách (dấu cách) giữa các từ khi gõ văn bản.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em vừa gõ nhầm một chữ ở ngay trước con trỏ soạn thảo. Nhấn phím nào để xoá chữ đó?","o":["Phím Backspace","Phím Enter","Phím Shift","Phím Space"],"a":"Phím Backspace","h":"Có một phím chuyên dùng để xoá chữ ở phía bên trái con trỏ.","e":"Phím Backspace xoá kí tự ở phía bên trái con trỏ soạn thảo.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi gõ một bài thơ, muốn chuyển xuống dòng mới em nhấn phím nào?","o":["Phím Enter","Phím Backspace","Phím Shift","Con lăn chuột"],"a":"Phím Enter","h":"Đây là phím quen thuộc dùng để xuống dòng và thực hiện lệnh.","e":"Phím Enter dùng để xuống dòng khi soạn thảo và để thực hiện một lệnh.","t":"tin-cap1","l":"thu-thach"},{"p":"Em giữ phím Shift rồi gõ phím chữ a. Kết quả trên màn hình sẽ là gì?","o":["Chữ A in hoa","Chữ a thường","Số 1","Một dấu cách"],"a":"Chữ A in hoa","h":"Phím Shift giúp đổi chữ thường thành dạng chữ nào?","e":"Giữ phím Shift trong khi gõ phím chữ sẽ cho ra chữ in hoa tương ứng.","t":"tin-cap1","l":"kho"},{"p":"Trong phần mềm Paint, muốn tô kín một hình bằng một màu, em dùng công cụ nào?","o":["Công cụ đổ màu (thùng sơn)","Công cụ tẩy","Công cụ bút chì","Công cụ viết chữ"],"a":"Công cụ đổ màu (thùng sơn)","h":"Công cụ này có hình chiếc thùng đang nghiêng đổ sơn.","e":"Công cụ đổ màu (Fill with color) giúp tô kín một vùng hình bằng màu đã chọn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Vẽ xong bức tranh trong Paint, muốn giữ lại để lần sau xem tiếp, em phải làm gì?","o":["Lưu bức tranh vào máy tính","Tắt luôn máy tính","Đóng phần mềm mà không lưu","In thật nhiều bản ra giấy"],"a":"Lưu bức tranh vào máy tính","h":"Nếu không làm việc này, bức tranh sẽ bị mất khi em đóng phần mềm.","e":"Em cần lưu (Save) bức tranh vào máy tính thì lần sau mới mở ra xem và sửa tiếp được.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn vẽ một hình tròn trong Paint, em chọn công cụ hình nào?","o":["Công cụ hình bầu dục (Oval)","Công cụ đường thẳng","Công cụ hình chữ nhật","Công cụ ngôi sao"],"a":"Công cụ hình bầu dục (Oval)","h":"Hình tròn là một dạng đặc biệt của hình bầu dục.","e":"Trong Paint, công cụ hình bầu dục (Oval) dùng để vẽ hình tròn và hình bầu dục.","t":"tin-cap1","l":"thu-thach"},{"p":"Em vẽ sai một nét trong Paint và muốn xoá riêng nét đó. Em dùng công cụ nào?","o":["Công cụ tẩy (Eraser)","Công cụ đổ màu","Công cụ kính lúp","Công cụ bút vẽ"],"a":"Công cụ tẩy (Eraser)","h":"Công cụ này giống như cục tẩy em vẫn dùng trên giấy.","e":"Công cụ tẩy (Eraser) giúp xoá những nét vẽ sai trong bức tranh.","t":"tin-cap1","l":"thu-thach"},{"p":"Muốn vẽ một đường thẳng thật thẳng trong Paint, cách nào sau đây là đúng?","o":["Chọn công cụ đường thẳng rồi kéo chuột","Vẽ tự do bằng bút chì thật nhanh","Dùng công cụ đổ màu","Nhấn phím Enter nhiều lần"],"a":"Chọn công cụ đường thẳng rồi kéo chuột","h":"Paint có sẵn một công cụ chuyên dùng để kẻ thẳng.","e":"Công cụ đường thẳng (Line) giúp em kẻ được đường thẳng đẹp, chỉ cần chọn công cụ rồi kéo chuột.","t":"tin-cap1","l":"kho"},{"p":"Khi ngồi học với máy tính, mắt em nên cách màn hình khoảng bao nhiêu là hợp lí?","o":["Khoảng 50 đến 70 cm","Khoảng 10 cm","Càng sát màn hình càng tốt","Khoảng 3 mét"],"a":"Khoảng 50 đến 70 cm","h":"Khoảng cách này áng chừng bằng độ dài một cánh tay của em.","e":"Giữ mắt cách màn hình khoảng 50–70 cm giúp mắt đỡ mỏi và bảo vệ thị lực.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Dùng máy tính liên tục khoảng 20 – 30 phút, em nên làm gì để bảo vệ mắt?","o":["Nghỉ giải lao, đứng dậy vận động và nhìn ra xa","Tiếp tục dùng thêm cho xong việc","Nhìn chằm chằm vào màn hình lâu hơn","Tắt hết đèn phòng cho tối"],"a":"Nghỉ giải lao, đứng dậy vận động và nhìn ra xa","h":"Đôi mắt cũng cần được nghỉ ngơi như cơ thể em vậy.","e":"Sau 20–30 phút dùng máy tính, em nên nghỉ giải lao, nhìn ra xa và vận động nhẹ để mắt được thư giãn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Tay em đang ướt, em có nên tự cắm phích điện của máy tính vào ổ điện không?","o":["Không, vì nước dẫn điện rất nguy hiểm","Có, miễn là cắm thật nhanh","Có, nếu em đứng trên ghế gỗ","Có, nếu chỉ cắm bằng một tay"],"a":"Không, vì nước dẫn điện rất nguy hiểm","h":"Nước kết hợp với điện sẽ gây ra điều gì nguy hiểm?","e":"Tay ướt chạm vào ổ điện có thể bị điện giật, rất nguy hiểm; em phải lau khô tay và nhờ người lớn giúp.","t":"tin-cap1","l":"thu-thach"},{"p":"Phòng học máy tính nên có ánh sáng như thế nào để tốt cho mắt?","o":["Đủ sáng, không quá tối và không để ánh nắng chói thẳng vào màn hình","Tối om để nhìn màn hình cho rõ","Chỉ cần bật mỗi màn hình máy tính","Ánh sáng càng chói càng tốt"],"a":"Đủ sáng, không quá tối và không để ánh nắng chói thẳng vào màn hình","h":"Ánh sáng thế nào thì em nhìn vừa rõ mà không bị chói, mỏi mắt?","e":"Ánh sáng đủ, đều và không chói vào màn hình giúp em nhìn rõ và bảo vệ mắt.","t":"tin-cap1","l":"thu-thach"},{"p":"Em phát hiện dây điện của máy tính bị hở, tróc vỏ, nhìn thấy lõi đồng bên trong. Việc làm đúng là gì?","o":["Không chạm vào dây điện, báo ngay cho thầy cô hoặc người lớn","Cầm sợi dây lên xem cho rõ","Tự lấy băng dính quấn lại rồi dùng tiếp","Giật mạnh sợi dây để rút phích điện ra"],"a":"Không chạm vào dây điện, báo ngay cho thầy cô hoặc người lớn","h":"Dây điện bị hở rất nguy hiểm, em tuyệt đối không được tự ý chạm vào.","e":"Dây điện bị hở có thể gây điện giật; em không chạm vào và phải báo ngay cho người lớn xử lí.","t":"tin-cap1","l":"kho"},{"p":"Màn hình máy tính quá sáng khiến em bị chói và mỏi mắt. Em nên làm gì?","o":["Nhờ thầy cô hoặc người lớn chỉnh lại độ sáng màn hình cho vừa","Dí mắt sát vào màn hình hơn","Nhắm mắt lại rồi gõ tiếp","Lấy tay che hết màn hình"],"a":"Nhờ thầy cô hoặc người lớn chỉnh lại độ sáng màn hình cho vừa","h":"Độ sáng của màn hình hoàn toàn có thể chỉnh lại cho phù hợp với mắt.","e":"Em nên nhờ người lớn chỉnh độ sáng màn hình vừa phải để bảo vệ mắt khi học.","t":"tin-cap1","l":"kho"},{"p":"Thiết bị nào giúp em nghe âm thanh từ máy tính mà không làm phiền người xung quanh?","o":["Tai nghe","Loa ngoài","Máy in","Webcam"],"a":"Tai nghe","h":"Thiết bị này em đeo lên tai khi nghe.","e":"Tai nghe phát âm thanh chỉ cho riêng em nghe nên không làm phiền người khác.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Máy in là thiết bị dùng để làm gì?","o":["In văn bản và hình ảnh từ máy tính ra giấy","Thu hình ảnh của em vào máy tính","Lưu trữ dữ liệu để mang đi","Phát âm thanh to hơn"],"a":"In văn bản và hình ảnh từ máy tính ra giấy","h":"Sau khi dùng thiết bị này, em cầm được tờ giấy có chữ và hình.","e":"Máy in chuyển văn bản, hình ảnh trong máy tính thành bản in trên giấy.","t":"tin-cap1","l":"nhe-nhang"},{"p":"USB (thiết bị nhớ USB) thường được dùng để làm gì?","o":["Lưu trữ và mang dữ liệu từ máy tính này sang máy tính khác","Làm mát cho máy tính","Kết nối chuột với máy tính","Chiếu hình lên tường"],"a":"Lưu trữ và mang dữ liệu từ máy tính này sang máy tính khác","h":"Em cắm thiết bị nhỏ này vào máy tính để chép tệp mang đi.","e":"USB là thiết bị lưu trữ nhỏ gọn, giúp lưu và chuyển dữ liệu giữa các máy tính.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi học trực tuyến, webcam giúp em làm việc gì?","o":["Thu hình ảnh của em để thầy cô và bạn bè nhìn thấy","In bài tập ra giấy","Gõ chữ nhanh hơn","Nghe nhạc hay hơn"],"a":"Thu hình ảnh của em để thầy cô và bạn bè nhìn thấy","h":"Thầy cô nhìn thấy hình ảnh của em qua thiết bị nào?","e":"Webcam thu hình ảnh của em và gửi đi, giúp thầy cô và bạn bè nhìn thấy em khi học trực tuyến.","t":"tin-cap1","l":"thu-thach"},{"p":"Chuột không dây khác chuột có dây ở điểm nào?","o":["Kết nối với máy tính bằng sóng, không cần dây nối","Không bao giờ cần pin hay sạc","Chỉ dùng được trên mặt kính","To hơn gấp đôi chuột có dây"],"a":"Kết nối với máy tính bằng sóng, không cần dây nối","h":"Tên gọi 'không dây' nói lên cách con chuột này kết nối với máy tính.","e":"Chuột không dây kết nối với máy tính qua sóng (thông qua đầu thu USB) nên không bị vướng dây nối.","t":"tin-cap1","l":"thu-thach"},{"p":"Các máy tính trong phòng Tin học được nối với nhau để chia sẻ thông tin và dùng chung máy in. Cách kết nối các máy tính như vậy tạo thành gì?","o":["Mạng máy tính","Một phần mềm vẽ tranh","Một chiếc máy tính lớn","Hệ thống loa của trường"],"a":"Mạng máy tính","h":"Nhiều máy tính nối lại với nhau để chia sẻ thì tạo thành một 'mạng'.","e":"Nhiều máy tính kết nối với nhau để trao đổi thông tin và dùng chung thiết bị tạo thành mạng máy tính.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Nhờ có mạng máy tính của trường, các máy tính trong phòng Tin học có thể cùng dùng chung thiết bị nào sau đây?","o":["Máy in","Bàn ghế","Bảng viết","Quạt trần"],"a":"Máy in","h":"Thiết bị nào chỉ cần một cái là đủ cho cả phòng máy cùng dùng?","e":"Nhờ mạng máy tính, nhiều máy trong phòng có thể cùng gửi lệnh in tới một máy in chung.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi em đổi tên một tệp trong máy tính, nội dung bên trong tệp sẽ thế nào?","o":["Vẫn giữ nguyên, chỉ có tên tệp thay đổi","Bị xoá hết","Tự động nhân đôi thành hai tệp","Chuyển thành một tệp hoàn toàn khác"],"a":"Vẫn giữ nguyên, chỉ có tên tệp thay đổi","h":"Đổi tên chỉ thay đổi cách gọi tệp, không đụng tới phần bên trong.","e":"Đổi tên tệp chỉ thay đổi tên gọi; nội dung của tệp vẫn được giữ nguyên.","t":"tin-cap1","l":"thu-thach"},{"p":"Máy tính của em chưa được kết nối mạng. Em KHÔNG thể làm được việc nào sau đây?","o":["Truy cập Internet để tìm thông tin","Soạn thảo một bài văn","Vẽ tranh bằng phần mềm Paint","Chơi trò chơi đã cài sẵn trong máy"],"a":"Truy cập Internet để tìm thông tin","h":"Việc nào bắt buộc phải có kết nối mạng mới làm được?","e":"Truy cập Internet để tìm thông tin cần máy tính có kết nối mạng; các việc còn lại làm được ngay trên máy.","t":"tin-cap1","l":"kho"},{"p":"Muốn gõ toàn chữ IN HOA trong một đoạn dài mà không phải giữ phím liên tục, em bật phím nào?","o":["Phím Caps Lock","Phím Enter","Phím Backspace","Phím Space"],"a":"Phím Caps Lock","h":"Khi bật phím này, trên bàn phím thường có một đèn nhỏ sáng lên.","e":"Bật Caps Lock giúp em gõ liên tục toàn chữ in hoa mà không cần giữ phím Shift.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Để tiêu đề của bài văn nằm chính giữa trang giấy, em chọn lệnh căn lề nào?","o":["Căn giữa","Căn trái","Căn phải","Không cần căn gì cả"],"a":"Căn giữa","h":"Tiêu đề thường đứng ở vị trí nào trên trang cho cân đối?","e":"Lệnh căn giữa giúp dòng tiêu đề nằm chính giữa trang, trông cân đối và đẹp mắt.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn chèn một bức tranh vào bài văn đang soạn thảo, em dùng lệnh nào?","o":["Lệnh chèn hình ảnh (Insert Picture)","Lệnh lưu văn bản","Lệnh căn giữa","Lệnh in văn bản"],"a":"Lệnh chèn hình ảnh (Insert Picture)","h":"Trong phần mềm soạn thảo có một lệnh chuyên để đưa hình vào văn bản.","e":"Em dùng lệnh chèn hình ảnh trong phần mềm soạn thảo rồi chọn bức tranh cần chèn vào vị trí mong muốn.","t":"tin-cap1","l":"thu-thach"},{"p":"Em đã bôi đen (chọn) một đoạn văn bản bị thừa. Nhấn phím nào để xoá đoạn văn đó?","o":["Phím Delete","Phím Enter","Phím Caps Lock","Phím Shift"],"a":"Phím Delete","h":"Có một phím mang tên Delete chuyên dùng để xoá phần đã chọn.","e":"Sau khi chọn đoạn văn, nhấn phím Delete (hoặc Backspace) sẽ xoá đoạn văn đó.","t":"tin-cap1","l":"thu-thach"},{"p":"Em vừa xoá nhầm một đoạn văn quan trọng. Tổ hợp phím nào giúp em khôi phục lại thao tác vừa làm (hoàn tác)?","o":["Ctrl + Z","Ctrl + C","Ctrl + V","Ctrl + A"],"a":"Ctrl + Z","h":"Tổ hợp phím hoàn tác quen thuộc là Ctrl kết hợp với phím Z.","e":"Tổ hợp phím Ctrl + Z là lệnh hoàn tác, giúp khôi phục lại thao tác vừa làm sai.","t":"tin-cap1","l":"kho"},{"p":"Muốn chép một đoạn văn sang vị trí khác mà đoạn văn gốc vẫn giữ nguyên, em làm thế nào?","o":["Chọn đoạn văn, dùng lệnh Sao chép (Copy) rồi Dán (Paste) vào vị trí mới","Cắt đoạn văn rồi dán sang chỗ mới","Gõ lại toàn bộ đoạn văn bằng tay","Xoá đoạn văn rồi cố nhớ lại"],"a":"Chọn đoạn văn, dùng lệnh Sao chép (Copy) rồi Dán (Paste) vào vị trí mới","h":"Lệnh nào tạo thêm một bản giống hệt mà không làm mất bản gốc?","e":"Lệnh Sao chép (Copy) tạo một bản sao của đoạn văn, sau đó Dán (Paste) vào vị trí mới, đoạn gốc vẫn còn nguyên.","t":"tin-cap1","l":"kho"},{"p":"Muốn có thêm một trang chiếu mới trong bài trình chiếu, em dùng lệnh nào?","o":["Lệnh thêm trang chiếu mới (New Slide)","Lệnh xoá trang chiếu","Lệnh lưu bài trình chiếu","Lệnh thoát phần mềm"],"a":"Lệnh thêm trang chiếu mới (New Slide)","h":"Tên lệnh này trong tiếng Anh có nghĩa là 'trang chiếu mới'.","e":"Lệnh New Slide giúp em thêm một trang chiếu mới vào bài trình chiếu.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Để bài trình chiếu đẹp và đồng nhất, em có thể chọn sẵn những gì trong phần mềm?","o":["Các mẫu nền (mẫu thiết kế) có sẵn","Các bài hát có sẵn","Các trò chơi có sẵn","Các hình ảnh lạ trên mạng"],"a":"Các mẫu nền (mẫu thiết kế) có sẵn","h":"Phần mềm đã chuẩn bị sẵn các bộ nền trang trí cho em chọn.","e":"Phần mềm trình chiếu có sẵn nhiều mẫu nền (theme) giúp bài trình chiếu đẹp và thống nhất.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Một trang chiếu trong bài bị thừa, em muốn xoá bỏ. Cách làm đúng là gì?","o":["Chọn trang chiếu đó rồi dùng lệnh xoá trang (Delete Slide)","Đóng phần mềm lại ngay","Xoá hết chữ trong trang đó","Tắt máy tính rồi mở lại"],"a":"Chọn trang chiếu đó rồi dùng lệnh xoá trang (Delete Slide)","h":"Em thao tác trên khung danh sách các trang ở bên trái màn hình.","e":"Em chọn trang chiếu cần bỏ trong danh sách trang rồi dùng lệnh xoá trang để loại bỏ nó khỏi bài.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi làm trang chiếu để cả lớp cùng xem, chữ trên trang nên như thế nào?","o":["Chữ to, ít chữ, rõ ràng dễ đọc","Chữ thật nhỏ để chứa được nhiều nội dung","Chữ kín cả trang, không chừa khoảng trống","Chữ màu nhạt trên nền cũng nhạt"],"a":"Chữ to, ít chữ, rõ ràng dễ đọc","h":"Bạn ngồi ở cuối lớp cũng cần đọc được chữ trên màn chiếu.","e":"Trang chiếu nên có chữ to, ngắn gọn và rõ ràng để mọi người dễ đọc và nắm ý chính.","t":"tin-cap1","l":"thu-thach"},{"p":"Muốn bắt đầu trình chiếu toàn màn hình từ trang đầu tiên, em nhấn phím nào?","o":["Phím F5","Phím Enter","Phím Space","Phím Esc"],"a":"Phím F5","h":"Đây là một phím chức năng nằm ở hàng trên cùng của bàn phím.","e":"Nhấn phím F5 để bắt đầu trình chiếu toàn màn hình từ trang chiếu đầu tiên.","t":"tin-cap1","l":"kho"},{"p":"Trình duyệt web là phần mềm dùng để làm gì?","o":["Mở và xem các trang web trên Internet","Vẽ tranh trên máy tính","Nghe nhạc trong máy tính","Dọn dẹp rác cho máy tính"],"a":"Mở và xem các trang web trên Internet","h":"Cốc Cốc và Google Chrome là ví dụ của loại phần mềm này.","e":"Trình duyệt web là phần mềm giúp em truy cập và xem các trang web trên Internet.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Một trang web là gì?","o":["Một trang thông tin trên Internet, có địa chỉ riêng để truy cập","Một tờ giấy trong vở của em","Một phần mềm vẽ tranh","Tên của chiếc máy tính"],"a":"Một trang thông tin trên Internet, có địa chỉ riêng để truy cập","h":"Em mở trang này bằng trình duyệt để đọc thông tin.","e":"Trang web là trang thông tin trên Internet, mỗi trang có một địa chỉ riêng để em truy cập bằng trình duyệt.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Địa chỉ của một trang web có tác dụng gì?","o":["Giúp trình duyệt tìm và mở đúng trang web em cần","Làm cho máy tính chạy nhanh hơn","Trang trí cho trang web đẹp hơn","Thay thế cho mật khẩu đăng nhập"],"a":"Giúp trình duyệt tìm và mở đúng trang web em cần","h":"Giống như địa chỉ nhà giúp em tìm đến đúng ngôi nhà cần tìm.","e":"Địa chỉ trang web cho trình duyệt biết cần tìm và mở trang nào trên Internet.","t":"tin-cap1","l":"thu-thach"},{"p":"Trên trang web, siêu liên kết (đường liên kết) là gì?","o":["Chữ hoặc hình ảnh mà khi nháy chuột vào sẽ đưa em tới nội dung khác","Một loại dây cáp mạng","Tên người viết ra trang web","Mật khẩu của trang web"],"a":"Chữ hoặc hình ảnh mà khi nháy chuột vào sẽ đưa em tới nội dung khác","h":"Đó thường là dòng chữ có màu khác, bấm vào là chuyển sang nội dung khác.","e":"Siêu liên kết là chữ hoặc hình trên trang web; nháy vào đó, trình duyệt sẽ chuyển em tới một trang hay nội dung khác.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn đến một trang web bằng địa chỉ của nó, em gõ địa chỉ vào đâu trong trình duyệt?","o":["Ô địa chỉ (thanh địa chỉ) ở phía trên cửa sổ trình duyệt","Bất kì chỗ nào ở giữa trang web","Trong phần mềm soạn thảo văn bản","Trên màn hình nền của máy tính"],"a":"Ô địa chỉ (thanh địa chỉ) ở phía trên cửa sổ trình duyệt","h":"Đó là ô dài nằm ở trên cùng của cửa sổ trình duyệt.","e":"Em gõ địa chỉ trang web vào ô địa chỉ của trình duyệt rồi nhấn Enter để mở trang.","t":"tin-cap1","l":"thu-thach"},{"p":"Em thấy một bộ phim hay nhưng trang web lạ bắt tải phim về từ nguồn không rõ ràng. Việc làm đúng là gì?","o":["Không tải về, chỉ xem ở nơi được phép và hỏi ý kiến người lớn","Tải ngay về cho nhanh","Nhờ bạn tải hộ vào máy của mình","Tắt phần mềm bảo vệ máy rồi tải"],"a":"Không tải về, chỉ xem ở nơi được phép và hỏi ý kiến người lớn","h":"Tải phim từ nguồn lạ vừa vi phạm bản quyền vừa dễ dính phần mềm độc hại.","e":"Em không nên tải phim từ nguồn lạ; hãy xem ở nơi được phép và hỏi ý kiến người lớn để bảo đảm an toàn và tôn trọng bản quyền.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Một quảng cáo lạ bật lên báo em 'trúng thưởng điện thoại, hãy bấm vào ngay'. Em nên làm gì?","o":["Không bấm vào, đóng quảng cáo lại","Bấm vào ngay kẻo mất quà","Nhập số điện thoại để nhận thưởng","Gọi bạn đến bấm thử thay mình"],"a":"Không bấm vào, đóng quảng cáo lại","h":"Quà tặng bất ngờ trong quảng cáo lạ thường là bẫy lừa đảo.","e":"Quảng cáo trúng thưởng bất ngờ thường là lừa đảo; em không bấm vào mà đóng quảng cáo lại, nếu lo lắng hãy kể cho người lớn nghe.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em muốn tải một phần mềm học tập mới về máy tính. Việc làm đúng là gì?","o":["Xin phép và nhờ người lớn tải cùng từ trang web chính thức của phần mềm","Tự tải từ bất kì trang nào hiện ra đầu tiên","Tải từ trang lạ có rất nhiều quảng cáo","Mượn chiếc USB lạ chép phần mềm vào máy"],"a":"Xin phép và nhờ người lớn tải cùng từ trang web chính thức của phần mềm","h":"Nguồn tải chính thức và có người lớn cùng kiểm tra sẽ an toàn nhất.","e":"Em cần xin phép người lớn và tải phần mềm từ trang chính thức để tránh phần mềm độc hại.","t":"tin-cap1","l":"thu-thach"},{"p":"Bạn em rủ tải nhạc và phim lậu (không được phép phát hành miễn phí) để xem cho 'đỡ tốn tiền'. Việc làm đó là gì?","o":["Vi phạm bản quyền, không nên làm","Việc làm thông minh, nên làm theo","Chỉ sai khi bị người khác phát hiện","Không sao vì rất nhiều người cũng làm thế"],"a":"Vi phạm bản quyền, không nên làm","h":"Phim và nhạc là sản phẩm có bản quyền của người sáng tạo ra chúng.","e":"Tải và dùng phim, nhạc lậu là vi phạm bản quyền của tác giả nên em không nên làm.","t":"tin-cap1","l":"thu-thach"},{"p":"Một trang web lạ yêu cầu em nhập họ tên, địa chỉ nhà và số điện thoại của bố mẹ để nhận quà miễn phí. Em nên làm gì?","o":["Không nhập thông tin, đóng trang web và kể lại cho người lớn nghe","Nhập đầy đủ thông tin để nhận quà","Chỉ nhập tên giả còn địa chỉ thì nhập thật","Nhờ bạn nhập thông tin của bạn ấy thay mình"],"a":"Không nhập thông tin, đóng trang web và kể lại cho người lớn nghe","h":"Thông tin cá nhân và gia đình phải được giữ kín trước người lạ trên mạng.","e":"Em tuyệt đối không cung cấp thông tin cá nhân, gia đình cho trang web lạ; hãy đóng trang và báo cho người lớn.","t":"tin-cap1","l":"kho"},{"p":"Trong Scratch, biến được dùng để làm gì?","o":["Lưu trữ một giá trị có thể thay đổi trong khi chương trình chạy","Vẽ hình cho nhân vật","Phát ra âm thanh cho chương trình","Đổi màu cho sân khấu"],"a":"Lưu trữ một giá trị có thể thay đổi trong khi chương trình chạy","h":"Nghĩ tới biến Điểm trong trò chơi.","e":"Biến là nơi lưu một giá trị, ví dụ điểm số, và giá trị đó có thể thay đổi khi chương trình chạy.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn nhân vật trong Scratch nói 'Xin chào!' trong 2 giây, em dùng khối lệnh nào?","o":["Khối 'nói ... trong ... giây' ở nhóm Hiển thị","Khối 'di chuyển 10 bước'","Khối 'đổi trang phục'","Khối 'chờ 1 giây'"],"a":"Khối 'nói ... trong ... giây' ở nhóm Hiển thị","h":"Nhóm lệnh làm nhân vật hiện lời nói trong bong bóng.","e":"Khối nói trong nhóm Hiển thị giúp nhân vật hiện bong bóng lời nói trong một khoảng thời gian.","t":"tin-cap1","l":"thu-thach"},{"p":"Muốn nhân vật mèo phát ra tiếng 'meo' khi em bấm vào nhân vật, em dùng nhóm khối lệnh nào?","o":["Nhóm Âm thanh","Nhóm Bút vẽ","Nhóm Cảm biến","Nhóm Số học"],"a":"Nhóm Âm thanh","h":"Nhóm lệnh liên quan tới tiếng động.","e":"Các khối phát âm thanh trong Scratch nằm ở nhóm Âm thanh.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong Scratch, sau khi dùng khối bút 'đặt bút xuống', điều gì xảy ra khi nhân vật di chuyển?","o":["Nhân vật vẽ thành một đường theo đường di chuyển","Nhân vật biến mất khỏi sân khấu","Nhân vật nói thành tiếng","Sân khấu đổi màu nền"],"a":"Nhân vật vẽ thành một đường theo đường di chuyển","h":"Giống như em đặt đầu bút xuống giấy rồi kéo đi.","e":"Đặt bút xuống giúp nhân vật để lại nét vẽ trên sân khấu khi di chuyển, giống bút vẽ trên giấy.","t":"tin-cap1","l":"thu-thach"},{"p":"Muốn nhân vật nhảy lên mỗi khi em nhấn phím cách trên bàn phím, chương trình Scratch nên bắt đầu bằng sự kiện nào?","o":["Khi phím cách được nhấn","Khi lá cờ xanh được bấm","Khi nhân vật được bấm vào","Khi sân khấu được bấm vào"],"a":"Khi phím cách được nhấn","h":"Sự kiện gắn với phím trên bàn phím.","e":"Scratch có sự kiện 'khi phím ... được nhấn', dùng để điều khiển nhân vật bằng bàn phím.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Nhân vật đang đi sang phải và chạm vào cạnh sân khấu. Khối lệnh nào giúp nhân vật tự quay lại và đi tiếp thay vì bị kẹt ở cạnh?","o":["Khối 'nếu chạm cạnh, bật lại'","Khối 'xoá tất cả hình vẽ'","Khối 'dừng tất cả'","Khối 'ẩn nhân vật'"],"a":"Khối 'nếu chạm cạnh, bật lại'","h":"Khối này nằm trong nhóm Di chuyển.","e":"Khối 'nếu chạm cạnh, bật lại' trong nhóm Di chuyển giúp nhân vật đổi hướng khi chạm mép sân khấu.","t":"tin-cap1","l":"kho"},{"p":"Biến Điểm đang có giá trị 5. Sau khi thực hiện khối 'thay đổi Điểm thêm 1', biến Điểm có giá trị bao nhiêu?","o":["6","5","1","10"],"a":"6","h":"Cộng thêm 1 vào giá trị đang có.","e":"Khối thay đổi biến thêm 1 sẽ tăng giá trị của biến Điểm từ 5 lên 6.","t":"tin-cap1","l":"thu-thach"},{"p":"Nhận được email của cô giáo, muốn viết thư trả lời ngay cho cô, em bấm vào nút nào?","o":["Trả lời (Reply)","Chuyển tiếp (Forward)","Xoá thư","In thư"],"a":"Trả lời (Reply)","h":"Nút có nghĩa là hồi âm lại thư vừa nhận.","e":"Nút Trả lời (Reply) mở khung soạn thư gửi lại cho chính người vừa gửi thư cho em.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi viết email, dòng 'Chủ đề' có tác dụng gì?","o":["Cho người nhận biết ngay thư nói về việc gì","Trang trí cho email đẹp hơn","Đính kèm tệp vào thư","Gửi thư đi nhanh hơn"],"a":"Cho người nhận biết ngay thư nói về việc gì","h":"Giống như tiêu đề của một bài văn.","e":"Chủ đề tóm tắt nội dung thư, giúp người nhận biết thư nói về việc gì trước khi mở đọc.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Thư rác (spam) trong email là gì?","o":["Thư quảng cáo hoặc thư lạ được gửi hàng loạt mà em không mong muốn","Thư của thầy cô gửi cho em","Thư em đã đọc xong","Thư nháp chưa gửi đi"],"a":"Thư quảng cáo hoặc thư lạ được gửi hàng loạt mà em không mong muốn","h":"Đó là những thư em không hề yêu cầu được gửi tới.","e":"Thư rác là thư quảng cáo, thư lạ gửi hàng loạt tới nhiều người mà người nhận không mong muốn.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi nhận được một thư rác lạ có đường liên kết mời bấm vào để nhận quà, em nên làm gì?","o":["Xoá thư hoặc đánh dấu là thư rác, không bấm vào liên kết","Bấm ngay vào liên kết để nhận quà","Chuyển tiếp cho nhiều bạn bè","Trả lời thư hỏi thêm thông tin"],"a":"Xoá thư hoặc đánh dấu là thư rác, không bấm vào liên kết","h":"Quà miễn phí từ người lạ thường là bẫy lừa đảo.","e":"Thư rác có liên kết lạ có thể chứa lừa đảo hoặc mã độc, em nên xoá thư và không bấm vào liên kết.","t":"tin-cap1","l":"thu-thach"},{"p":"Muốn gửi kèm ba bức ảnh trong cùng một email cho bạn, em làm thế nào?","o":["Đính kèm cả ba tệp ảnh vào thư rồi mới gửi","Gửi ba email, mỗi email một ảnh cho nhanh","Chép ảnh vào dòng chủ đề của thư","In ảnh ra rồi gửi qua bưu điện"],"a":"Đính kèm cả ba tệp ảnh vào thư rồi mới gửi","h":"Một email có thể đính kèm nhiều tệp cùng lúc.","e":"Khi soạn thư, em có thể đính kèm nhiều tệp ảnh cùng lúc vào một email rồi gửi đi.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Thư của cô giáo được gửi cho cả lớp. Muốn trả lời sao cho tất cả các bạn cùng nhận được thư trả lời của em, em dùng nút nào?","o":["Trả lời tất cả (Reply All)","Trả lời (Reply)","Chuyển tiếp (Forward)","Xoá thư"],"a":"Trả lời tất cả (Reply All)","h":"Có một nút trả lời dành cho mọi người cùng nhận thư.","e":"Nút Trả lời tất cả (Reply All) gửi thư trả lời tới tất cả những người có trong danh sách nhận thư, không chỉ người gửi.","t":"tin-cap1","l":"kho"},{"p":"Trong phần mềm soạn thảo, nút chữ B dùng để làm gì?","o":["Làm cho chữ được chọn đậm hơn","Làm cho chữ nghiêng đi","Gạch chân dưới chữ","Đổi màu chữ thành đỏ"],"a":"Làm cho chữ được chọn đậm hơn","h":"B là chữ cái đầu của từ 'Bold' nghĩa là đậm.","e":"Nút B (Bold) dùng để in đậm phần chữ đang được chọn trong văn bản.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn gạch chân dưới một từ quan trọng trong bài soạn thảo, em dùng nút nào?","o":["Nút U","Nút B","Nút I","Nút căn giữa"],"a":"Nút U","h":"U là chữ cái đầu của từ 'Underline'.","e":"Nút U (Underline) dùng để gạch chân dưới chữ được chọn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi gõ tiêu đề bài văn, em thường dùng cách căn lề nào để tiêu đề nằm ở giữa trang?","o":["Căn giữa","Căn trái","Căn phải","Căn đều hai bên"],"a":"Căn giữa","h":"Tiêu đề thường đứng ở vị trí trung tâm của dòng.","e":"Căn giữa đưa nội dung ra giữa trang, thường dùng cho tiêu đề bài văn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn các chữ trong tiêu đề to hơn phần nội dung, em cần thay đổi điều gì?","o":["Cỡ chữ của tiêu đề","Màu giấy của trang","Khoảng cách giữa các trang","Tên của tệp văn bản"],"a":"Cỡ chữ của tiêu đề","h":"Đó là con số chỉ độ lớn của chữ, ví dụ 14, 16, 20.","e":"Cỡ chữ quyết định độ to nhỏ của chữ; tăng cỡ chữ sẽ làm tiêu đề to hơn nội dung.","t":"tin-cap1","l":"thu-thach"},{"p":"Sau khi chèn một bức hình vào văn bản, muốn đưa hình sang vị trí khác trong trang, em làm thế nào?","o":["Bấm chọn hình rồi kéo thả tới vị trí mới","Xoá văn bản rồi gõ lại từ đầu","Đổi tên tệp văn bản","Tắt máy rồi bật lại"],"a":"Bấm chọn hình rồi kéo thả tới vị trí mới","h":"Dùng chuột kéo vật tới nơi em muốn đặt.","e":"Hình đã chèn vào văn bản có thể được chọn và kéo thả bằng chuột tới vị trí khác trong trang.","t":"tin-cap1","l":"thu-thach"},{"p":"Em muốn tiêu đề bài thơ vừa to, vừa đậm và nằm giữa trang. Cách làm nào hợp lí nhất?","o":["Chọn tiêu đề, tăng cỡ chữ, bấm nút in đậm rồi bấm căn giữa","Gõ lại tiêu đề bằng toàn chữ hoa","Chèn một bức hình chụp tiêu đề vào văn bản","Đổi màu giấy của trang thành màu khác"],"a":"Chọn tiêu đề, tăng cỡ chữ, bấm nút in đậm rồi bấm căn giữa","h":"Kết hợp cả ba thao tác định dạng đã học.","e":"Muốn tiêu đề to, đậm và ở giữa trang, em chọn tiêu đề rồi tăng cỡ chữ, in đậm và căn giữa.","t":"tin-cap1","l":"kho"},{"p":"Muốn tìm đường đi ngắn nhất từ nhà em tới trường bằng Internet, em nên dùng loại công cụ nào?","o":["Bản đồ số trên Internet","Phần mềm nghe nhạc","Trò chơi điện tử","Máy tính bỏ túi"],"a":"Bản đồ số trên Internet","h":"Công cụ cho xem đường phố và chỉ đường đi.","e":"Bản đồ số trực tuyến giúp em tìm vị trí và đường đi giữa hai nơi một cách nhanh chóng.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Học trực tuyến là hình thức học như thế nào?","o":["Học qua Internet bằng các bài giảng, lớp học trên mạng","Học bằng cách đọc sách giấy ở nhà","Học cùng bạn ở sân trường","Học qua truyền hình cáp tại nhà hàng xóm"],"a":"Học qua Internet bằng các bài giảng, lớp học trên mạng","h":"Chữ 'trực tuyến' gắn với mạng Internet.","e":"Học trực tuyến là học qua Internet, qua video bài giảng hoặc lớp học trực tuyến với thầy cô.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi tìm kiếm trên Internet, việc đặt cụm từ khoá trong dấu ngoặc kép giúp ích gì?","o":["Máy tìm kiếm ưu tiên các kết quả chứa đúng cụm từ đó","Kết quả tìm kiếm hiện ra nhanh gấp đôi","Không còn quảng cáo trong kết quả","Tự động dịch kết quả sang tiếng Việt"],"a":"Máy tìm kiếm ưu tiên các kết quả chứa đúng cụm từ đó","h":"Ngoặc kép giúp tìm đúng nguyên văn cụm từ.","e":"Đặt từ khoá trong dấu ngoặc kép giúp máy tìm kiếm trả về kết quả chứa đúng cụm từ em cần.","t":"tin-cap1","l":"thu-thach"},{"p":"Đang xem video bài giảng trực tuyến mà chưa hiểu một đoạn, em nên làm gì?","o":["Tạm dừng hoặc tua lại đoạn đó để xem lại","Tắt video và bỏ qua luôn","Xem tiếp cho hết dù không hiểu","Chờ bạn bên cạnh giảng lại"],"a":"Tạm dừng hoặc tua lại đoạn đó để xem lại","h":"Video trực tuyến có thể xem lại nhiều lần.","e":"Video bài giảng có thể tạm dừng và tua lại, giúp em xem lại đoạn chưa hiểu cho tới khi hiểu bài.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em cần tìm đúng nguyên văn câu thơ 'Quê hương là chùm khế ngọt' trên Internet. Cách gõ tìm kiếm nào hiệu quả nhất?","o":["Gõ cả câu thơ trong dấu ngoặc kép","Chỉ gõ một từ 'quê'","Gõ tên của em vào ô tìm kiếm","Gõ câu thơ không dấu và thêm nhiều từ lạ"],"a":"Gõ cả câu thơ trong dấu ngoặc kép","h":"Dùng dấu ngoặc kép cho cả câu cần tìm nguyên văn.","e":"Đặt cả câu trong dấu ngoặc kép giúp máy tìm kiếm tìm đúng nguyên văn câu thơ.","t":"tin-cap1","l":"kho"},{"p":"Mật khẩu nào sau đây là mật khẩu tốt cho tài khoản học tập của em?","o":["Một dãy khó đoán gồm cả chữ và số, chỉ em và bố mẹ biết","Ngày sinh của em","Tên của em viết liền","Dãy số 123456"],"a":"Một dãy khó đoán gồm cả chữ và số, chỉ em và bố mẹ biết","h":"Mật khẩu tốt phải khó bị người khác đoán ra.","e":"Mật khẩu tốt cần khó đoán, gồm cả chữ và số, và không dùng thông tin dễ biết như ngày sinh.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Vì sao em không nên dùng cùng một mật khẩu cho mọi tài khoản trên mạng?","o":["Nếu mật khẩu bị lộ ở một nơi, kẻ xấu có thể đăng nhập tất cả tài khoản còn lại","Vì máy tính không cho phép đặt trùng mật khẩu","Vì mật khẩu dùng chung sẽ tự hết hạn","Vì các tài khoản sẽ bị khoá vĩnh viễn"],"a":"Nếu mật khẩu bị lộ ở một nơi, kẻ xấu có thể đăng nhập tất cả tài khoản còn lại","h":"Nghĩ tới trường hợp một tài khoản bị lộ mật khẩu.","e":"Dùng chung một mật khẩu rất nguy hiểm: lộ ở một tài khoản là kẻ xấu có thể vào mọi tài khoản khác.","t":"tin-cap1","l":"thu-thach"},{"p":"Một người lạ trên mạng nhắn tin rủ em gửi ảnh cá nhân và hứa tặng quà trong trò chơi. Em nên làm gì?","o":["Không gửi ảnh, chặn người đó và kể với bố mẹ hoặc thầy cô","Gửi ảnh để nhận quà","Hỏi xin thêm quà rồi mới gửi","Nhắn cho bạn bè cùng gửi ảnh"],"a":"Không gửi ảnh, chặn người đó và kể với bố mẹ hoặc thầy cô","h":"Không tin lời hứa quà tặng của người lạ trên mạng.","e":"Người lạ xin ảnh cá nhân có thể có ý đồ xấu; em không gửi, chặn liên lạc và báo cho người lớn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi chơi trò chơi trực tuyến, em muốn mua một vật phẩm bằng tiền thật. Việc em cần làm trước tiên là gì?","o":["Xin phép và được bố mẹ đồng ý","Mua ngay kẻo hết hàng","Mượn tài khoản của bạn để mua","Giấu bố mẹ và tự mua"],"a":"Xin phép và được bố mẹ đồng ý","h":"Mọi khoản chi tiền thật đều cần người lớn đồng ý.","e":"Mua vật phẩm bằng tiền thật trong trò chơi phải xin phép và được bố mẹ đồng ý trước.","t":"tin-cap1","l":"thu-thach"},{"p":"Bạn thân xin mật khẩu tài khoản học trực tuyến của em để vào xem bài. Em nên làm gì?","o":["Không chia sẻ mật khẩu, khuyên bạn dùng tài khoản của chính bạn","Cho bạn mật khẩu vì là bạn thân","Đổi mật khẩu đơn giản hơn rồi cho bạn","Cho bạn mật khẩu nhưng dặn giữ bí mật"],"a":"Không chia sẻ mật khẩu, khuyên bạn dùng tài khoản của chính bạn","h":"Mật khẩu là của riêng mỗi người, kể cả với bạn thân.","e":"Mật khẩu tài khoản là thông tin riêng, không chia sẻ cho bất kì ai; bạn nên dùng tài khoản của chính mình.","t":"tin-cap1","l":"kho"},{"p":"Thông tin nào sau đây em KHÔNG nên công khai cho mọi người trên mạng?","o":["Địa chỉ nhà và số điện thoại của em","Tên cuốn truyện em yêu thích","Màu sắc em thích nhất","Tên môn học em thích"],"a":"Địa chỉ nhà và số điện thoại của em","h":"Đó là thông tin riêng tư của gia đình em.","e":"Địa chỉ nhà và số điện thoại là thông tin cá nhân cần giữ kín, không công khai trên mạng.","t":"tin-cap1","l":"thu-thach"},{"p":"Số nhị phân được viết bằng những chữ số nào?","o":["Chỉ hai chữ số 0 và 1","Các chữ số từ 0 đến 9","Các chữ cái A và B","Các chữ số từ 1 đến 9"],"a":"Chỉ hai chữ số 0 và 1","h":"Chữ 'nhị' nghĩa là hai.","e":"Hệ nhị phân chỉ dùng hai chữ số 0 và 1 để biểu diễn mọi thông tin.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Mỗi bit trong máy tính chỉ nhận một trong hai giá trị nào?","o":["0 hoặc 1","1 hoặc 2","Chữ Đ hoặc chữ S","Âm hoặc dương"],"a":"0 hoặc 1","h":"Bit là đơn vị thông tin nhỏ nhất.","e":"Một bit chỉ có hai trạng thái, được kí hiệu bằng 0 hoặc 1.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Vì sao máy tính dùng hệ nhị phân để biểu diễn và xử lí thông tin?","o":["Vì các bộ phận điện tử của máy tính dễ thể hiện hai trạng thái như có điện và không có điện","Vì hệ nhị phân có nhiều chữ số hơn hệ thập phân","Vì con người chỉ đếm được tới số 2","Vì hệ nhị phân luôn viết nhanh hơn mọi hệ đếm khác"],"a":"Vì các bộ phận điện tử của máy tính dễ thể hiện hai trạng thái như có điện và không có điện","h":"Liên quan tới cách mạch điện trong máy tính hoạt động.","e":"Mạch điện trong máy tính có hai trạng thái rõ ràng (đóng/mở, có điện/không có điện) nên hệ nhị phân rất phù hợp.","t":"tin-cap2","l":"thu-thach"},{"p":"Khi em gõ chữ 'A' trên bàn phím, trong máy tính chữ đó được biểu diễn dưới dạng nào?","o":["Một dãy các bit 0 và 1","Một hình vẽ của chữ A","Một âm thanh đọc chữ A","Một tờ giấy in chữ A"],"a":"Một dãy các bit 0 và 1","h":"Mọi thông tin trong máy tính đều được đưa về cùng một dạng.","e":"Mọi kí tự khi đưa vào máy tính đều được mã hoá thành dãy bit gồm các số 0 và 1.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong hệ nhị phân, số 11 tương đương với số nào trong hệ thập phân?","o":["3","2","11","10"],"a":"3","h":"11 trong hệ nhị phân bằng 1×2 + 1.","e":"Số nhị phân 11 có giá trị 1×2 + 1 = 3 trong hệ thập phân.","t":"tin-cap2","l":"kho"},{"p":"Văn bản, hình ảnh và âm thanh khi được lưu trong máy tính có điểm chung nào?","o":["Đều được chuyển thành dãy bit để lưu trữ và xử lí","Đều được in ra giấy ngay lập tức","Đều có dung lượng bằng nhau","Đều không cần điện để hoạt động"],"a":"Đều được chuyển thành dãy bit để lưu trữ và xử lí","h":"Máy tính chỉ xử lí được một dạng thông tin duy nhất.","e":"Mọi dạng thông tin đưa vào máy tính đều được biểu diễn bằng dãy bit để lưu trữ và xử lí.","t":"tin-cap2","l":"thu-thach"},{"p":"Muốn có một tài khoản thư điện tử (email) để gửi và nhận thư, em cần làm gì?","o":["Đăng kí tài khoản với một nhà cung cấp dịch vụ thư điện tử","Mua một chiếc máy tính mới","Xin số điện thoại của bạn bè","Cài thêm một trò chơi vào máy"],"a":"Đăng kí tài khoản với một nhà cung cấp dịch vụ thư điện tử","h":"Giống như đăng kí một hộp thư của riêng em trên mạng.","e":"Để dùng email, em cần đăng kí một tài khoản với nhà cung cấp dịch vụ thư điện tử.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Bạn gửi email cho em. Khi em đăng nhập vào hộp thư của mình, thư của bạn sẽ nằm ở đâu?","o":["Trong hộp thư đến (Inbox)","Trong thư mục rác","Trong thư nháp","Trong các tệp đã xoá"],"a":"Trong hộp thư đến (Inbox)","h":"Đó là nơi chứa các thư người khác gửi tới.","e":"Thư người khác gửi tới sẽ xuất hiện trong hộp thư đến (Inbox) của em.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Đâu là một mặt trái của Internet mà em cần cảnh giác?","o":["Có thông tin sai lệch, độc hại và những kẻ lừa đảo trên mạng","Internet làm máy tính trở nên nặng hơn","Internet chỉ dùng được vào ban ngày","Internet khiến em không thể học tập được nữa"],"a":"Có thông tin sai lệch, độc hại và những kẻ lừa đảo trên mạng","h":"Bên cạnh nhiều lợi ích, Internet cũng có những nguy cơ.","e":"Internet có thể chứa thông tin sai lệch, nội dung độc hại và lừa đảo, nên em cần cẩn thận khi sử dụng.","t":"tin-cap2","l":"thu-thach"},{"p":"Em nhận được email lạ tự xưng là ngân hàng và yêu cầu em cung cấp mật khẩu tài khoản. Em nên làm gì?","o":["Không cung cấp mật khẩu, xoá thư và báo cho người lớn","Cung cấp ngay để không bị khoá tài khoản","Chuyển tiếp thư cho bạn bè cùng làm theo","Trả lời thư để hỏi lại cho rõ"],"a":"Không cung cấp mật khẩu, xoá thư và báo cho người lớn","h":"Ngân hàng không bao giờ xin mật khẩu của khách hàng qua email.","e":"Đây là chiêu lừa đảo nhằm đánh cắp tài khoản; em tuyệt đối không cung cấp mật khẩu và nên báo cho người lớn.","t":"tin-cap1","l":"kho"},{"p":"Mạng xã hội là gì?","o":["Dịch vụ trên Internet giúp mọi người kết nối, chia sẻ thông tin và trò chuyện với nhau","Một loại trò chơi điện tử trên máy tính","Một thiết bị lưu trữ dữ liệu","Một phần mềm soạn thảo văn bản"],"a":"Dịch vụ trên Internet giúp mọi người kết nối, chia sẻ thông tin và trò chuyện với nhau","h":"Đó là nơi mọi người kết bạn và chia sẻ bài viết, hình ảnh.","e":"Mạng xã hội là dịch vụ trực tuyến giúp mọi người kết nối, chia sẻ thông tin và trò chuyện.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Danh sách đánh số tự động trong văn bản có lợi ích gì?","o":["Các mục được đánh số thứ tự và tự thay đổi khi em thêm hoặc bớt mục","Làm cho chữ trong danh sách to hơn","Tự động đổi màu cho cả danh sách","Giúp văn bản được in ra nhanh hơn"],"a":"Các mục được đánh số thứ tự và tự thay đổi khi em thêm hoặc bớt mục","h":"Em không phải tự gõ số cho từng mục.","e":"Danh sách đánh số tự động giúp các mục luôn đúng thứ tự khi em thêm, bớt hoặc sắp xếp lại mục.","t":"tin-cap2","l":"thu-thach"},{"p":"Công cụ Tìm kiếm và Thay thế (Find and Replace) trong soạn thảo dùng để làm gì?","o":["Tìm một từ trong văn bản và thay nó bằng từ khác ở tất cả các vị trí","Tìm tệp văn bản trong máy tính","Thay đổi màu nền của trang giấy","Thay thế hình ảnh bằng văn bản"],"a":"Tìm một từ trong văn bản và thay nó bằng từ khác ở tất cả các vị trí","h":"Rất tiện khi một từ bị gõ sai ở nhiều chỗ trong bài.","e":"Find and Replace giúp tìm một từ và thay thế nó bằng từ khác trong toàn bộ văn bản một cách nhanh chóng.","t":"tin-cap2","l":"thu-thach"},{"p":"Trước khi in một văn bản, em nên làm gì để chắc chắn trang in được trình bày đúng ý?","o":["Xem trước khi in (Print Preview)","Tắt màn hình máy tính","Đổi tên tệp văn bản","Gửi văn bản cho bạn bè"],"a":"Xem trước khi in (Print Preview)","h":"Chế độ này cho em nhìn thấy trang giấy trước khi in thật.","e":"Xem trước khi in giúp em kiểm tra bố cục, lề và lỗi trình bày trước khi in ra giấy.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong soạn thảo văn bản, 'lề trang' là gì?","o":["Khoảng trống giữa phần nội dung văn bản và các mép của trang giấy","Đường kẻ ở giữa hai cột văn bản","Tên của người soạn văn bản","Số trang in ở cuối tờ giấy"],"a":"Khoảng trống giữa phần nội dung văn bản và các mép của trang giấy","h":"Đó là phần giấy trắng bao quanh nội dung.","e":"Lề trang là khoảng cách từ nội dung văn bản tới các mép trên, dưới, trái, phải của trang giấy.","t":"tin-cap2","l":"kho"},{"p":"Muốn liệt kê các đồ dùng học tập cần mang theo bằng dấu chấm đầu dòng, em dùng loại danh sách nào?","o":["Danh sách gạch đầu dòng (không đánh số)","Danh sách đánh số thứ tự","Bảng biểu","Biểu đồ cột"],"a":"Danh sách gạch đầu dòng (không đánh số)","h":"Các mục này không cần thứ tự trước sau.","e":"Khi các mục không cần xếp thứ tự, em dùng danh sách gạch đầu dòng với dấu chấm hoặc kí hiệu ở đầu mỗi mục.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong phần mềm trình chiếu PowerPoint, 'bố cục' (layout) của một trang chiếu là gì?","o":["Cách sắp xếp vị trí của tiêu đề, nội dung và hình ảnh trên trang chiếu","Màu nền của trang chiếu","Hiệu ứng chuyển động của chữ","Số lượng trang chiếu trong bài"],"a":"Cách sắp xếp vị trí của tiêu đề, nội dung và hình ảnh trên trang chiếu","h":"Nó quyết định mỗi thành phần nằm ở đâu trên trang.","e":"Bố cục (layout) quy định cách bố trí tiêu đề, nội dung, hình ảnh trên một trang chiếu.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Hiệu ứng chuyển trang trong bài trình chiếu là gì?","o":["Cách một trang chiếu mới xuất hiện thay cho trang chiếu trước khi trình chiếu","Âm thanh phát ra khi bấm chuột","Màu chữ của tiêu đề trang chiếu","Tên của tệp trình chiếu"],"a":"Cách một trang chiếu mới xuất hiện thay cho trang chiếu trước khi trình chiếu","h":"Hiệu ứng này xảy ra ở khoảnh khắc đổi từ trang này sang trang khác.","e":"Hiệu ứng chuyển trang là hiệu ứng xuất hiện khi chuyển từ trang chiếu này sang trang chiếu tiếp theo.","t":"tin-cap2","l":"thu-thach"},{"p":"Trình tự nào sau đây là hợp lí khi tạo một bài trình chiếu đơn giản?","o":["Mở phần mềm, tạo các trang chiếu và nhập nội dung, chèn hình, rồi lưu và trình chiếu thử","Trình chiếu thử trước rồi mới tạo trang chiếu","In bài trình chiếu rồi mới nhập nội dung","Chèn hình vào máy trước khi mở phần mềm"],"a":"Mở phần mềm, tạo các trang chiếu và nhập nội dung, chèn hình, rồi lưu và trình chiếu thử","h":"Làm xong bài mới trình chiếu thử để kiểm tra.","e":"Quy trình hợp lí: mở phần mềm, tạo trang và nhập nội dung, chèn hình minh hoạ, lưu tệp rồi trình chiếu thử.","t":"tin-cap2","l":"kho"},{"p":"Một trang chiếu thường gồm những thành phần chính nào?","o":["Tiêu đề và phần nội dung (văn bản, hình ảnh)","Chỉ có hình ảnh động","Chỉ có âm thanh","Chỉ có đúng một dòng chữ"],"a":"Tiêu đề và phần nội dung (văn bản, hình ảnh)","h":"Nhìn vào bất kì trang chiếu mẫu nào em cũng thấy hai phần này.","e":"Trang chiếu thường có tiêu đề ở phía trên và phần nội dung gồm văn bản, hình ảnh ở phía dưới.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong sơ đồ khối của thuật toán, hình chữ nhật thể hiện điều gì?","o":["Một bước xử lí (thao tác cần thực hiện)","Điểm bắt đầu của thuật toán","Điểm kết thúc của thuật toán","Một câu hỏi kiểm tra điều kiện"],"a":"Một bước xử lí (thao tác cần thực hiện)","h":"Hình này khác với hình thoi dùng cho bước kiểm tra điều kiện.","e":"Trong sơ đồ khối, hình chữ nhật biểu diễn một bước xử lí, tức một thao tác cần thực hiện.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong sơ đồ khối, hình ô-van (hình bầu dục) thể hiện điều gì?","o":["Bắt đầu hoặc kết thúc của thuật toán","Một bước tính toán","Một bước kiểm tra điều kiện","Thứ tự thực hiện các bước"],"a":"Bắt đầu hoặc kết thúc của thuật toán","h":"Hình này luôn nằm ở đầu và ở cuối sơ đồ.","e":"Hình ô-van trong sơ đồ khối dùng để đánh dấu điểm bắt đầu hoặc điểm kết thúc của thuật toán.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong sơ đồ khối, các mũi tên có vai trò gì?","o":["Chỉ trình tự thực hiện các bước của thuật toán","Trang trí cho sơ đồ đẹp hơn","Đánh số thứ tự cho các hình","Thể hiện kết quả cuối cùng"],"a":"Chỉ trình tự thực hiện các bước của thuật toán","h":"Mũi tên nối bước trước với bước sau.","e":"Mũi tên trong sơ đồ khối cho biết thứ tự thực hiện: bước nào làm trước, bước nào làm sau.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Cấu trúc tuần tự trong thuật toán là gì?","o":["Các bước được thực hiện lần lượt theo thứ tự, bước trước xong mới tới bước sau","Tất cả các bước được thực hiện cùng một lúc","Các bước được lặp lại nhiều lần không dừng","Chỉ thực hiện bước cuối cùng rồi dừng"],"a":"Các bước được thực hiện lần lượt theo thứ tự, bước trước xong mới tới bước sau","h":"Giống như làm lần lượt từng bước trong một công thức nấu ăn.","e":"Cấu trúc tuần tự là cấu trúc mà các bước của thuật toán được thực hiện lần lượt theo đúng thứ tự đã liệt kê.","t":"tin-cap2","l":"kho"},{"p":"Khi dùng một đoạn tài liệu lấy từ Internet cho bài tập của mình, em cần làm gì cho đúng?","o":["Ghi rõ nguồn của tài liệu đó","Không cần ghi gì cả","Đổi tên tác giả thành tên của em","Xoá hết mọi dấu vết của nguồn tài liệu"],"a":"Ghi rõ nguồn của tài liệu đó","h":"Đó là cách tôn trọng công sức của tác giả.","e":"Khi sử dụng tài liệu của người khác, em phải ghi rõ nguồn để tôn trọng tác giả và bản quyền.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Việc làm nào sau đây KHÔNG nên làm khi sử dụng mạng Internet?","o":["Công khai địa chỉ nhà và số điện thoại của mình cho mọi người","Hỏi bố mẹ khi gặp điều lạ trên mạng","Dùng Internet để tra cứu bài học","Kết bạn với bạn cùng lớp trên mạng"],"a":"Công khai địa chỉ nhà và số điện thoại của mình cho mọi người","h":"Thông tin cá nhân cần được giữ kín.","e":"Địa chỉ nhà và số điện thoại là thông tin cá nhân, không nên công khai trên mạng để tránh nguy hiểm.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Một bạn sao chép nguyên văn bài viết trên Internet rồi nộp cho thầy cô như bài làm của mình. Việc làm này sai ở điểm nào?","o":["Không trung thực và vi phạm bản quyền vì không ghi nguồn, đó không phải bài do mình làm","Sai vì bài viết trên Internet luôn ngắn hơn bài tự làm","Sai vì máy tính không cho phép sao chép văn bản","Không sai, vì tài liệu trên Internet là của chung mọi người"],"a":"Không trung thực và vi phạm bản quyền vì không ghi nguồn, đó không phải bài do mình làm","h":"Vấn đề nằm ở sự trung thực và tôn trọng tác giả.","e":"Sao chép nguyên văn mà không ghi nguồn là thiếu trung thực và vi phạm bản quyền của tác giả.","t":"tin-cap2","l":"thu-thach"},{"p":"Máy in thuộc loại thiết bị nào của máy tính?","o":["Thiết bị vào","Thiết bị ra","Thiết bị lưu trữ","Bộ xử lí trung tâm"],"a":"Thiết bị ra","h":"Nghĩ xem máy in đưa thông tin ra ngoài hay nhận thông tin vào.","e":"Máy in đưa kết quả xử lí từ máy tính ra giấy nên là thiết bị ra.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi trình chiếu bài học cho cả lớp, máy chiếu có vai trò gì?","o":["Lưu trữ bài học trong máy tính","Xử lí dữ liệu của bài học","Hiển thị hình ảnh từ máy tính lên màn hình lớn","Kết nối máy tính với Internet"],"a":"Hiển thị hình ảnh từ máy tính lên màn hình lớn","h":"Cả lớp cùng nhìn thấy bài học ở đâu?","e":"Máy chiếu là thiết bị ra, giúp hiển thị hình ảnh từ máy tính lên màn chiếu lớn cho nhiều người cùng xem.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Ổ cứng SSD và USB thường được dùng để làm gì?","o":["Hiển thị hình ảnh","Lưu trữ dữ liệu","Nhập văn bản vào máy tính","Phát âm thanh"],"a":"Lưu trữ dữ liệu","h":"Ảnh, bài tập của em được giữ lâu dài ở đâu?","e":"SSD và USB là thiết bị lưu trữ, dùng để giữ dữ liệu lâu dài trong máy tính hoặc mang theo.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong các dung lượng lưu trữ sau, dung lượng nào lớn nhất?","o":["256 GB","512 GB","128 GB","1 TB"],"a":"1 TB","h":"Nhớ mối quan hệ giữa GB và TB.","e":"1 TB bằng 1024 GB nên lớn hơn 512 GB, 256 GB và 128 GB.","t":"tin-cap2","l":"thu-thach"},{"p":"Cổng HDMI trên máy tính thường được dùng để làm gì?","o":["Kết nối máy tính với màn hình hoặc máy chiếu để truyền hình ảnh","Sạc pin cho điện thoại","Kết nối máy tính với mạng có dây","Cắm tai nghe nghe nhạc"],"a":"Kết nối máy tính với màn hình hoặc máy chiếu để truyền hình ảnh","h":"Em thường thấy dây HDMI cắm giữa máy tính và thiết bị nào khi trình chiếu?","e":"Cổng HDMI dùng để truyền tín hiệu hình ảnh (và âm thanh) từ máy tính sang màn hình, ti vi hoặc máy chiếu.","t":"tin-cap2","l":"thu-thach"},{"p":"Điểm khác nhau cơ bản giữa ổ cứng gắn trong máy tính và USB là gì?","o":["Ổ cứng không lưu được dữ liệu, USB thì có","Ổ cứng thường có dung lượng lớn và gắn cố định trong máy, USB nhỏ gọn, dễ mang theo","USB có dung lượng lớn hơn mọi ổ cứng","Ổ cứng chỉ lưu được ảnh, USB lưu được mọi loại tệp"],"a":"Ổ cứng thường có dung lượng lớn và gắn cố định trong máy, USB nhỏ gọn, dễ mang theo","h":"So sánh về kích thước, dung lượng và tính di động.","e":"Ổ cứng gắn trong thường có dung lượng lớn và cố định trong máy; USB nhỏ gọn nên tiện mang theo để chép dữ liệu.","t":"tin-cap2","l":"kho"},{"p":"Android và iOS là gì?","o":["Phần mềm chơi trò chơi trên điện thoại","Hệ điều hành dành cho điện thoại thông minh","Ứng dụng chụp ảnh","Trình duyệt web trên điện thoại"],"a":"Hệ điều hành dành cho điện thoại thông minh","h":"Điện thoại cần phần mềm nào để hoạt động và chạy các ứng dụng?","e":"Android và iOS là hai hệ điều hành phổ biến trên điện thoại thông minh.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Phần mềm soạn thảo văn bản thuộc loại phần mềm nào?","o":["Hệ điều hành","Phần mềm ứng dụng","Phần mềm hệ thống","Chương trình diệt virus"],"a":"Phần mềm ứng dụng","h":"Phần mềm này phục vụ một công việc cụ thể là soạn thảo.","e":"Phần mềm soạn thảo văn bản phục vụ nhu cầu công việc cụ thể nên thuộc nhóm phần mềm ứng dụng.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Máy tính báo hết dung lượng trống nên không cài thêm được phần mềm mới. Nguyên nhân thường là gì?","o":["Màn hình quá nhỏ","Ổ đĩa lưu trữ đã đầy","Bàn phím bị hỏng","Chuột hết pin"],"a":"Ổ đĩa lưu trữ đã đầy","h":"Phần mềm mới cài vào đâu trong máy tính?","e":"Phần mềm được cài đặt và lưu trên ổ đĩa; khi ổ đĩa đầy sẽ không còn chỗ để cài thêm.","t":"tin-cap2","l":"thu-thach"},{"p":"Muốn loại bỏ hẳn một phần mềm không còn sử dụng khỏi máy tính, em nên làm gì?","o":["Chỉ xoá biểu tượng của phần mềm trên màn hình nền","Gỡ cài đặt (uninstall) phần mềm đó đúng cách","Đổi tên thư mục chứa phần mềm","Tắt máy tính rồi mở lại"],"a":"Gỡ cài đặt (uninstall) phần mềm đó đúng cách","h":"Xoá biểu tượng có xoá được phần mềm thật không?","e":"Phải gỡ cài đặt đúng cách thì phần mềm mới bị loại bỏ hoàn toàn; xoá biểu tượng chỉ xoá lối tắt.","t":"tin-cap2","l":"thu-thach"},{"p":"Khi cài đặt một phần mềm mới tải từ Internet, việc làm nào quan trọng nhất để tránh mã độc?","o":["Cài thật nhanh trước khi máy tự tắt","Chỉ tải phần mềm từ trang web chính thức, đáng tin cậy và quét virus trước khi cài","Tắt phần mềm diệt virus để cài cho nhanh","Cài mọi phần mềm được quảng cáo trên trang web lạ"],"a":"Chỉ tải phần mềm từ trang web chính thức, đáng tin cậy và quét virus trước khi cài","h":"Phần mềm từ nguồn không rõ ràng có thể chứa gì?","e":"Tải phần mềm từ nguồn chính thức và quét virus trước khi cài giúp tránh cài phải mã độc.","t":"tin-cap2","l":"kho"},{"p":"Hàm COUNT trong bảng tính dùng để làm gì?","o":["Tính tổng các số trong một vùng","Đếm số ô có chứa dữ liệu số trong một vùng","Tìm số lớn nhất trong một vùng","Đếm tất cả các ô kể cả ô trống"],"a":"Đếm số ô có chứa dữ liệu số trong một vùng","h":"COUNT liên quan tới việc đếm, không phải tính tổng.","e":"Hàm COUNT đếm số lượng ô có chứa dữ liệu số trong vùng được chọn.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Muốn chèn thêm một hàng mới vào bảng tính, em dùng lệnh nào?","o":["Lệnh Insert để chèn hàng","Lệnh Delete để xoá hàng","Lệnh Save để lưu bảng","Lệnh Print để in bảng"],"a":"Lệnh Insert để chèn hàng","h":"Insert trong tiếng Anh nghĩa là chèn vào.","e":"Dùng lệnh Insert (chèn) để thêm hàng hoặc cột mới vào bảng tính.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Khi nhập 15/03/2026 vào một ô tính, phần mềm thường hiểu đây là dữ liệu kiểu gì?","o":["Dữ liệu số thập phân","Dữ liệu ngày tháng","Dữ liệu công thức","Dữ liệu hình ảnh"],"a":"Dữ liệu ngày tháng","h":"Dạng ngày/tháng/năm quen thuộc.","e":"Chuỗi nhập theo dạng ngày/tháng/năm được phần mềm bảng tính nhận biết là dữ liệu ngày tháng.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Theo mặc định trong bảng tính, dữ liệu số và dữ liệu chữ thường được căn lề thế nào?","o":["Số căn trái, chữ căn phải","Số căn phải, chữ căn trái","Cả số và chữ đều căn giữa","Cả số và chữ đều căn phải"],"a":"Số căn phải, chữ căn trái","h":"Quan sát vị trí của số và chữ trong ô khi mới nhập.","e":"Mặc định, bảng tính căn dữ liệu số về bên phải và dữ liệu chữ về bên trái của ô.","t":"tin-cap2","l":"thu-thach"},{"p":"Ô C1 có công thức =A1+B1. Khi sao chép công thức này xuống ô C2, công thức ở C2 sẽ là gì?","o":["=A1+B1","=A2+B2","=A1+B2","=C1+C2"],"a":"=A2+B2","h":"Địa chỉ tương đối tự thay đổi theo vị trí mới.","e":"Địa chỉ tương đối trong công thức tự điều chỉnh theo hàng mới, nên =A1+B1 ở C1 thành =A2+B2 ở C2.","t":"tin-cap2","l":"thu-thach"},{"p":"Một vùng bảng tính gồm các giá trị: 5, 8, Toán, 10. Hàm COUNT áp dụng trên vùng này cho kết quả nào?","o":["4","3","23","0"],"a":"3","h":"COUNT chỉ đếm các ô chứa số.","e":"COUNT chỉ đếm ô có dữ liệu số; vùng có ba số là 5, 8, 10 nên kết quả là 3.","t":"tin-cap2","l":"thu-thach"},{"p":"Khi gõ 007 vào một ô tính, phần mềm hiển thị 7. Vì sao?","o":["Phần mềm bị lỗi hiển thị","Vì phần mềm hiểu đó là số nên tự bỏ số 0 ở đầu","Vì ô tính quá hẹp","Vì phông chữ không hiển thị được số 0"],"a":"Vì phần mềm hiểu đó là số nên tự bỏ số 0 ở đầu","h":"Muốn giữ số 0 ở đầu, người ta thường định dạng ô thành kiểu chữ (Text).","e":"Dữ liệu dạng số không giữ số 0 ở đầu; muốn nhập 007 nguyên vẹn phải định dạng ô là Text hoặc thêm dấu nháy trước.","t":"tin-cap2","l":"kho"},{"p":"Virus máy tính là gì?","o":["Một loại phần cứng của máy tính","Chương trình độc hại có khả năng lây lan và gây hại cho máy tính, dữ liệu","Phần mềm giúp máy tính chạy nhanh hơn","Tên một trò chơi trên máy tính"],"a":"Chương trình độc hại có khả năng lây lan và gây hại cho máy tính, dữ liệu","h":"Virus máy tính gây hại giống như virus sinh học lây bệnh.","e":"Virus máy tính là chương trình độc hại, tự lây lan sang tệp và máy khác, phá hoại dữ liệu hoặc làm máy hoạt động bất thường.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Phần mềm diệt virus có tác dụng gì?","o":["Tăng tốc độ mạng Internet","Phát hiện, ngăn chặn và loại bỏ virus, mã độc","Tự động làm bài tập cho học sinh","Thay thế cho hệ điều hành"],"a":"Phát hiện, ngăn chặn và loại bỏ virus, mã độc","h":"Tên của phần mềm đã nói rõ tác dụng.","e":"Phần mềm diệt virus quét, phát hiện và xử lí các chương trình độc hại để bảo vệ máy tính.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Việc làm nào sau đây giúp phòng tránh virus máy tính hiệu quả?","o":["Mở mọi tệp đính kèm nhận được cho vui","Không mở tệp lạ từ nguồn không rõ ràng, luôn bật phần mềm diệt virus","Tắt phần mềm diệt virus khi chép dữ liệu từ USB","Tải phần mềm từ bất kì trang web nào có quảng cáo hấp dẫn"],"a":"Không mở tệp lạ từ nguồn không rõ ràng, luôn bật phần mềm diệt virus","h":"Virus thường lây qua tệp lạ và USB không an toàn.","e":"Không mở tệp lạ, quét USB trước khi dùng và duy trì phần mềm diệt virus là các cách phòng virus hiệu quả.","t":"tin-cap2","l":"thu-thach"},{"p":"Sao lưu (backup) dữ liệu là gì?","o":["Xoá bớt dữ liệu cũ cho nhẹ máy","Tạo bản sao của dữ liệu để phòng khi dữ liệu gốc bị mất hoặc hỏng","Đổi tên dữ liệu thành tên khác","Nén dữ liệu thành một tệp nhỏ hơn"],"a":"Tạo bản sao của dữ liệu để phòng khi dữ liệu gốc bị mất hoặc hỏng","h":"Backup nghĩa là có một bản dự phòng.","e":"Sao lưu là tạo thêm bản sao dữ liệu, lưu ở nơi khác để dùng khi bản gốc gặp sự cố.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Vì sao cần sao lưu dữ liệu thường xuyên?","o":["Để máy tính chạy nhanh hơn","Để khôi phục được dữ liệu khi máy hỏng, bị virus hoặc xoá nhầm","Để chia sẻ dữ liệu cho bạn bè dễ hơn","Để ổ cứng trông gọn gàng hơn"],"a":"Để khôi phục được dữ liệu khi máy hỏng, bị virus hoặc xoá nhầm","h":"Bản sao dự phòng phát huy tác dụng khi nào?","e":"Sao lưu thường xuyên giúp em lấy lại dữ liệu quan trọng khi xảy ra sự cố như hỏng máy, nhiễm virus hay xoá nhầm.","t":"tin-cap1","l":"thu-thach"},{"p":"Phần mềm diệt virus KHÔNG làm được việc nào sau đây?","o":["Quét và phát hiện mã độc trong máy","Ngăn chặn tệp độc hại chạy trên máy","Khôi phục dữ liệu đã bị xoá mất mà chưa từng sao lưu","Cập nhật dữ liệu nhận diện virus mới"],"a":"Khôi phục dữ liệu đã bị xoá mất mà chưa từng sao lưu","h":"Việc khôi phục dữ liệu đã mất phụ thuộc vào bản sao lưu.","e":"Phần mềm diệt virus chỉ phòng và xử lí mã độc; dữ liệu đã mất chỉ khôi phục được nếu đã sao lưu từ trước.","t":"tin-cap2","l":"kho"},{"p":"Khi sử dụng mạng xã hội, em chỉ nên kết bạn với ai?","o":["Bất kì ai gửi lời mời kết bạn","Những người em quen biết ngoài đời thực","Những tài khoản có nhiều người theo dõi","Những người ở nước ngoài cho vui"],"a":"Những người em quen biết ngoài đời thực","h":"Người lạ trên mạng có thể không phải người tốt.","e":"Chỉ kết bạn với người quen biết giúp em tránh bị lừa đảo và tiếp cận bởi người xấu.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Cài đặt quyền riêng tư trên mạng xã hội giúp em làm gì?","o":["Tăng số người theo dõi nhanh hơn","Kiểm soát ai có thể xem thông tin và bài đăng của em","Đăng bài được dài hơn","Xem được bài đăng của mọi người khác"],"a":"Kiểm soát ai có thể xem thông tin và bài đăng của em","h":"Riêng tư nghĩa là giới hạn người xem.","e":"Quyền riêng tư cho phép em giới hạn phạm vi người xem, ví dụ chỉ bạn bè mới xem được bài đăng và thông tin cá nhân.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Việc làm nào sau đây KHÔNG nên làm trên mạng xã hội?","o":["Chia sẻ vị trí trực tiếp cho mọi người biết em đang ở đâu","Đặt ảnh đại diện là hình hoạt hình","Chỉ cho bạn bè xem bài đăng","Đọc tin tức từ các trang chính thống"],"a":"Chia sẻ vị trí trực tiếp cho mọi người biết em đang ở đâu","h":"Thông tin về vị trí có thể bị kẻ xấu lợi dụng.","e":"Chia sẻ vị trí trực tiếp khiến người lạ biết em đang ở đâu, gây nguy hiểm cho bản thân.","t":"tin-cap2","l":"thu-thach"},{"p":"Một người lạ trên mạng xã hội nhắn tin hỏi địa chỉ nhà và tên trường của em. Em nên làm gì?","o":["Trả lời đầy đủ vì họ hỏi lịch sự","Không cung cấp thông tin cá nhân, có thể chặn hoặc báo cáo tài khoản đó","Hỏi lại địa chỉ của họ trước","Gửi ảnh chụp thẻ học sinh cho họ xem"],"a":"Không cung cấp thông tin cá nhân, có thể chặn hoặc báo cáo tài khoản đó","h":"Thông tin cá nhân không được chia sẻ cho người lạ.","e":"Tuyệt đối không cho người lạ thông tin cá nhân; nên chặn, báo cáo và nói với người lớn khi cần.","t":"tin-cap1","l":"thu-thach"},{"p":"Trước khi đăng ảnh có mặt bạn của em lên mạng xã hội, em nên làm gì?","o":["Đăng ngay vì ảnh chụp rất đẹp","Xin phép bạn trước khi đăng","Gắn thẻ càng nhiều người càng tốt","Chỉnh sửa ảnh tuỳ ý rồi đăng"],"a":"Xin phép bạn trước khi đăng","h":"Ảnh của người khác cũng cần được tôn trọng.","e":"Xin phép trước khi đăng ảnh người khác là ứng xử văn minh và tôn trọng quyền riêng tư của bạn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Một tài khoản mạng xã hội để chế độ công khai, thường xuyên đăng vị trí đang ở và ảnh chụp thẻ học sinh. Nguy cơ lớn nhất là gì?","o":["Bị ít người theo dõi hơn","Người xấu thu thập được thông tin cá nhân để lừa đảo hoặc gây hại","Bài đăng hiển thị chậm hơn","Bị mạng xã hội thu phí đăng bài"],"a":"Người xấu thu thập được thông tin cá nhân để lừa đảo hoặc gây hại","h":"Công khai quá nhiều thông tin giúp kẻ xấu biết những gì về em?","e":"Đăng công khai vị trí và giấy tờ cá nhân giúp kẻ xấu nắm thông tin để lừa đảo, giả mạo hoặc tìm đến gây hại.","t":"tin-cap2","l":"kho"},{"p":"Tin giả (fake news) là gì?","o":["Tin tức được đăng trên báo chính thống","Thông tin sai sự thật nhưng được lan truyền như tin thật","Tin tức cũ đã qua lâu ngày","Tin tức chỉ có ít người đọc"],"a":"Thông tin sai sự thật nhưng được lan truyền như tin thật","h":"Fake trong tiếng Anh nghĩa là giả.","e":"Tin giả là thông tin bịa đặt hoặc sai lệch, được phát tán khiến nhiều người tưởng là thật.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Khi thấy một tin gây sốc lan truyền trên mạng, việc đầu tiên em nên làm là gì?","o":["Chia sẻ ngay cho bạn bè cùng biết","Kiểm chứng nguồn tin trước khi tin và chia sẻ","Bình luận thật nhiều để tin nổi hơn","Lưu lại để sau này kiểm chứng"],"a":"Kiểm chứng nguồn tin trước khi tin và chia sẻ","h":"Đừng vội tin, hãy kiểm tra trước.","e":"Kiểm chứng nguồn tin giúp em tránh tin và lan truyền thông tin sai sự thật.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Dấu hiệu nào sau đây cho thấy một tin tức trên mạng có thể là tin giả?","o":["Tin được nhiều báo uy tín cùng đăng","Tiêu đề giật gân, nguồn không rõ ràng và không thấy ở các báo uy tín","Tin có ghi rõ tác giả và ngày đăng","Tin được cơ quan nhà nước thông báo"],"a":"Tiêu đề giật gân, nguồn không rõ ràng và không thấy ở các báo uy tín","h":"Tin giả thường cố thu hút bằng cảm xúc mạnh.","e":"Tin giả thường có tiêu đề giật gân, thiếu nguồn tin cậy và không được các cơ quan báo chí uy tín đăng tải.","t":"tin-cap2","l":"thu-thach"},{"p":"Để kiểm chứng một thông tin trên mạng có đúng hay không, em nên làm gì?","o":["Chỉ đọc bình luận của người khác dưới bài viết","Đối chiếu thông tin ở nhiều nguồn tin uy tín khác nhau","Tin ngay nếu bài viết có nhiều lượt thích","Hỏi ý kiến một người bạn bất kì"],"a":"Đối chiếu thông tin ở nhiều nguồn tin uy tín khác nhau","h":"Một nguồn duy nhất có thể sai; nhiều nguồn uy tín cùng khẳng định sẽ đáng tin hơn.","e":"Đối chiếu ở nhiều nguồn uy tín là cách kiểm chứng thông tin hiệu quả trước khi tin và chia sẻ.","t":"tin-cap2","l":"thu-thach"},{"p":"Bạn em chia sẻ một bài viết quảng cáo thuốc chữa bệnh chưa rõ nguồn gốc và rủ em chia sẻ tiếp. Em nên khuyên bạn điều gì?","o":["Chia sẻ ngay vì biết đâu giúp được người bệnh","Không chia sẻ tin chưa kiểm chứng, nên tra cứu ở nguồn y tế chính thống vì tin sai về sức khoẻ rất nguy hiểm","Chỉ chia sẻ cho người thân trong gia đình","Chia sẻ kèm dòng chữ 'nghe nói thế' là được"],"a":"Không chia sẻ tin chưa kiểm chứng, nên tra cứu ở nguồn y tế chính thống vì tin sai về sức khoẻ rất nguy hiểm","h":"Tin giả về sức khoẻ có thể làm người bệnh bỏ qua cách chữa đúng.","e":"Không lan truyền tin chưa kiểm chứng; thông tin sức khoẻ phải tra cứu từ cơ quan y tế và báo chí chính thống.","t":"tin-cap2","l":"kho"},{"p":"Địa chỉ tuyệt đối trong bảng tính có đặc điểm gì?","o":["Không có tên cột và số hàng","Có dấu $ trước tên cột và số hàng, ví dụ $A$1","Luôn nằm ở ô đầu tiên của bảng","Tự thay đổi khi sao chép công thức"],"a":"Có dấu $ trước tên cột và số hàng, ví dụ $A$1","h":"Dấu $ là dấu hiệu nhận biết.","e":"Địa chỉ tuyệt đối được viết với dấu $ trước cột và hàng, ví dụ $A$1.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Tác dụng của địa chỉ tuyệt đối khi sao chép công thức là gì?","o":["Giúp công thức tính nhanh hơn","Địa chỉ ô đó không thay đổi dù sao chép công thức tới vị trí nào","Tự động xoá các ô không cần thiết","Đổi màu cho ô chứa công thức"],"a":"Địa chỉ ô đó không thay đổi dù sao chép công thức tới vị trí nào","h":"Tuyệt đối nghĩa là cố định, không đổi.","e":"Địa chỉ tuyệt đối giữ nguyên khi sao chép công thức, thường dùng cho các giá trị cố định như tỉ lệ, đơn giá.","t":"tin-cap2","l":"thu-thach"},{"p":"Biểu đồ tròn thường được dùng để thể hiện điều gì?","o":["Sự thay đổi của dữ liệu theo thời gian","Tỉ lệ phần trăm của các phần trong một tổng thể","So sánh chiều cao của các cột dữ liệu","Mối quan hệ giữa hai đại lượng"],"a":"Tỉ lệ phần trăm của các phần trong một tổng thể","h":"Cả hình tròn là 100%.","e":"Biểu đồ tròn chia tổng thể thành các phần theo tỉ lệ phần trăm, thích hợp để xem cơ cấu.","t":"tin-cap2","l":"thu-thach"},{"p":"Biểu đồ đường thường được dùng để thể hiện điều gì?","o":["Sự thay đổi, xu hướng của dữ liệu theo thời gian","Tỉ lệ phần trăm trong một tổng thể","Danh sách học sinh của lớp","Kết quả của một phép tính"],"a":"Sự thay đổi, xu hướng của dữ liệu theo thời gian","h":"Đường nối các điểm cho thấy dữ liệu lên xuống thế nào.","e":"Biểu đồ đường thích hợp để theo dõi xu hướng biến đổi của dữ liệu qua các mốc thời gian.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Hàm SUMIF trong bảng tính dùng để làm gì?","o":["Tính tổng tất cả các số trong bảng","Tính tổng các ô thoả mãn một điều kiện cho trước","Đếm số ô có dữ liệu","Tìm giá trị trung bình của một vùng"],"a":"Tính tổng các ô thoả mãn một điều kiện cho trước","h":"SUM là tổng, IF là điều kiện.","e":"SUMIF tính tổng có điều kiện, chỉ cộng những ô đáp ứng điều kiện đã cho.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Ô C1 có công thức =A1*$B$1. Khi sao chép công thức xuống ô C2, công thức ở C2 sẽ là gì?","o":["=A1*$B$1","=A2*$B$1","=A2*$B$2","=A1*$B$2"],"a":"=A2*$B$1","h":"Phần có dấu $ giữ nguyên, phần còn lại thay đổi theo hàng.","e":"A1 là địa chỉ tương đối nên thành A2; $B$1 là địa chỉ tuyệt đối nên giữ nguyên khi sao chép.","t":"tin-cap2","l":"kho"},{"p":"Một ô chứa giá trị 0,25. Khi định dạng ô theo kiểu phần trăm (Percent), ô sẽ hiển thị thế nào?","o":["0,25%","25%","250%","2,5%"],"a":"25%","h":"Đổi số thập phân sang phần trăm bằng cách nhân với 100.","e":"0,25 bằng 25/100 nên khi định dạng phần trăm sẽ hiển thị là 25%.","t":"tin-cap2","l":"thu-thach"},{"p":"Sắp xếp dữ liệu giảm dần trong bảng tính nghĩa là sắp xếp thế nào?","o":["Từ giá trị nhỏ nhất đến lớn nhất","Từ giá trị lớn nhất đến nhỏ nhất","Theo thứ tự nhập dữ liệu ban đầu","Theo màu sắc của ô dữ liệu"],"a":"Từ giá trị lớn nhất đến nhỏ nhất","h":"Giảm dần là đi xuống.","e":"Sắp xếp giảm dần xếp dữ liệu từ lớn đến bé, ví dụ điểm số từ cao xuống thấp.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Bảng điểm được sắp xếp theo cột tổng điểm giảm dần. Học sinh có tổng điểm cao nhất sẽ nằm ở đâu?","o":["Ở cuối danh sách","Ở đầu danh sách","Ở giữa danh sách","Bị ẩn khỏi danh sách"],"a":"Ở đầu danh sách","h":"Giảm dần bắt đầu từ giá trị lớn nhất.","e":"Sắp xếp giảm dần đưa giá trị lớn nhất lên đầu nên học sinh điểm cao nhất đứng đầu danh sách.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Từ bảng dữ liệu chung của cả lớp, em muốn vẽ biểu đồ chỉ thể hiện học sinh nữ. Việc nên làm trước khi vẽ biểu đồ là gì?","o":["Xoá hết dữ liệu của học sinh nam","Lọc dữ liệu để chỉ hiển thị học sinh nữ rồi vẽ biểu đồ trên dữ liệu đã lọc","Đổi màu chữ của học sinh nữ","Sao chép bảng sang một tệp hoàn toàn mới"],"a":"Lọc dữ liệu để chỉ hiển thị học sinh nữ rồi vẽ biểu đồ trên dữ liệu đã lọc","h":"Lọc giúp chọn đúng nhóm dữ liệu cần xem mà không xoá dữ liệu gốc.","e":"Lọc dữ liệu chọn ra nhóm cần thiết, sau đó biểu đồ sẽ thể hiện đúng nhóm dữ liệu đã lọc.","t":"tin-cap2","l":"thu-thach"},{"p":"Khi lọc dữ liệu trong bảng tính, các hàng không thoả mãn điều kiện lọc sẽ thế nào?","o":["Bị xoá vĩnh viễn khỏi bảng","Bị ẩn đi tạm thời, dữ liệu vẫn còn nguyên","Bị chuyển sang một bảng tính khác","Bị đổi thành số 0"],"a":"Bị ẩn đi tạm thời, dữ liệu vẫn còn nguyên","h":"Bỏ lọc đi thì dữ liệu có hiện lại không?","e":"Lọc chỉ ẩn tạm thời các hàng không thoả điều kiện; khi bỏ lọc, toàn bộ dữ liệu hiện lại đầy đủ.","t":"tin-cap2","l":"kho"},{"p":"Trong Scratch, khối lệnh 'hỏi ... và chờ' dùng để làm gì?","o":["Hiển thị lời thoại của nhân vật","Hỏi người chơi và nhận câu trả lời do người chơi nhập vào","Đặt câu hỏi cho giáo viên","Tạm dừng chương trình mãi mãi"],"a":"Hỏi người chơi và nhận câu trả lời do người chơi nhập vào","h":"Khối này thuộc nhóm Cảm biến, dùng trong trò chơi hỏi đáp.","e":"Khối 'hỏi và chờ' hiển thị câu hỏi và chờ người chơi gõ câu trả lời để chương trình xử lí tiếp.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong Scratch, câu trả lời do người chơi nhập vào sau khối 'hỏi và chờ' được lưu ở đâu?","o":["Trong khối 'trả lời'","Trong tên của nhân vật","Trong hình nền sân khấu","Trong khối âm thanh"],"a":"Trong khối 'trả lời'","h":"Có một khối riêng cùng nhóm Cảm biến giữ nội dung này.","e":"Nội dung người chơi nhập được lưu trong khối 'trả lời' để các lệnh sau có thể sử dụng.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Muốn trò chơi Scratch kết thúc khi nhân vật chạm vào chướng ngại vật, em dùng nhóm khối nào?","o":["Khối cảm biến kiểm tra 'chạm vào ...' kết hợp khối điều kiện","Khối âm thanh phát tiếng","Khối bút vẽ lên sân khấu","Khối thay đổi trang phục"],"a":"Khối cảm biến kiểm tra 'chạm vào ...' kết hợp khối điều kiện","h":"Cần phát hiện sự va chạm trước rồi mới xử lí.","e":"Khối cảm biến 'chạm vào' trong khối điều kiện giúp chương trình phát hiện va chạm và thực hiện hành động như dừng trò chơi.","t":"tin-cap2","l":"thu-thach"},{"p":"Khối lệnh 'tạo bản sao của chính tôi' trong Scratch có tác dụng gì?","o":["Lưu chương trình thành một tệp mới","Tạo thêm một nhân vật giống hệt để hoạt động độc lập","Xoá nhân vật khỏi sân khấu","Đổi tên cho nhân vật"],"a":"Tạo thêm một nhân vật giống hệt để hoạt động độc lập","h":"Bản sao trong tiếng Anh là clone.","e":"Tạo bản sao giúp sinh ra nhiều nhân vật giống nhau, ví dụ nhiều quả táo rơi cùng lúc trong trò chơi hứng táo.","t":"tin-cap2","l":"thu-thach"},{"p":"Trò chơi hứng táo trong Scratch: mỗi lần quả táo chạm vào giỏ, điểm tăng thêm 1. Khối lệnh nào xử lí việc tăng điểm?","o":["Khối 'thay đổi Điểm thêm 1' đặt trong điều kiện khi táo chạm giỏ","Khối 'nói Xin chào trong 2 giây'","Khối 'phát âm thanh' đặt ở đầu chương trình","Khối 'đi tới vị trí ngẫu nhiên' đặt riêng lẻ"],"a":"Khối 'thay đổi Điểm thêm 1' đặt trong điều kiện khi táo chạm giỏ","h":"Điểm chỉ tăng đúng vào thời điểm táo chạm giỏ.","e":"Khi điều kiện chạm giỏ đúng, lệnh thay đổi biến Điểm thêm 1 được thực hiện, đúng với luật của trò chơi.","t":"tin-cap2","l":"kho"},{"p":"Cắt ảnh (crop) là thao tác chỉnh sửa ảnh nào?","o":["Thay đổi màu sắc của toàn bộ ảnh","Cắt bỏ phần thừa xung quanh, giữ lại phần ảnh cần dùng","Ghép nhiều ảnh thành một ảnh","Làm mờ toàn bộ ảnh"],"a":"Cắt bỏ phần thừa xung quanh, giữ lại phần ảnh cần dùng","h":"Giống như dùng kéo cắt bỏ viền thừa của tờ giấy.","e":"Cắt ảnh loại bỏ phần không cần thiết ở các cạnh, giúp bức ảnh tập trung vào chủ thể chính.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Một bức ảnh chụp bị nghiêng. Em dùng thao tác nào để sửa?","o":["Cắt ảnh","Xoay ảnh","Đổi tên tệp ảnh","Nén ảnh"],"a":"Xoay ảnh","h":"Cần đưa ảnh về hướng thẳng đứng bình thường.","e":"Thao tác xoay ảnh giúp chỉnh lại hướng của ảnh bị nghiêng hoặc bị ngược.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Một bức ảnh chụp thiếu sáng, trông quá tối. Em nên chỉnh thông số nào?","o":["Tăng độ sáng của ảnh","Giảm kích thước tệp ảnh","Đổi định dạng của ảnh","Xoá phông nền của ảnh"],"a":"Tăng độ sáng của ảnh","h":"Ảnh tối cần thêm sáng.","e":"Tăng độ sáng (và có thể thêm tương phản) giúp bức ảnh tối trở nên rõ ràng, dễ nhìn hơn.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Âm thanh số là gì?","o":["Âm thanh phát ra từ loa của máy tính","Âm thanh được ghi lại và biểu diễn dưới dạng dữ liệu số để máy tính lưu trữ, xử lí và phát lại","Tên một phần mềm nghe nhạc","Âm thanh chỉ nghe được bằng tai nghe"],"a":"Âm thanh được ghi lại và biểu diễn dưới dạng dữ liệu số để máy tính lưu trữ, xử lí và phát lại","h":"Giống như ảnh số, âm thanh cũng được số hoá.","e":"Âm thanh số là âm thanh đã được chuyển thành dữ liệu số, có thể lưu trong tệp, chỉnh sửa và phát lại bằng thiết bị số.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Tin nhắn tự xưng là ngân hàng, yêu cầu em cung cấp mã OTP để 'tránh bị khoá tài khoản'. Đây là dấu hiệu của điều gì?","o":["Chương trình khuyến mãi của ngân hàng","Hành vi lừa đảo mạo danh để chiếm đoạt tài khoản","Thông báo bảo mật bình thường","Lỗi hệ thống của ngân hàng"],"a":"Hành vi lừa đảo mạo danh để chiếm đoạt tài khoản","h":"Ngân hàng không bao giờ hỏi mã OTP qua tin nhắn.","e":"Kẻ xấu mạo danh ngân hàng để dụ cung cấp mã OTP và chiếm tiền trong tài khoản; ngân hàng không bao giờ yêu cầu mã OTP như vậy.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em nhận được tin nhắn lạ tự xưng là nhà trường, yêu cầu chuyển tiền học qua một đường liên kết. Em nên làm gì?","o":["Chuyển tiền ngay để không bị ghi nợ học phí","Không bấm liên kết và không chuyển tiền, kiểm chứng lại qua giáo viên hoặc số điện thoại chính thức của trường","Chia sẻ tin nhắn cho bạn bè để cùng chuyển","Cung cấp thông tin tài khoản để họ kiểm tra"],"a":"Không bấm liên kết và không chuyển tiền, kiểm chứng lại qua giáo viên hoặc số điện thoại chính thức của trường","h":"Mọi yêu cầu chuyển tiền qua liên kết lạ đều đáng ngờ.","e":"Cần kiểm chứng qua kênh chính thức trước khi làm theo bất kì yêu cầu chuyển tiền nào nhận qua tin nhắn lạ.","t":"tin-cap2","l":"thu-thach"},{"p":"Khi dùng Wi-Fi công cộng miễn phí ở quán cà phê, việc làm nào sau đây tiềm ẩn rủi ro?","o":["Đọc tin tức trên báo điện tử","Đăng nhập tài khoản ngân hàng và giao dịch chuyển tiền","Xem dự báo thời tiết","Nghe nhạc trực tuyến"],"a":"Đăng nhập tài khoản ngân hàng và giao dịch chuyển tiền","h":"Wi-Fi công cộng không được bảo vệ, kẻ xấu có thể nghe lén dữ liệu.","e":"Wi-Fi công cộng kém an toàn, thông tin đăng nhập và giao dịch quan trọng có thể bị đánh cắp.","t":"tin-cap2","l":"thu-thach"},{"p":"Em nhận được tin nhắn giống hệt thông báo của ngân hàng, kèm đường liên kết đăng nhập để 'xác minh tài khoản'. Cách xử lí đúng nhất là gì?","o":["Bấm ngay vào liên kết trong tin nhắn và đăng nhập","Không dùng liên kết trong tin nhắn; tự mở ứng dụng hoặc trang web chính thức của ngân hàng để kiểm tra","Chuyển tiếp tin nhắn cho bạn bè để hỏi ý kiến","Trả lời tin nhắn để hỏi lại ngân hàng"],"a":"Không dùng liên kết trong tin nhắn; tự mở ứng dụng hoặc trang web chính thức của ngân hàng để kiểm tra","h":"Liên kết trong tin nhắn có thể dẫn tới trang giả mạo giống hệt trang thật.","e":"Trang đăng nhập giả mạo qua liên kết lạ là bẫy lừa đảo quen thuộc; luôn tự truy cập kênh chính thức của ngân hàng.","t":"tin-cap2","l":"kho"},{"p":"Trong Python, phép toán 10 % 3 cho kết quả bằng bao nhiêu?","o":["0","1","3","10"],"a":"1","h":"% là phép chia lấy phần dư.","e":"10 chia cho 3 được 3, dư 1 nên 10 % 3 = 1.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong Python, 2 ** 3 cho kết quả bằng bao nhiêu?","o":["6","8","9","5"],"a":"8","h":"** là phép luỹ thừa.","e":"2 ** 3 nghĩa là 2 × 2 × 2 = 8.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong Python, toán tử == được dùng để làm gì?","o":["Gán giá trị cho biến","So sánh hai giá trị có bằng nhau không","Cộng hai số với nhau","In kết quả ra màn hình"],"a":"So sánh hai giá trị có bằng nhau không","h":"Đừng nhầm với dấu = dùng để gán.","e":"== là phép so sánh bằng, cho kết quả True nếu hai giá trị bằng nhau.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Hàm len('Python') cho kết quả bằng bao nhiêu?","o":["5","6","7","12"],"a":"6","h":"Hãy đếm từng kí tự trong chuỗi.","e":"Chuỗi 'Python' có 6 kí tự: P, y, t, h, o, n.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong Python, biểu thức so sánh 5 != 5 cho kết quả là gì?","o":["True","False","5","Chương trình báo lỗi"],"a":"False","h":"!= nghĩa là 'khác nhau'.","e":"5 != 5 nghĩa là '5 khác 5'; điều này sai nên kết quả là False.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong Python, biểu thức 'Ha' + 'Noi' cho kết quả nào?","o":["HaNoi","Ha Noi","Ha+Noi","Chương trình báo lỗi"],"a":"HaNoi","h":"Dấu + với chuỗi có tác dụng nối chuỗi.","e":"Dấu + nối hai chuỗi lại liền nhau thành 'HaNoi'.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong Python, biểu thức 'ab' * 3 cho kết quả nào?","o":["ababab","ab3","ab ab ab","Chương trình báo lỗi"],"a":"ababab","h":"Một chuỗi có thể được lặp lại nhiều lần.","e":"'ab' * 3 lặp lại chuỗi 'ab' ba lần, được 'ababab'.","t":"tin-cap2","l":"thu-thach"},{"p":"Bạn Bình đọc được một số dưới dạng chuỗi '15' và muốn chuyển thành số nguyên để tính toán. Bạn cần dùng hàm nào?","o":["str()","int()","print()","len()"],"a":"int()","h":"Tên hàm gợi nhớ đến từ 'integer' (số nguyên).","e":"Hàm int() chuyển một chuỗi số như '15' thành số nguyên 15.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong Python, biểu thức (5 > 3) and (2 < 1) cho kết quả là gì?","o":["True","False","Lỗi cú pháp","Không xác định được"],"a":"False","h":"Phép and chỉ đúng khi cả hai vế đều đúng.","e":"(5 > 3) là True nhưng (2 < 1) là False; phép and cần cả hai cùng đúng nên kết quả là False.","t":"tin-cap2","l":"kho"},{"p":"Trong Python, biểu thức (7 % 4) + (2 ** 3) cho kết quả bằng bao nhiêu?","o":["10","11","12","15"],"a":"11","h":"Tính từng phần trước: 7 % 4 bằng mấy, 2 ** 3 bằng mấy?","e":"7 % 4 = 3 và 2 ** 3 = 8, vậy 3 + 8 = 11.","t":"tin-cap2","l":"kho"},{"p":"Cấu trúc if / elif / else trong chương trình được dùng khi nào?","o":["Khi cần lặp lại một lệnh nhiều lần","Khi cần lựa chọn thực hiện lệnh tuỳ theo điều kiện","Khi cần khai báo một biến mới","Khi cần lưu dữ liệu vào tệp"],"a":"Khi cần lựa chọn thực hiện lệnh tuỳ theo điều kiện","h":"Đây còn gọi là cấu trúc rẽ nhánh.","e":"if/elif/else giúp chương trình rẽ nhánh: kiểm tra điều kiện để chọn khối lệnh phù hợp.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Vòng lặp while trong Python thường được dùng khi nào?","o":["Khi biết trước chính xác số lần lặp","Khi muốn lặp lại lệnh trong lúc điều kiện còn đúng","Khi muốn khai báo một danh sách","Khi muốn in kết quả ra màn hình"],"a":"Khi muốn lặp lại lệnh trong lúc điều kiện còn đúng","h":"while trong tiếng Anh nghĩa là 'trong khi'.","e":"Vòng while kiểm tra điều kiện trước mỗi vòng lặp; điều kiện còn đúng thì còn lặp.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Cho đoạn chương trình: x = 7; if x > 5: print('Lớn') else: print('Nhỏ'). Chương trình in ra gì?","o":["Lớn","Nhỏ","7","Không in gì cả"],"a":"Lớn","h":"Hãy so sánh 7 với 5 trước.","e":"7 > 5 là đúng nên chương trình thực hiện lệnh ở nhánh if và in ra 'Lớn'.","t":"tin-cap2","l":"thu-thach"},{"p":"Cho đoạn chương trình: s = 0; i = 1; while i <= 3: s = s + i; i = i + 1; print(s). Kết quả in ra là bao nhiêu?","o":["3","5","6","9"],"a":"6","h":"Cộng lần lượt i = 1, 2, 3 vào s.","e":"Qua ba vòng lặp, s = 0 + 1 + 2 + 3 = 6.","t":"tin-cap2","l":"kho"},{"p":"Trong Python, giá trị 2024 thuộc kiểu dữ liệu nào?","o":["Số nguyên (int)","Số thực (float)","Chuỗi kí tự (str)","Danh sách (list)"],"a":"Số nguyên (int)","h":"Giá trị này không có phần thập phân.","e":"Số 2024 là số nguyên nên thuộc kiểu dữ liệu int trong Python.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Cho danh sách a = [10, 20, 30]. Phần tử đầu tiên của danh sách có chỉ số là bao nhiêu?","o":["1","0","10","-1"],"a":"0","h":"Trong Python, việc đánh chỉ số bắt đầu rất đặc biệt.","e":"Python đánh chỉ số bắt đầu từ 0, nên phần tử đầu tiên có chỉ số 0.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Cho danh sách a = [2, 4, 6, 8, 10]. Giá trị của biểu thức len(a) - a[0] bằng bao nhiêu?","o":["2","3","5","8"],"a":"3","h":"Tính len(a) và a[0] riêng trước rồi trừ.","e":"len(a) = 5 phần tử, a[0] = 2, vậy 5 - 2 = 3.","t":"tin-cap2","l":"kho"},{"p":"Cho danh sách a = [5, 10, 15]. Giá trị của a[0] + a[2] bằng bao nhiêu?","o":["15","20","25","30"],"a":"20","h":"a[0] là phần tử đầu tiên, a[2] là phần tử thứ ba.","e":"a[0] = 5 và a[2] = 15 nên tổng là 20.","t":"tin-cap2","l":"kho"},{"p":"Lỗi cú pháp (syntax error) trong chương trình là lỗi gì?","o":["Lỗi do máy tính bị hỏng phần cứng","Lỗi viết sai quy tắc của ngôn ngữ lập trình","Lỗi do mất kết nối mạng","Lỗi do người dùng nhập dữ liệu chậm"],"a":"Lỗi viết sai quy tắc của ngôn ngữ lập trình","h":"Ví dụ như thiếu dấu ngoặc hoặc viết sai từ khoá.","e":"Lỗi cú pháp xảy ra khi câu lệnh viết không đúng quy tắc của ngôn ngữ, khiến chương trình không chạy được.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Vì sao sau khi viết chương trình, người lập trình cần kiểm thử chương trình?","o":["Để chương trình có giao diện đẹp hơn","Để phát hiện và sửa các lỗi trước khi sử dụng thật","Để đổi tên cho chương trình","Để in chương trình ra giấy"],"a":"Để phát hiện và sửa các lỗi trước khi sử dụng thật","h":"Kiểm thử giống như kiểm tra lại bài làm trước khi nộp.","e":"Kiểm thử là chạy thử chương trình với nhiều dữ liệu khác nhau để tìm và sửa lỗi sớm.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Bạn An viết lệnh print('Xin chào' nhưng quên dấu đóng ngoặc ). Khi chạy, chương trình báo lỗi. Đây là loại lỗi nào?","o":["Lỗi cú pháp","Lỗi logic","Lỗi dữ liệu","Không phải là lỗi"],"a":"Lỗi cú pháp","h":"Thiếu dấu ngoặc là viết sai quy tắc viết lệnh.","e":"Thiếu dấu đóng ngoặc khiến câu lệnh không đúng cấu trúc, đó là lỗi cú pháp.","t":"tin-cap2","l":"thu-thach"},{"p":"Một chương trình chạy được bình thường, không báo lỗi, nhưng cho kết quả tính toán sai so với yêu cầu. Đây là loại lỗi nào?","o":["Lỗi cú pháp","Lỗi logic (sai thuật toán)","Lỗi phần cứng","Lỗi hệ điều hành"],"a":"Lỗi logic (sai thuật toán)","h":"Chương trình 'chạy được' nhưng 'nghĩ sai'.","e":"Lỗi logic xảy ra khi thuật toán hoặc công thức chưa đúng, chương trình vẫn chạy nhưng cho kết quả sai.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong một bảng dữ liệu, khoá chính có vai trò gì?","o":["Giúp sắp xếp dữ liệu theo bảng chữ cái","Giúp phân biệt từng bản ghi, không có hai bản ghi nào trùng giá trị khoá chính","Giúp xoá nhanh dữ liệu cũ","Giúp in bảng dữ liệu ra giấy"],"a":"Giúp phân biệt từng bản ghi, không có hai bản ghi nào trùng giá trị khoá chính","h":"Hãy liên tưởng tới mã học sinh riêng của mỗi bạn trong lớp.","e":"Khoá chính nhận diện duy nhất mỗi bản ghi, giống như mã học sinh không bạn nào trùng nhau.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Phần mềm nào sau đây là một hệ quản trị cơ sở dữ liệu?","o":["Microsoft Word","Microsoft Access","Paint","Windows Media Player"],"a":"Microsoft Access","h":"Hệ quản trị CSDL giúp tạo và quản lí các bảng dữ liệu.","e":"Microsoft Access là hệ quản trị cơ sở dữ liệu phổ biến được giới thiệu trong chương trình phổ thông.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Thư viện trường dùng cơ sở dữ liệu để quản lí mượn sách. Để biết một quyển sách đang được bạn nào mượn, thủ thư nên làm gì?","o":["Đếm lại toàn bộ sách trên kệ","Tra cứu trong bảng dữ liệu quản lí mượn — trả sách","Hỏi từng học sinh trong trường","In lại toàn bộ danh mục sách"],"a":"Tra cứu trong bảng dữ liệu quản lí mượn — trả sách","h":"Điểm mạnh nhất của CSDL là tìm kiếm nhanh.","e":"Chỉ cần tra cứu theo tên sách trong bảng mượn — trả là biết ngay bạn nào đang mượn.","t":"tin-cap2","l":"thu-thach"},{"p":"Một siêu thị dùng cơ sở dữ liệu để quản lí bán hàng. Cơ sở dữ liệu hỗ trợ tốt nhất cho việc nào sau đây?","o":["Trang trí cửa hàng đẹp hơn","Tra cứu nhanh thông tin và giá của hàng hoá khi tính tiền","Tự động nấu ăn cho nhân viên","Phát nhạc trong siêu thị"],"a":"Tra cứu nhanh thông tin và giá của hàng hoá khi tính tiền","h":"Hãy nghĩ tới lúc nhân viên quét mã vạch ở quầy thu ngân.","e":"Khi quét mã hàng, CSDL cho ngay tên và giá sản phẩm, giúp tính tiền nhanh và chính xác.","t":"tin-cap2","l":"thu-thach"},{"p":"Lập trình viên là người làm công việc nào?","o":["Sửa chữa phần cứng máy tính","Viết các chương trình và phần mềm máy tính","Bán máy tính tại cửa hàng","Dạy thể dục cho học sinh"],"a":"Viết các chương trình và phần mềm máy tính","h":"Tên nghề gắn liền với từ 'lập trình'.","e":"Lập trình viên dùng ngôn ngữ lập trình để tạo ra các phần mềm phục vụ nhu cầu khác nhau.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Thương mại điện tử là gì?","o":["Việc mua bán hàng hoá và dịch vụ qua mạng Internet","Việc học trực tuyến qua video","Việc gửi thư điện tử cho bạn bè","Việc chơi trò chơi trực tuyến"],"a":"Việc mua bán hàng hoá và dịch vụ qua mạng Internet","h":"Ví dụ: mua hàng trên các sàn như Shopee, Tiki.","e":"Thương mại điện tử cho phép chọn hàng, thanh toán và nhận hàng mà không cần đến trực tiếp cửa hàng.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Quản trị mạng là người đảm nhiệm công việc nào?","o":["Thiết kế bìa sách và tờ rơi","Quản lí, vận hành và đảm bảo hệ thống mạng máy tính hoạt động ổn định","Viết bài quảng cáo cho trang web","Thu ngân tại siêu thị"],"a":"Quản lí, vận hành và đảm bảo hệ thống mạng máy tính hoạt động ổn định","h":"Tên nghề gắn liền với 'mạng máy tính'.","e":"Quản trị mạng cài đặt, theo dõi và xử lí sự cố để mạng của cơ quan, trường học luôn thông suốt.","t":"tin-cap2","l":"thu-thach"},{"p":"Dịch vụ công trực tuyến giúp người dân thuận tiện nhất ở điểm nào?","o":["Được mua hàng giảm giá mỗi ngày","Làm các thủ tục hành chính qua mạng mà không phải đến trực tiếp cơ quan","Xem phim miễn phí không giới hạn","Chơi trò chơi cùng bạn bè"],"a":"Làm các thủ tục hành chính qua mạng mà không phải đến trực tiếp cơ quan","h":"Ví dụ: đăng kí làm căn cước qua cổng dịch vụ công.","e":"Dịch vụ công trực tuyến giúp người dân nộp hồ sơ và nhận kết quả qua mạng, tiết kiệm thời gian đi lại.","t":"tin-cap2","l":"thu-thach"},{"p":"Điện toán đám mây (cloud computing) là gì?","o":["Một loại máy tính để bàn thế hệ mới","Việc lưu trữ và xử lí dữ liệu trên các máy chủ qua Internet thay vì chỉ trên máy cá nhân","Một kiểu mạng không dây trong gia đình","Phần mềm giúp làm mát máy tính"],"a":"Việc lưu trữ và xử lí dữ liệu trên các máy chủ qua Internet thay vì chỉ trên máy cá nhân","h":"Dữ liệu 'nằm trên Internet' nên dùng ở đâu cũng được.","e":"Với điện toán đám mây, dữ liệu được lưu trên máy chủ của nhà cung cấp và truy cập được qua Internet.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Ví dụ nào sau đây là ứng dụng của điện toán đám mây?","o":["Lưu ảnh và tài liệu trên Google Drive để xem trên nhiều thiết bị","Lưu tệp vào USB mang theo người","Ghi tệp ra đĩa CD","In tài liệu ra giấy để cất"],"a":"Lưu ảnh và tài liệu trên Google Drive để xem trên nhiều thiết bị","h":"Dịch vụ nào trong các lựa chọn hoạt động qua Internet?","e":"Google Drive là dịch vụ lưu trữ đám mây: tệp nằm trên máy chủ trực tuyến, mở được ở mọi nơi có Internet.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Thiết bị thông minh (ví dụ: đồng hồ thông minh, tivi thông minh) khác thiết bị thông thường chủ yếu ở điểm nào?","o":["Màn hình lớn hơn thiết bị thường","Có khả năng kết nối, thu thập và xử lí dữ liệu để phục vụ người dùng tốt hơn","Giá bán cao hơn thiết bị thường","Chỉ dùng pin sạc, không dùng điện trực tiếp"],"a":"Có khả năng kết nối, thu thập và xử lí dữ liệu để phục vụ người dùng tốt hơn","h":"Chữ 'thông minh' đến từ khả năng xử lí dữ liệu.","e":"Thiết bị thông minh có cảm biến, kết nối mạng và tự xử lí dữ liệu, ví dụ đồng hồ thông minh đo nhịp tim rồi đồng bộ với điện thoại.","t":"tin-cap3","l":"thu-thach"},{"p":"Các trang thương mại điện tử thường gợi ý đúng sản phẩm mà từng người dùng quan tâm. Khả năng này chủ yếu nhờ vào công nghệ nào?","o":["Phân tích dữ liệu lớn (Big Data)","Công nghệ in 3D","Thực tế tăng cường (AR)","Robot tự động trong kho hàng"],"a":"Phân tích dữ liệu lớn (Big Data)","h":"Hệ thống phải 'học' từ rất nhiều dữ liệu về hành vi mua sắm.","e":"Phân tích dữ liệu lớn từ lịch sử xem và mua hàng giúp hệ thống dự đoán sở thích của từng người dùng.","t":"tin-cap3","l":"thu-thach"},{"p":"Điều hoà thông minh có thể tự tăng hoặc giảm công suất để giữ nhiệt độ phòng luôn ổn định. Bộ phận nào giúp nó 'cảm nhận' được nhiệt độ trong phòng?","o":["Màn hình cảm ứng","Cảm biến nhiệt độ","Loa thông minh","Camera an ninh"],"a":"Cảm biến nhiệt độ","h":"'Cảm nhận' là nhiệm vụ của các cảm biến.","e":"Cảm biến nhiệt độ đo nhiệt độ phòng và gửi dữ liệu về bộ xử lí để điều hoà tự điều chỉnh.","t":"tin-cap3","l":"kho"},{"p":"WWW (World Wide Web) là gì?","o":["Tên của một trình duyệt web","Hệ thống các trang web và tài nguyên liên kết với nhau trên Internet","Một loại mạng máy tính trong nhà","Tên của một hệ điều hành"],"a":"Hệ thống các trang web và tài nguyên liên kết với nhau trên Internet","h":"WWW là viết tắt của World Wide Web.","e":"WWW là hệ thống thông tin gồm vô số trang web liên kết với nhau mà em truy cập qua trình duyệt.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong thư điện tử, 'tệp đính kèm' có nghĩa là gì?","o":["Thư bị đánh dấu là thư rác","Một tệp (ảnh, tài liệu...) được gửi kèm theo nội dung thư","Địa chỉ của người gửi thư","Mật khẩu của hộp thư"],"a":"Một tệp (ảnh, tài liệu...) được gửi kèm theo nội dung thư","h":"Hãy nhớ biểu tượng chiếc kẹp giấy trong hộp thư.","e":"Khi gửi email, ta có thể đính kèm thêm tệp như ảnh hoặc tài liệu để người nhận tải về xem.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Wi-Fi là công nghệ dùng để làm gì?","o":["Kết nối các thiết bị vào mạng mà không cần dây cáp","Sạc pin cho điện thoại nhanh hơn","Tăng dung lượng ổ cứng của máy tính","Gửi thư điện tử tự động"],"a":"Kết nối các thiết bị vào mạng mà không cần dây cáp","h":"Nhờ nó mà điện thoại vào mạng không cần cắm dây.","e":"Wi-Fi kết nối thiết bị với mạng bằng sóng vô tuyến trong phạm vi gần như nhà ở, trường học, quán cà phê.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Tên miền kết thúc bằng .edu.vn thường thuộc về tổ chức nào?","o":["Cơ quan nhà nước của Việt Nam","Cơ sở giáo dục (trường học) của Việt Nam","Doanh nghiệp thương mại nước ngoài","Tổ chức phi chính phủ quốc tế"],"a":"Cơ sở giáo dục (trường học) của Việt Nam","h":"'edu' là viết tắt của education (giáo dục).","e":".edu.vn là tên miền dành cho lĩnh vực giáo dục của Việt Nam, ví dụ trang web của các trường học.","t":"tin-cap3","l":"thu-thach"},{"p":"Khi em gõ 'tuoitre.vn' vào thanh địa chỉ của trình duyệt, cụm 'tuoitre.vn' được gọi là gì?","o":["Tên miền của trang web","Mật khẩu của trang web","Tên của trình duyệt","Địa chỉ thư điện tử"],"a":"Tên miền của trang web","h":"Nó giống như 'địa chỉ nhà' của trang web.","e":"Tên miền là địa chỉ dễ nhớ của một trang web trên Internet, thay cho địa chỉ IP dạng số khó nhớ.","t":"tin-cap3","l":"thu-thach"},{"p":"Hành vi nào sau đây bị cấm khi sử dụng mạng Internet?","o":["Chia sẻ ảnh chuyến du lịch của bản thân","Đưa thông tin sai sự thật, xuyên tạc gây ảnh hưởng xấu đến người khác","Học trực tuyến trên các trang học tập","Gửi thư điện tử cho bạn bè"],"a":"Đưa thông tin sai sự thật, xuyên tạc gây ảnh hưởng xấu đến người khác","h":"Hãy chọn hành vi gây hại cho người khác và xã hội.","e":"Pháp luật cấm lợi dụng mạng để đưa thông tin sai sự thật, xuyên tạc, xúc phạm danh dự của tổ chức và cá nhân.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Việc làm nào sau đây vi phạm bản quyền nội dung số?","o":["Đọc một bài viết trên báo điện tử","Chia sẻ đường liên kết tới bài viết cho bạn bè","Sao chép toàn bộ bài viết của người khác rồi đăng lại như của mình","Viết cảm nghĩ của mình về một cuốn sách"],"a":"Sao chép toàn bộ bài viết của người khác rồi đăng lại như của mình","h":"Vi phạm xảy ra khi 'nhận vơ' công sức của người khác.","e":"Tác phẩm của người khác được pháp luật bảo hộ; sao chép toàn bộ và nhận là của mình là vi phạm bản quyền.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi lấy một bức ảnh trên mạng để minh hoạ cho bài thuyết trình học tập của mình, em nên làm gì cho đúng?","o":["Xoá tên tác giả trên ảnh","Ghi rõ nguồn của bức ảnh","Nhận bức ảnh là do mình chụp","Bán lại bức ảnh cho bạn khác"],"a":"Ghi rõ nguồn của bức ảnh","h":"Hãy tôn trọng công sức của người chụp bức ảnh.","e":"Ghi nguồn rõ ràng là cách tôn trọng quyền tác giả khi sử dụng lại hình ảnh của người khác.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Một bạn đăng lại một tin sai sự thật lên mạng xã hội khiến nhiều người hoang mang. Phát biểu nào sau đây là đúng?","o":["Chỉ người tạo ra tin giả mới phải chịu trách nhiệm","Người chia sẻ thông tin sai sự thật cũng có thể bị xử lí theo quy định của pháp luật","Chia sẻ lại tin của người khác thì hoàn toàn không sao","Mọi thông tin trên mạng đều đáng tin cậy"],"a":"Người chia sẻ thông tin sai sự thật cũng có thể bị xử lí theo quy định của pháp luật","h":"Trước khi chia sẻ bất cứ tin gì, mỗi người đều phải kiểm chứng.","e":"Pháp luật quy định cả người đưa tin và người lan truyền thông tin sai sự thật đều có thể bị xử phạt.","t":"tin-cap3","l":"thu-thach"},{"p":"Hành vi nào sau đây xâm phạm quyền riêng tư của người khác?","o":["Đăng ảnh chụp của chính mình lên trang cá nhân","Tự ý đăng số điện thoại và ảnh cá nhân của bạn lên mạng khi chưa được đồng ý","Nhắn tin riêng hỏi thăm bạn","Xem các bài viết công khai trên mạng"],"a":"Tự ý đăng số điện thoại và ảnh cá nhân của bạn lên mạng khi chưa được đồng ý","h":"Thông tin cá nhân của ai thì người đó có quyền quyết định.","e":"Số điện thoại và hình ảnh cá nhân là thông tin riêng tư; tự ý công khai khi chưa được đồng ý là xâm phạm quyền riêng tư.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong Python, kiểu dữ liệu float dùng để biểu diễn loại số nào?","o":["Số nguyên như 1, 2, 3","Số thực có phần thập phân như 3.5","Chuỗi kí tự như 'Xin chào'","Giá trị đúng (True) hoặc sai (False)"],"a":"Số thực có phần thập phân như 3.5","h":"float nghĩa là số có phần thập phân.","e":"float là kiểu số thực, dùng cho các giá trị có phần thập phân như điểm trung bình 7.5.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong Python, dữ liệu mà lệnh input() nhận vào luôn thuộc kiểu dữ liệu nào?","o":["Số nguyên (int)","Số thực (float)","Chuỗi (str)","Danh sách (list)"],"a":"Chuỗi (str)","h":"Dù em gõ số, máy vẫn coi dữ liệu nhập vào là...","e":"input() luôn trả về một chuỗi; muốn tính toán số học cần chuyển đổi bằng int() hoặc float().","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong Python, biểu thức 'Lớp' + '10' cho kết quả nào?","o":["Lớp10","Lớp 10","10Lớp","Chương trình báo lỗi"],"a":"Lớp10","h":"Dấu + nối hai chuỗi liền nhau, không tự thêm dấu cách.","e":"Phép + nối chuỗi 'Lớp' và '10' liền nhau thành 'Lớp10'.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Từ khoá elif trong Python được dùng để làm gì?","o":["Kết thúc chương trình ngay lập tức","Kiểm tra thêm một điều kiện khác khi điều kiện trước đó không đúng","Lặp lại một khối lệnh nhiều lần","Khai báo một biến mới"],"a":"Kiểm tra thêm một điều kiện khác khi điều kiện trước đó không đúng","h":"elif là viết gọn của 'else if' (ngược lại nếu).","e":"elif cho phép xét thêm một trường hợp mới trong cấu trúc rẽ nhánh khi điều kiện của if không đúng.","t":"tin-cap3","l":"thu-thach"},{"p":"Cho chuỗi s = 'Hello'. Kí tự s[0] là kí tự nào?","o":["H","e","o","Chuỗi không có chỉ số 0"],"a":"H","h":"Chỉ số kí tự trong chuỗi bắt đầu từ 0.","e":"Kí tự đầu tiên của chuỗi có chỉ số 0, với 'Hello' thì s[0] = 'H'.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong Python, 17 // 5 và 17 % 5 cho kết quả lần lượt là gì?","o":["3 và 2","2 và 3","3.4 và 0","4 và 1"],"a":"3 và 2","h":"17 chia cho 5 được mấy, dư mấy?","e":"17 = 5 × 3 + 2 nên phép chia lấy phần nguyên cho 3 và phép chia lấy phần dư cho 2.","t":"tin-cap3","l":"kho"},{"p":"Cho đoạn chương trình: n = 0; while n < 5: n = n + 2; print(n). Kết quả in ra là bao nhiêu?","o":["4","5","6","Lặp vô hạn không dừng"],"a":"6","h":"Lần lượt thay n = 0, 2, 4... và kiểm tra điều kiện n < 5.","e":"n tăng dần 0 → 2 → 4 → 6; khi n = 6, điều kiện n < 5 sai nên vòng lặp dừng và in ra 6.","t":"tin-cap3","l":"kho"},{"p":"Cho đoạn chương trình: s = 'Viet' + 'Nam'; print(len(s)). Kết quả in ra là bao nhiêu?","o":["6","7","8","Chương trình báo lỗi"],"a":"7","h":"Nối chuỗi trước, rồi đếm số kí tự của chuỗi thu được.","e":"s = 'VietNam' gồm 7 kí tự nên len(s) = 7.","t":"tin-cap3","l":"kho"},{"p":"Điểm ảnh (pixel) là gì?","o":["Một loại máy ảnh kĩ thuật số","Phần tử nhỏ nhất tạo nên một hình ảnh số","Một phần mềm chỉnh sửa ảnh","Đơn vị đo dung lượng của tệp ảnh"],"a":"Phần tử nhỏ nhất tạo nên một hình ảnh số","h":"Phóng to ảnh thật lớn, em sẽ thấy những ô vuông nhỏ.","e":"Mỗi bức ảnh số được ghép từ rất nhiều điểm ảnh; mỗi điểm ảnh mang một màu nhất định.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Hệ màu RGB được tạo thành từ ba màu cơ bản nào?","o":["Đỏ, vàng, xanh dương","Đỏ, xanh lá, xanh dương","Cam, tím, hồng","Đen, trắng, xám"],"a":"Đỏ, xanh lá, xanh dương","h":"RGB là viết tắt tiếng Anh của ba màu đó.","e":"RGB gồm Red (đỏ), Green (xanh lá) và Blue (xanh dương); phối trộn ba màu này tạo ra các màu hiển thị trên màn hình.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Độ phân giải của một bức ảnh cho biết điều gì?","o":["Dung lượng của tệp ảnh tính bằng MB","Số lượng điểm ảnh cấu tạo nên bức ảnh","Độ sáng tối của bức ảnh","Kích thước giấy khi in ảnh"],"a":"Số lượng điểm ảnh cấu tạo nên bức ảnh","h":"Độ phân giải thường được ghi ở dạng như 1920 × 1080.","e":"Độ phân giải cho biết số điểm ảnh theo chiều ngang và chiều dọc; càng nhiều điểm ảnh, ảnh càng chi tiết.","t":"tin-cap3","l":"thu-thach"},{"p":"Một bức ảnh có độ phân giải 1920 × 1080 có nghĩa là gì?","o":["Ảnh có dung lượng 1920 MB","Ảnh gồm 1920 điểm ảnh theo chiều ngang và 1080 điểm ảnh theo chiều dọc","Ảnh được chụp vào năm 1920","Ảnh chỉ xem được trên màn hình 1080 inch"],"a":"Ảnh gồm 1920 điểm ảnh theo chiều ngang và 1080 điểm ảnh theo chiều dọc","h":"Hai con số ứng với hai chiều của bức ảnh.","e":"1920 × 1080 nghĩa là bề ngang của ảnh có 1920 điểm ảnh và bề dọc có 1080 điểm ảnh.","t":"tin-cap3","l":"thu-thach"},{"p":"Muốn in một bức ảnh ở khổ lớn mà hình vẫn sắc nét, em nên chọn ảnh có đặc điểm nào?","o":["Độ phân giải cao, nhiều điểm ảnh","Dung lượng tệp càng nhỏ càng tốt","Ảnh có càng ít màu càng tốt","Ảnh chụp bằng điện thoại đời cũ"],"a":"Độ phân giải cao, nhiều điểm ảnh","h":"In càng lớn thì càng cần nhiều điểm ảnh.","e":"Ảnh độ phân giải cao chứa nhiều điểm ảnh nên khi in khổ lớn vẫn giữ được chi tiết, không bị mờ vỡ.","t":"tin-cap3","l":"thu-thach"},{"p":"Khi phóng to quá mức một bức ảnh có độ phân giải thấp, hiện tượng nào thường xảy ra?","o":["Ảnh tự động trở nên sắc nét hơn","Ảnh bị vỡ hạt, thấy rõ các ô vuông điểm ảnh và mất chi tiết","Ảnh tự chuyển thành ảnh đen trắng","Màu sắc của ảnh trở nên tươi hơn"],"a":"Ảnh bị vỡ hạt, thấy rõ các ô vuông điểm ảnh và mất chi tiết","h":"Số điểm ảnh không đổi nhưng mỗi điểm ảnh bị kéo to ra.","e":"Ảnh ít điểm ảnh khi bị phóng to sẽ lộ từng ô điểm ảnh, hình ảnh bị vỡ hạt và mờ chi tiết.","t":"tin-cap3","l":"kho"},{"p":"Trong cơ sở dữ liệu quan hệ, khoá ngoại của một bảng dùng để làm gì?","o":["Liên kết bảng đó với một bảng khác thông qua khoá chính của bảng kia","Mã hoá toàn bộ dữ liệu trong bảng","Sắp xếp các bản ghi theo thứ tự bảng chữ cái","Tự động xoá các bản ghi bị trùng lặp"],"a":"Liên kết bảng đó với một bảng khác thông qua khoá chính của bảng kia","h":"Nhờ nó mà hai bảng biết được bản ghi nào thuộc về nhau.","e":"Khoá ngoại là trường trong một bảng chứa giá trị khoá chính của bảng khác, dùng để thiết lập mối liên kết giữa hai bảng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong CSDL trường học, bảng HOCSINH có trường MaLop lưu mã của các lớp có trong bảng LOP. Trường MaLop trong bảng HOCSINH là:","o":["Khoá chính","Khoá ngoại","Trường ghi chú","Trường tính toán"],"a":"Khoá ngoại","h":"Nó trỏ sang khoá chính của một bảng khác.","e":"MaLop trong bảng HOCSINH chứa giá trị khoá chính của bảng LOP nên nó là khoá ngoại, giúp biết mỗi học sinh thuộc lớp nào.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Khi thiết kế CSDL trường học, vì sao người ta tách thông tin lớp học thành một bảng LOP riêng thay vì ghi đầy đủ tên lớp trong từng bản ghi học sinh?","o":["Để bảng học sinh trông ngắn hơn khi in ra","Để tránh trùng lặp dữ liệu; khi tên lớp thay đổi chỉ cần sửa ở một nơi duy nhất","Để học sinh không biết mình học lớp nào","Để bắt buộc phải dùng hai máy tính khác nhau"],"a":"Để tránh trùng lặp dữ liệu; khi tên lớp thay đổi chỉ cần sửa ở một nơi duy nhất","h":"Hãy nghĩ xem điều gì xảy ra khi một thông tin phải sửa ở hàng trăm chỗ.","e":"Tách bảng giúp mỗi thông tin chỉ lưu một lần, tránh trùng lặp và mâu thuẫn khi cập nhật.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong CSDL trường học, một lớp có nhiều học sinh, mỗi học sinh chỉ thuộc một lớp. Quan hệ giữa bảng LOP và bảng HOCSINH là quan hệ nào?","o":["Một – một","Một – nhiều","Nhiều – nhiều","Không có quan hệ"],"a":"Một – nhiều","h":"Một ở phía lớp, nhiều ở phía học sinh.","e":"Một bản ghi của bảng LOP liên kết với nhiều bản ghi của bảng HOCSINH nên đây là quan hệ một – nhiều.","t":"tin-cap3","l":"thu-thach"},{"p":"Người quản trị xoá một lớp trong bảng LOP trong khi bảng HOCSINH vẫn còn nhiều học sinh mang mã lớp đó. Hệ quả đúng nhất là:","o":["Không có vấn đề gì vì hai bảng độc lập hoàn toàn","Dữ liệu trở nên không nhất quán vì các học sinh đó tham chiếu tới một lớp không còn tồn tại","Các học sinh đó tự động bị xoá theo","Bảng HOCSINH tự tạo lại lớp vừa xoá"],"a":"Dữ liệu trở nên không nhất quán vì các học sinh đó tham chiếu tới một lớp không còn tồn tại","h":"Khoá ngoại vẫn còn đó nhưng đầu mối liên kết đã mất.","e":"Đây là vi phạm toàn vẹn tham chiếu: khoá ngoại trỏ tới một bản ghi không còn tồn tại khiến dữ liệu mất nhất quán.","t":"tin-cap3","l":"kho"},{"p":"Trong bảng ĐIỂM, trường điểm trung bình môn nên dùng kiểu dữ liệu nào?","o":["Văn bản","Số","Ngày tháng","Hình ảnh"],"a":"Số","h":"Điểm cần được cộng và chia trung bình.","e":"Điểm là giá trị cần tính toán (cộng, tính trung bình, xếp loại) nên phải lưu bằng kiểu số.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trường họ và tên học sinh trong bảng HOCSINH nên dùng kiểu dữ liệu nào?","o":["Số nguyên","Ngày tháng","Văn bản","Âm thanh"],"a":"Văn bản","h":"Họ tên được viết bằng các kí tự chữ.","e":"Họ và tên là dãy kí tự chữ nên dùng kiểu văn bản (text).","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trường ngày sinh của học sinh nên dùng kiểu dữ liệu nào?","o":["Ngày tháng","Số thập phân","Văn bản dài","Hình ảnh"],"a":"Ngày tháng","h":"Kiểu này giúp tính được tuổi của học sinh.","e":"Kiểu ngày tháng giúp lưu đúng ngày sinh, tính được tuổi và sắp xếp theo thời gian.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Nếu lưu điểm số dưới dạng văn bản, khó khăn nào dễ gặp phải khi xử lí dữ liệu?","o":["Không thể in bảng điểm ra giấy","Không tính toán trực tiếp được và sắp xếp theo văn bản có thể cho thứ tự sai, ví dụ '10' đứng trước '9'","Điểm sẽ tự động bị nhân đôi","Máy tính không hiển thị được con số"],"a":"Không tính toán trực tiếp được và sắp xếp theo văn bản có thể cho thứ tự sai, ví dụ '10' đứng trước '9'","h":"Máy tính coi chúng là chuỗi kí tự chứ không phải con số.","e":"Dữ liệu kiểu văn bản không tham gia tính toán số học và được sắp xếp theo từng kí tự nên thứ tự có thể sai so với giá trị số.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong câu lệnh SQL, mệnh đề ORDER BY dùng để làm gì?","o":["Lọc ra các bản ghi thỏa điều kiện","Sắp xếp kết quả truy vấn theo một hoặc nhiều trường","Thêm bản ghi mới vào bảng","Đổi tên của bảng dữ liệu"],"a":"Sắp xếp kết quả truy vấn theo một hoặc nhiều trường","h":"Tên mệnh đề gợi ý tới việc thứ tự của kết quả.","e":"ORDER BY sắp xếp các dòng kết quả truy vấn, mặc định tăng dần hoặc giảm dần khi có DESC.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Câu truy vấn có đoạn ... ORDER BY Diem DESC sẽ cho kết quả thế nào?","o":["Học sinh có điểm thấp nhất xếp trước","Học sinh có điểm cao nhất xếp trước","Chỉ lấy học sinh có tên là DESC","Xoá các học sinh điểm thấp"],"a":"Học sinh có điểm cao nhất xếp trước","h":"DESC nghĩa là giảm dần.","e":"DESC sắp xếp giảm dần nên điểm cao nhất đứng đầu danh sách kết quả.","t":"tin-cap3","l":"thu-thach"},{"p":"Điều kiện WHERE Diem >= 5 AND GioiTinh = 'Nữ' sẽ chọn những học sinh nào?","o":["Mọi học sinh có điểm từ 5 trở lên, không phân biệt giới tính","Mọi học sinh nữ, không phân biệt điểm","Học sinh nữ có điểm từ 5 trở lên (thỏa đồng thời cả hai điều kiện)","Học sinh thỏa ít nhất một trong hai điều kiện"],"a":"Học sinh nữ có điểm từ 5 trở lên (thỏa đồng thời cả hai điều kiện)","h":"Chú ý vai trò của từ AND giữa hai điều kiện.","e":"Toán tử AND yêu cầu cả hai điều kiện cùng đúng thì bản ghi mới được chọn.","t":"tin-cap3","l":"thu-thach"},{"p":"Điều kiện WHERE Lop = '11A1' OR Lop = '11A2' sẽ chọn những học sinh nào?","o":["Chỉ học sinh học đồng thời cả hai lớp","Học sinh thuộc lớp 11A1 hoặc lớp 11A2","Học sinh không thuộc hai lớp trên","Toàn bộ học sinh trong trường"],"a":"Học sinh thuộc lớp 11A1 hoặc lớp 11A2","h":"Chú ý vai trò của từ OR giữa hai điều kiện.","e":"Toán tử OR chỉ cần một trong hai điều kiện đúng là bản ghi được chọn.","t":"tin-cap3","l":"thu-thach"},{"p":"Cho truy vấn: SELECT HoTen FROM HOCSINH WHERE GioiTinh = 'Nữ' AND Diem >= 9 ORDER BY Diem DESC. Kết quả của truy vấn là:","o":["Họ tên mọi học sinh nữ, xếp theo bảng chữ cái","Họ tên các học sinh nữ có điểm từ 9 trở lên, điểm cao nhất xếp trước","Họ tên các học sinh nam có điểm từ 9 trở lên","Điểm trung bình của học sinh nữ toàn trường"],"a":"Họ tên các học sinh nữ có điểm từ 9 trở lên, điểm cao nhất xếp trước","h":"Đọc lần lượt từng phần: chọn trường nào, điều kiện lọc ra sao, sắp xếp thế nào.","e":"Mệnh đề WHERE lọc học sinh nữ có điểm từ 9 trở lên, ORDER BY Diem DESC sắp xếp điểm giảm dần.","t":"tin-cap3","l":"kho"},{"p":"Muốn in danh sách gồm họ tên học sinh kèm theo tên lớp của từng em, trong khi họ tên nằm ở bảng HOCSINH còn tên lớp nằm ở bảng LOP, truy vấn cần làm gì?","o":["Chỉ truy vấn bảng HOCSINH là đủ","Kết hợp dữ liệu của hai bảng dựa trên trường liên kết MaLop","Sao chép tên lớp sang mọi bảng khác","Xoá bảng LOP rồi gõ tay tên lớp vào danh sách"],"a":"Kết hợp dữ liệu của hai bảng dựa trên trường liên kết MaLop","h":"Hai bảng được nối với nhau nhờ trường chung nào?","e":"Truy vấn phải kết nối hai bảng theo khoá ngoại MaLop để lấy đồng thời thông tin từ cả hai bảng.","t":"tin-cap3","l":"kho"},{"p":"Để đưa thêm một học sinh mới vào bảng HOCSINH, ta cần thực hiện thao tác nào?","o":["Thêm một trường mới","Thêm một bản ghi mới","Thêm một bảng mới","Đổi khoá chính của bảng"],"a":"Thêm một bản ghi mới","h":"Mỗi học sinh chiếm một hàng trong bảng.","e":"Mỗi học sinh là một bản ghi (một hàng) trong bảng nên thêm học sinh tức là thêm bản ghi mới.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong phần mềm quản trị CSDL, biểu mẫu (form) thường được dùng để làm gì?","o":["Nhập và hiển thị dữ liệu theo từng bản ghi một cách thuận tiện","Nén dữ liệu để tiết kiệm bộ nhớ","Vẽ biểu đồ thống kê","Sao lưu dữ liệu ra ổ cứng ngoài"],"a":"Nhập và hiển thị dữ liệu theo từng bản ghi một cách thuận tiện","h":"Biểu mẫu giống như một tờ phiếu điền thông tin.","e":"Biểu mẫu trình bày mỗi bản ghi trong một khung nhập liệu rõ ràng, giúp nhập và xem dữ liệu dễ hơn làm việc trực tiếp với bảng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Một học sinh chuyển từ lớp 11A1 sang 11A2, người quản trị cần sửa giá trị MaLop trong bản ghi của học sinh đó. Đây là thao tác nào?","o":["Thêm bản ghi","Xoá bản ghi","Cập nhật (sửa) bản ghi","Tạo bảng mới"],"a":"Cập nhật (sửa) bản ghi","h":"Bản ghi vẫn còn đó, chỉ một giá trị trong đó thay đổi.","e":"Thay đổi giá trị đã có trong một bản ghi được gọi là cập nhật dữ liệu.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Một học sinh đã chuyển trường và không còn học tại trường nữa. Để danh sách lớp được đúng, thao tác phù hợp với bản ghi của học sinh đó là:","o":["Giữ nguyên và thêm một bản ghi giống hệt","Xoá bản ghi của học sinh đó khỏi bảng (theo quy định lưu trữ của trường)","Đổi họ tên học sinh thành khoảng trắng","Thêm một trường mới dành riêng cho học sinh đó"],"a":"Xoá bản ghi của học sinh đó khỏi bảng (theo quy định lưu trữ của trường)","h":"CSDL phải phản ánh đúng tình hình thực tế hiện tại.","e":"Bản ghi không còn đúng với thực tế cần được xoá hoặc xử lí theo quy định để CSDL phản ánh đúng hiện trạng.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong Python, lệnh return trong một hàm dùng để làm gì?","o":["In giá trị ra màn hình","Trả một giá trị từ hàm về cho nơi gọi hàm","Khai báo một biến toàn cục","Dừng toàn bộ chương trình ngay lập tức"],"a":"Trả một giá trị từ hàm về cho nơi gọi hàm","h":"Nhờ nó mà ta có thể viết y = f(3) và dùng tiếp giá trị y.","e":"return kết thúc hàm và gửi giá trị kết quả về cho dòng lệnh đã gọi hàm.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Cho định nghĩa hàm: def tinh_tong(a, b): return a + b. Hai tên a và b được gọi là gì?","o":["Biến toàn cục","Tham số của hàm","Từ khoá của Python","Kết quả của hàm"],"a":"Tham số của hàm","h":"Chúng nhận giá trị truyền vào mỗi khi hàm được gọi.","e":"a và b là các tham số của hàm, nhận giá trị truyền vào khi hàm được gọi.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Cho s = 'abc'. Biểu thức s.upper() cho kết quả nào?","o":["'abc'","'ABC'","'Abc'","'aBc'"],"a":"'ABC'","h":"upper() tác động lên mọi kí tự chữ trong chuỗi.","e":"Phương thức upper() chuyển toàn bộ kí tự trong chuỗi thành chữ in hoa.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Cho s = 'Tin Hoc'. Biểu thức s.lower() cho kết quả nào?","o":["'TIN HOC'","'Tin Hoc'","'tin hoc'","'tIN hOC'"],"a":"'tin hoc'","h":"lower() là phương thức ngược lại với upper().","e":"Phương thức lower() chuyển toàn bộ kí tự trong chuỗi thành chữ thường.","t":"tin-cap3","l":"thu-thach"},{"p":"Cho danh sách a = [10, 20, 30, 40]. Giá trị của a[1] là bao nhiêu?","o":["10","20","30","40"],"a":"20","h":"Chỉ số trong Python bắt đầu từ 0.","e":"Phần tử đầu tiên có chỉ số 0 nên a[1] là phần tử thứ hai, tức 20.","t":"tin-cap3","l":"thu-thach"},{"p":"Cho đoạn chương trình: a = [1, 2, 3]; tong = 0; for x in a: tong = tong + x; print(tong). Kết quả in ra là:","o":["3","5","6","123"],"a":"6","h":"Vòng lặp cộng lần lượt từng phần tử của danh sách.","e":"Vòng for duyệt từng phần tử 1, 2, 3 và cộng dồn vào biến tong nên kết quả in ra là 6.","t":"tin-cap3","l":"thu-thach"},{"p":"Một biến được tạo ra ở bên trong một hàm trong Python (biến cục bộ) có đặc điểm nào?","o":["Dùng được ở mọi nơi trong chương trình","Chỉ có tác dụng bên trong hàm đó; ra khỏi hàm thì không còn dùng được","Tự động được lưu xuống đĩa cứng","Luôn có giá trị bằng 0"],"a":"Chỉ có tác dụng bên trong hàm đó; ra khỏi hàm thì không còn dùng được","h":"Hãy nghĩ tới phạm vi hoạt động của biến.","e":"Biến cục bộ chỉ tồn tại trong phạm vi hàm nơi nó được tạo ra.","t":"tin-cap3","l":"kho"},{"p":"Trong hệ thống quản lí điểm của trường, học sinh chỉ được xem điểm của mình mà không thể sửa điểm. Điều này là nhờ cơ chế nào?","o":["Sao lưu dữ liệu","Phân quyền người dùng","Nén dữ liệu","Tự động sắp xếp"],"a":"Phân quyền người dùng","h":"Mỗi đối tượng sử dụng chỉ được làm những việc nhất định.","e":"Hệ thống cấp quyền khác nhau cho từng đối tượng: học sinh chỉ có quyền xem, giáo viên mới có quyền nhập và sửa điểm.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Người chuyên phụ trách cài đặt, quản lí, bảo trì và bảo mật cơ sở dữ liệu của một cơ quan được gọi là:","o":["Quản trị viên cơ sở dữ liệu","Nhân viên nhập liệu","Thiết kế đồ hoạ","Kế toán trưởng"],"a":"Quản trị viên cơ sở dữ liệu","h":"Tên gọi tắt tiếng Anh của nghề này là DBA.","e":"Quản trị viên CSDL (DBA) chịu trách nhiệm vận hành, phân quyền, sao lưu và bảo mật cơ sở dữ liệu.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Việc sao lưu cơ sở dữ liệu định kì mang lại lợi ích gì quan trọng nhất?","o":["Làm máy tính chạy nhanh hơn","Khôi phục lại được dữ liệu khi xảy ra sự cố như hỏng máy, xoá nhầm hay nhiễm mã độc","Giúp thêm được nhiều người dùng cùng lúc","Tự động sửa lỗi chính tả trong dữ liệu"],"a":"Khôi phục lại được dữ liệu khi xảy ra sự cố như hỏng máy, xoá nhầm hay nhiễm mã độc","h":"Bản sao lưu phát huy tác dụng khi bản chính gặp chuyện.","e":"Bản sao lưu là nguồn để khôi phục dữ liệu khi bản chính bị mất hoặc hư hỏng do sự cố.","t":"tin-cap3","l":"thu-thach"},{"p":"Khi cấp quyền truy cập CSDL cho nhân viên, cách làm an toàn nhất là:","o":["Cấp toàn quyền cho mọi người để tiện làm việc","Chỉ cấp đúng những quyền cần thiết cho công việc của từng người","Cho mọi người dùng chung một tài khoản quản trị","Không đặt mật khẩu để đăng nhập nhanh hơn"],"a":"Chỉ cấp đúng những quyền cần thiết cho công việc của từng người","h":"Cách làm này được gọi là nguyên tắc quyền tối thiểu.","e":"Nguyên tắc quyền tối thiểu giúp hạn chế thiệt hại và rò rỉ dữ liệu khi một tài khoản bị lạm dụng hoặc bị đánh cắp.","t":"tin-cap3","l":"kho"},{"p":"Học sâu (deep learning) trong trí tuệ nhân tạo được hiểu là:","o":["Việc dạy máy tính bằng cách viết sẵn mọi quy tắc xử lí","Phương pháp học máy dùng mạng nơ-ron nhân tạo gồm nhiều lớp để tự rút ra đặc trưng từ dữ liệu lớn","Kĩ thuật sao lưu dữ liệu theo nhiều lớp","Chương trình dịch ngôn ngữ tự nhiên đầu tiên trên thế giới"],"a":"Phương pháp học máy dùng mạng nơ-ron nhân tạo gồm nhiều lớp để tự rút ra đặc trưng từ dữ liệu lớn","h":"Chữ 'sâu' gắn với số lớp của mạng nơ-ron.","e":"Học sâu là một nhánh của học máy, dùng mạng nơ-ron nhiều lớp và dữ liệu lớn để mô hình tự học các đặc trưng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"AI tạo sinh (AI sinh nội dung) có khả năng nổi bật nào?","o":["Tạo ra nội dung mới như văn bản, hình ảnh, âm thanh dựa trên dữ liệu đã học","Tự sửa chữa phần cứng máy tính khi hỏng","Thay thế hoàn toàn hệ điều hành","Tăng dung lượng bộ nhớ của máy tính"],"a":"Tạo ra nội dung mới như văn bản, hình ảnh, âm thanh dựa trên dữ liệu đã học","h":"Các chatbot viết văn và công cụ vẽ tranh theo mô tả thuộc nhóm này.","e":"AI tạo sinh học từ dữ liệu có sẵn rồi sinh ra nội dung mới tương tự, như viết đoạn văn hay vẽ tranh theo yêu cầu.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Deepfake là gì?","o":["Một loại vi rút máy tính nguy hiểm","Hình ảnh, video hoặc giọng nói giả mạo do AI tạo ra, ghép mặt hoặc giọng của người này vào người khác","Phần mềm tăng độ nét cho ảnh cũ","Mạng xã hội dành riêng cho lập trình viên"],"a":"Hình ảnh, video hoặc giọng nói giả mạo do AI tạo ra, ghép mặt hoặc giọng của người này vào người khác","h":"Tên gọi này gắn với các video giả mặt người nổi tiếng.","e":"Deepfake dùng AI để tạo nội dung giả rất giống thật, thường nhằm lừa đảo hoặc bôi nhọ nên cần cảnh giác.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Vì sao AI tạo sinh có thể làm tin giả lan truyền nhanh hơn trước?","o":["Vì AI chỉ tạo tin giả vào ban đêm","Vì nó tạo được bài viết, ảnh, video giả rất giống thật trong thời gian ngắn, khiến người xem khó phân biệt","Vì mạng xã hội bắt buộc phải đăng tin do AI viết","Vì tin giả luôn nhận được nhiều lượt thích hơn tin thật"],"a":"Vì nó tạo được bài viết, ảnh, video giả rất giống thật trong thời gian ngắn, khiến người xem khó phân biệt","h":"Hãy nghĩ tới tốc độ và độ giống thật của nội dung do AI tạo ra.","e":"Chi phí tạo nội dung giả gần như bằng không và độ giống thật cao khiến tin giả được sản xuất hàng loạt và khó nhận ra.","t":"tin-cap3","l":"thu-thach"},{"p":"Một hệ thống AI tuyển dụng được huấn luyện chủ yếu bằng hồ sơ của một nhóm ứng viên nhất định. Nguy cơ lớn nhất là gì?","o":["Hệ thống chạy chậm hơn bình thường","Kết quả đánh giá bị thiên lệch, thiếu công bằng với các nhóm ứng viên ít xuất hiện trong dữ liệu huấn luyện","Hồ sơ ứng viên bị in thừa ra hai bản","Hệ thống tự quên mật khẩu quản trị"],"a":"Kết quả đánh giá bị thiên lệch, thiếu công bằng với các nhóm ứng viên ít xuất hiện trong dữ liệu huấn luyện","h":"Dữ liệu đầu vào thế nào thì kết quả đầu ra có xu hướng thế ấy.","e":"Dữ liệu huấn luyện thiên lệch khiến mô hình học theo sự thiên lệch đó và cho kết quả không công bằng.","t":"tin-cap3","l":"thu-thach"},{"p":"Bạn hỏi một chatbot AI về một cuốn sách, AI mô tả rất chi tiết dù cuốn sách đó không hề tồn tại. Hiện tượng này cho thấy điều gì?","o":["AI không bao giờ mắc lỗi","AI tạo sinh có thể bịa ra thông tin nghe rất thuyết phục, nên cần kiểm chứng bằng nguồn đáng tin cậy","Cuốn sách chắc chắn tồn tại nhưng rất ít người biết","Chatbot đang cố tình đùa với người dùng"],"a":"AI tạo sinh có thể bịa ra thông tin nghe rất thuyết phục, nên cần kiểm chứng bằng nguồn đáng tin cậy","h":"AI tạo câu trả lời nghe hợp lí chứ không tra cứu sự thật.","e":"AI tạo sinh dự đoán nội dung hợp lí theo mẫu ngôn ngữ chứ không tự kiểm chứng sự thật, nên có thể đưa ra thông tin sai mà vẫn rất tự tin.","t":"tin-cap3","l":"thu-thach"},{"p":"Một mô hình AI được huấn luyện bằng dữ liệu thu thập tràn lan trên Internet mà không qua kiểm chứng. Nguy cơ đúng nhất là:","o":["Mô hình sẽ luôn khách quan và chính xác tuyệt đối","Mô hình học cả thông tin sai và định kiến trong dữ liệu, rồi tái tạo lại chúng trong các câu trả lời","Mô hình tự động xoá hết dữ liệu xấu","Mô hình chỉ trả lời được bằng tiếng Anh"],"a":"Mô hình học cả thông tin sai và định kiến trong dữ liệu, rồi tái tạo lại chúng trong các câu trả lời","h":"Chất lượng đầu ra phụ thuộc trực tiếp vào chất lượng đầu vào.","e":"Dữ liệu huấn luyện chưa kiểm chứng khiến AI học và lặp lại cả những thông tin sai và định kiến có trong dữ liệu.","t":"tin-cap3","l":"kho"},{"p":"Tường lửa (firewall) trong hệ thống mạng có vai trò chính là gì?","o":["Tăng tốc độ đường truyền Internet","Kiểm soát dữ liệu ra vào mạng và ngăn chặn các kết nối trái phép","Lưu trữ bản sao của mọi tệp tin","Diệt mọi loại vi rút trên máy tính"],"a":"Kiểm soát dữ liệu ra vào mạng và ngăn chặn các kết nối trái phép","h":"Hãy hình dung tường lửa như một chốt kiểm soát ở cổng ra vào.","e":"Tường lửa chỉ cho phép các kết nối hợp lệ đi qua và chặn các truy cập trái phép vào hệ thống mạng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Cập nhật hệ điều hành và phần mềm thường xuyên giúp bảo vệ máy tính chủ yếu vì:","o":["Bản cập nhật làm giao diện đẹp hơn","Bản cập nhật vá các lỗ hổng bảo mật đã được phát hiện","Bản cập nhật xoá bớt tệp rác trong máy","Bản cập nhật giúp tăng thời lượng pin"],"a":"Bản cập nhật vá các lỗ hổng bảo mật đã được phát hiện","h":"Tin tặc thường nhắm vào những điểm yếu đã bị công bố.","e":"Tin tặc thường khai thác các lỗ hổng đã biết; cập nhật kịp thời là cách vá những lỗ hổng đó.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Mã độc tống tiền (ransomware) gây hại bằng cách nào?","o":["Làm màn hình nhấp nháy liên tục","Mã hoá dữ liệu của nạn nhân và đòi tiền chuộc để mở khoá","Tự động gửi thư rác quảng cáo","Chiếm quyền điều khiển chuột máy tính"],"a":"Mã hoá dữ liệu của nạn nhân và đòi tiền chuộc để mở khoá","h":"Tên gọi của nó gắn với hai chữ: mã độc và tiền chuộc.","e":"Ransomware mã hoá tệp tin khiến nạn nhân không dùng được dữ liệu và đòi tiền chuộc để cung cấp khoá giải mã.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Máy tính của một cơ quan bị ransomware mã hoá toàn bộ dữ liệu, nhưng cơ quan có bản sao lưu độc lập được cập nhật thường xuyên. Lợi ích lớn nhất của bản sao lưu lúc này là:","o":["Giúp bắt được kẻ tấn công ngay lập tức","Khôi phục lại dữ liệu để tiếp tục công việc mà không phải trả tiền chuộc","Tự động giải mã mọi tệp đã bị mã hoá","Ngăn ransomware lây ngược về thời điểm trước khi bị tấn công"],"a":"Khôi phục lại dữ liệu để tiếp tục công việc mà không phải trả tiền chuộc","h":"Bản sao lưu sạch và tách biệt là lối thoát khi dữ liệu chính đã bị khoá.","e":"Bản sao lưu sạch, tách biệt cho phép khôi phục dữ liệu sau sự cố mà không phụ thuộc vào kẻ tấn công.","t":"tin-cap3","l":"thu-thach"},{"p":"Vì sao chuyên gia khuyến cáo không nên trì hoãn các bản cập nhật bảo mật của hệ điều hành?","o":["Vì bản cập nhật chỉ có hiệu lực trong vòng 24 giờ","Vì lỗ hổng chưa được vá là cửa ngõ mà tin tặc đang tích cực khai thác","Vì máy tính sẽ tự tắt nếu không cập nhật","Vì nhà sản xuất sẽ thu thêm phí nếu cập nhật muộn"],"a":"Vì lỗ hổng chưa được vá là cửa ngõ mà tin tặc đang tích cực khai thác","h":"Khoảng thời gian giữa lúc lỗ hổng bị công bố và lúc được vá là lúc nguy hiểm nhất.","e":"Khi lỗ hổng đã bị công bố mà chưa được vá, máy tính ở trạng thái dễ bị tấn công nhất.","t":"tin-cap3","l":"thu-thach"},{"p":"Một người sao lưu dữ liệu bằng cách chép sang một thư mục khác trên cùng ổ cứng của chính máy tính đó. Khi máy bị ransomware tấn công, điều gì dễ xảy ra?","o":["Bản sao lưu hoàn toàn an toàn vì nằm ở thư mục khác","Bản sao lưu cũng bị mã hoá theo vì nằm trên cùng hệ thống bị tấn công","Ransomware tự bỏ qua các thư mục có tên là sao lưu","Dữ liệu gốc tự khôi phục từ bản sao lưu"],"a":"Bản sao lưu cũng bị mã hoá theo vì nằm trên cùng hệ thống bị tấn công","h":"Sao lưu an toàn phải tách biệt khỏi hệ thống chính.","e":"Sao lưu trên cùng một máy không tách biệt nên mã độc vẫn tiếp cận và mã hoá được; cần sao lưu ra thiết bị ngoài hoặc đám mây tách biệt.","t":"tin-cap3","l":"kho"},{"p":"Dữ liệu lớn (Big Data) được hiểu là:","o":["Một tệp văn bản có dung lượng trên 1 GB","Các tập dữ liệu có khối lượng rất lớn, đa dạng và tăng nhanh, cần công nghệ riêng để lưu trữ và xử lí","Toàn bộ dữ liệu trong một máy tính cá nhân","Dữ liệu được in ra trên giấy khổ lớn"],"a":"Các tập dữ liệu có khối lượng rất lớn, đa dạng và tăng nhanh, cần công nghệ riêng để lưu trữ và xử lí","h":"Hãy nhớ ba đặc trưng: lớn, nhanh và đa dạng.","e":"Dữ liệu lớn có ba đặc trưng thường được nhắc tới: khối lượng rất lớn, tốc độ tạo ra nhanh và dạng dữ liệu đa dạng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Cơ sở dữ liệu trên nền điện toán đám mây có đặc điểm nổi bật nào?","o":["Chỉ truy cập được từ một máy tính duy nhất","Dữ liệu lưu trên hệ thống máy chủ qua Internet nên có thể truy cập từ nhiều nơi, nhiều thiết bị","Không cần kết nối mạng vẫn dùng được ở mọi nơi","Dữ liệu tự động xoá sau 30 ngày"],"a":"Dữ liệu lưu trên hệ thống máy chủ qua Internet nên có thể truy cập từ nhiều nơi, nhiều thiết bị","h":"Người dùng không phải tự vận hành máy chủ riêng.","e":"CSDL đám mây đặt dữ liệu trên máy chủ trực tuyến, người dùng truy cập qua Internet từ nhiều thiết bị khác nhau.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Khai thác dữ liệu (data mining) từ kho dữ liệu lớn của một siêu thị nhằm mục đích chính là gì?","o":["Xoá bớt dữ liệu bán hàng cũ cho nhẹ máy","Tìm ra các quy luật hữu ích, ví dụ nhóm hàng thường được mua cùng nhau, để phục vụ kinh doanh","In hoá đơn cho khách nhanh hơn","Đổi tên các mặt hàng trong kho"],"a":"Tìm ra các quy luật hữu ích, ví dụ nhóm hàng thường được mua cùng nhau, để phục vụ kinh doanh","h":"Giống như đãi cát tìm vàng trong kho dữ liệu.","e":"Khai thác dữ liệu là quá trình phân tích khối dữ liệu lớn để rút ra tri thức và quy luật phục vụ việc ra quyết định.","t":"tin-cap3","l":"thu-thach"},{"p":"Hệ thống đặt vé tàu trực tuyến dùng cơ sở dữ liệu chủ yếu để:","o":["Quản lí thông tin chuyến tàu, số ghế còn trống và vé đã bán, tránh bán trùng một ghế cho nhiều người","Trang trí giao diện trang web cho đẹp mắt","Phát nhạc cho hành khách nghe","Đo tốc độ chạy của đoàn tàu"],"a":"Quản lí thông tin chuyến tàu, số ghế còn trống và vé đã bán, tránh bán trùng một ghế cho nhiều người","h":"Hệ thống phải biết chính xác ghế nào còn, ghế nào đã bán.","e":"CSDL giúp hệ thống theo dõi chính xác tình trạng ghế và vé tại mọi thời điểm, tránh bán trùng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Vì sao các hệ thống lớn như đặt vé, ngân hàng dùng một cơ sở dữ liệu tập trung thay vì để mỗi chi nhánh lưu dữ liệu riêng?","o":["Để mỗi chi nhánh có một số liệu khác nhau cho phong phú","Để mọi nơi cùng thấy dữ liệu mới nhất và nhất quán, tránh mâu thuẫn thông tin","Để phải mua thêm nhiều máy chủ hơn","Để nhân viên tra cứu khó khăn hơn"],"a":"Để mọi nơi cùng thấy dữ liệu mới nhất và nhất quán, tránh mâu thuẫn thông tin","h":"Một thay đổi chỉ cần cập nhật ở một nơi duy nhất.","e":"Dữ liệu tập trung đảm bảo tính nhất quán: thông tin được cập nhật một nơi và mọi điểm truy cập đều thấy giống nhau.","t":"tin-cap3","l":"thu-thach"},{"p":"Trang web bán vé xem phim có hàng nghìn người cùng đặt vé trong một phút. Yêu cầu quan trọng nhất đối với cơ sở dữ liệu của hệ thống là:","o":["Giao diện quản trị phải có nhiều màu sắc","Xử lí được nhiều giao dịch đồng thời mà vẫn đảm bảo đúng dữ liệu, không bán trùng một ghế cho hai người","Chỉ cần lưu được dữ liệu, tốc độ không quan trọng","Tự động giảm giá vé khi đông người truy cập"],"a":"Xử lí được nhiều giao dịch đồng thời mà vẫn đảm bảo đúng dữ liệu, không bán trùng một ghế cho hai người","h":"Hãy nghĩ tới điều gì xảy ra nếu hai người cùng mua chiếc ghế cuối cùng.","e":"Hệ thống phải đảm bảo tính toàn vẹn dữ liệu khi nhiều giao dịch diễn ra đồng thời, tránh xung đột như bán trùng ghế.","t":"tin-cap3","l":"kho"},{"p":"Học sinh yêu thích lập trình và muốn làm nghề phát triển phần mềm sau khi tốt nghiệp THPT. Hướng đi phù hợp là:","o":["Học đại học hoặc cao đẳng các ngành công nghệ thông tin, kĩ thuật phần mềm, hoặc các khoá đào tạo nghề lập trình","Chỉ cần nghỉ học ở nhà chơi trò chơi điện tử","Học bất kì ngành nào cũng ra làm lập trình viên được ngay","Chờ đến 30 tuổi mới bắt đầu học lập trình"],"a":"Học đại học hoặc cao đẳng các ngành công nghệ thông tin, kĩ thuật phần mềm, hoặc các khoá đào tạo nghề lập trình","h":"Ngành tin học có nhiều đường vào: đại học, cao đẳng và đào tạo nghề.","e":"Sau THPT, học sinh có thể theo đại học, cao đẳng nghề hoặc các khoá đào tạo lập trình để vào nghề phát triển phần mềm.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Tiếng Anh quan trọng với người làm nghề tin học chủ yếu vì:","o":["Mọi máy tính đều chỉ có bàn phím tiếng Anh","Phần lớn tài liệu kĩ thuật, ngôn ngữ lập trình và cộng đồng công nghệ sử dụng tiếng Anh","Không biết tiếng Anh thì không bật được máy tính","Các công ty tin học chỉ tuyển người nước ngoài"],"a":"Phần lớn tài liệu kĩ thuật, ngôn ngữ lập trình và cộng đồng công nghệ sử dụng tiếng Anh","h":"Hãy nghĩ tới ngôn ngữ của tài liệu hướng dẫn và thông báo lỗi.","e":"Đọc tài liệu, thông báo lỗi, hướng dẫn và trao đổi với cộng đồng lập trình quốc tế đều cần tiếng Anh.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Kĩ năng tự học có vai trò đặc biệt quan trọng trong nghề tin học vì:","o":["Trường học không dạy gì về tin học cả","Công nghệ thay đổi rất nhanh, người làm nghề phải liên tục cập nhật kiến thức và công cụ mới","Người làm tin học không bao giờ được đi đào tạo lại","Tự học tốt thì không cần làm việc nhóm nữa"],"a":"Công nghệ thay đổi rất nhanh, người làm nghề phải liên tục cập nhật kiến thức và công cụ mới","h":"Công cụ hôm nay hiện đại, vài năm sau có thể đã lỗi thời.","e":"Công cụ và công nghệ mới xuất hiện liên tục nên khả năng tự học quyết định việc theo kịp nghề.","t":"tin-cap3","l":"thu-thach"},{"p":"Một kĩ thuật viên vô tình thao tác sai làm hệ thống của khách hàng ngừng hoạt động. Phẩm chất trung thực được thể hiện đúng nhất ở việc:","o":["Che giấu sự cố và hi vọng không ai phát hiện","Đổ lỗi cho phần mềm của hãng khác","Nhận lỗi, báo cáo đúng sự việc cho quản lí và khách hàng, đồng thời tìm cách khắc phục","Xoá nhật kí hệ thống để không còn bằng chứng"],"a":"Nhận lỗi, báo cáo đúng sự việc cho quản lí và khách hàng, đồng thời tìm cách khắc phục","h":"Trung thực bắt đầu từ việc dám nhận phần việc mình làm sai.","e":"Trung thực trong nghề là dám nhận trách nhiệm và thông tin minh bạch để sự cố được xử lí nhanh và đúng.","t":"tin-cap3","l":"thu-thach"},{"p":"Người quản trị hệ thống có thể truy cập dữ liệu cá nhân của nhiều người dùng. Hành vi nào sau đây vi phạm đạo đức nghề nghiệp?","o":["Sao lưu dữ liệu định kì theo kế hoạch","Tự ý mở xem và kể lại thông tin riêng tư của người dùng khi không phục vụ công việc","Đặt mật khẩu mạnh cho tài khoản quản trị","Ghi nhật kí các thao tác bảo trì hệ thống"],"a":"Tự ý mở xem và kể lại thông tin riêng tư của người dùng khi không phục vụ công việc","h":"Quyền truy cập cao đi kèm trách nhiệm bảo mật cao.","e":"Dùng quyền quản trị để xâm phạm thông tin riêng tư của người khác là vi phạm đạo đức nghề nghiệp.","t":"tin-cap3","l":"thu-thach"},{"p":"Một người bạn nhờ bạn — đang làm quản trị CSDL của trường — sửa tăng điểm cho bạn ấy trong hệ thống. Hành động đúng là:","o":["Giúp bạn vì chỉ thay đổi một con số nhỏ","Từ chối vì đó là gian lận, vi phạm đạo đức nghề nghiệp và quy định pháp luật","Sửa điểm nhưng ghi chú là do máy bị lỗi","Nhờ một người khác sửa thay để mình tránh bị phát hiện"],"a":"Từ chối vì đó là gian lận, vi phạm đạo đức nghề nghiệp và quy định pháp luật","h":"Tính toàn vẹn của dữ liệu là điều người làm nghề phải giữ.","e":"Sửa dữ liệu trái phép là hành vi gian lận; người làm nghề tin học phải từ chối và giữ tính toàn vẹn của dữ liệu.","t":"tin-cap3","l":"kho"},{"p":"Khi tham gia tranh luận trên mạng xã hội, cách ứng xử văn minh là:","o":["Dùng lời lẽ gay gắt để thắng bằng được","Trình bày ý kiến rõ ràng, tôn trọng người khác, không công kích cá nhân","Đăng thông tin đời tư của đối phương lên mạng","Tạo nhiều tài khoản ảo để ủng hộ ý kiến của mình"],"a":"Trình bày ý kiến rõ ràng, tôn trọng người khác, không công kích cá nhân","h":"Tranh luận là trao đổi về ý kiến, không phải xúc phạm con người.","e":"Tranh luận văn minh là trao đổi về nội dung, giữ thái độ tôn trọng và không công kích cá nhân.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Về mặt pháp lí, người chia sẻ thông tin sai sự thật lên mạng xã hội gây ảnh hưởng xấu có thể phải đối mặt với điều gì?","o":["Không có hậu quả gì vì mạng xã hội là thế giới ảo","Có thể bị xử phạt hành chính hoặc chịu trách nhiệm theo quy định của pháp luật","Chỉ bị trừ điểm thi đua ở trường","Được nhiều người theo dõi hơn"],"a":"Có thể bị xử phạt hành chính hoặc chịu trách nhiệm theo quy định của pháp luật","h":"Hành vi trên mạng vẫn chịu sự điều chỉnh của pháp luật thật.","e":"Pháp luật Việt Nam có quy định xử lí hành vi đăng tải, chia sẻ thông tin sai sự thật trên mạng, mức xử lí tuỳ theo hậu quả gây ra.","t":"tin-cap3","l":"thu-thach"},{"p":"Thấy một bài viết trên mạng đang xúc phạm, bêu riếu bạn của mình, việc làm đúng nhất là:","o":["Chia sẻ lại để nhiều người cùng biết","Nhảy vào bình luận xúc phạm lại người đăng bài","Không hùa theo, báo cáo bài viết với nhà quản trị nền tảng và động viên bạn mình","Chụp màn hình gửi đi nhiều nhóm khác nhau"],"a":"Không hùa theo, báo cáo bài viết với nhà quản trị nền tảng và động viên bạn mình","h":"Đừng tiếp tay lan truyền nội dung xấu, hãy dùng công cụ báo cáo.","e":"Không lan truyền nội dung xúc phạm, báo cáo với nền tảng và hỗ trợ người bị hại là cách ứng xử đúng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Bạn đã chia sẻ một thông tin lên mạng và sau đó phát hiện đó là tin giả. Việc làm có trách nhiệm nhất là:","o":["Để nguyên vì đằng nào cũng đã có nhiều người xem rồi","Xoá bài và đăng đính chính công khai để những người đã xem không tiếp tục hiểu sai","Chia sẻ thêm một tin khác để lấn át tin cũ","Đổi tên tài khoản để tránh bị nhận ra"],"a":"Xoá bài và đăng đính chính công khai để những người đã xem không tiếp tục hiểu sai","h":"Sửa sai công khai giúp ngăn thông tin giả lan thêm.","e":"Đính chính công khai giúp ngăn thông tin sai tiếp tục lan truyền và thể hiện trách nhiệm của người chia sẻ.","t":"tin-cap3","l":"kho"},{"p":"Trong phần mềm Scratch, khu vực nơi nhân vật biểu diễn và di chuyển được gọi là gì?","o":["Sân khấu","Thư mục","Bàn phím","Khối lệnh"],"a":"Sân khấu","h":"Hãy nhớ lại màn hình chính của Scratch, nơi con mèo đứng và đi lại.","e":"Khu vực nhân vật biểu diễn trong Scratch được gọi là Sân khấu.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong Scratch, hình con mèo mặc định và các hình khác được điều khiển để hoạt động được gọi chung là gì?","o":["Âm thanh","Nhân vật","Phông nền","Khối lệnh màu tím"],"a":"Nhân vật","h":"Đây là đối tượng mà em kéo thả khối lệnh để ra lệnh cho nó.","e":"Các đối tượng được lập trình để hoạt động trong Scratch gọi là nhân vật (mặc định là con mèo).","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi em bấm vào lá cờ xanh trong Scratch thì điều gì xảy ra?","o":["Máy tính tắt","Nhân vật bị xoá","Chương trình bắt đầu chạy","Đổi ngôn ngữ của phần mềm"],"a":"Chương trình bắt đầu chạy","h":"Lá cờ xanh nằm ngay phía trên sân khấu.","e":"Bấm vào lá cờ xanh là lệnh bắt đầu chạy chương trình trong Scratch.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn nhân vật trong Scratch bước đi về phía trước, em dùng khối lệnh nào?","o":["Khối nói 'Xin chào'","Khối chờ 1 giây","Khối đổi màu nhân vật","Khối di chuyển 10 bước"],"a":"Khối di chuyển 10 bước","h":"Hãy nghĩ đến nhóm khối lệnh Chuyển động.","e":"Khối 'di chuyển 10 bước' thuộc nhóm Chuyển động, giúp nhân vật tiến về phía trước.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn nhân vật trong Scratch thay đổi hình dáng bên ngoài, ví dụ mặc thêm áo hoặc đổi kiểu dáng, em cần thay đổi phần nào?","o":["Trang phục của nhân vật","Âm thanh","Tên của tệp","Tốc độ con trỏ chuột"],"a":"Trang phục của nhân vật","h":"Trong Scratch có một thẻ riêng để chỉnh sửa vẻ ngoài của nhân vật.","e":"Hình dáng bên ngoài của nhân vật được thay đổi ở phần Trang phục.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Tệp trong máy tính là gì?","o":["Một chiếc hộp đựng giấy tờ","Một tập hợp thông tin được lưu trong máy tính và có tên gọi","Một loại chuột máy tính","Một phím trên bàn phím"],"a":"Một tập hợp thông tin được lưu trong máy tính và có tên gọi","h":"Bức tranh em vẽ và lưu lại trong máy là một ví dụ của điều này.","e":"Tệp là tập hợp thông tin (văn bản, hình ảnh, âm thanh...) được lưu trong máy tính và có tên gọi riêng.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi vẽ xong một bức tranh trong phần mềm vẽ, em nên làm gì để lần sau vẫn mở lại được bức tranh?","o":["Lưu tranh thành một tệp trong thư mục","Tắt máy ngay, không cần lưu","Xoá bức tranh rồi vẽ lại sau","Đóng phần mềm vẽ thật nhanh"],"a":"Lưu tranh thành một tệp trong thư mục","h":"Muốn dùng lại thì phải cất giữ cẩn thận.","e":"Lưu tranh thành tệp trong thư mục giúp em mở lại và xem tranh bất cứ lúc nào.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Sau khi vẽ xong một bức tranh trong phần mềm vẽ, muốn giữ bức tranh lại để lần sau xem tiếp, em cần làm gì?","o":["Tắt máy ngay lập tức","Xoá bức tranh đi","Đổi màu màn hình nền","Lưu bức tranh thành một tệp"],"a":"Lưu bức tranh thành một tệp","h":"Hãy nhớ thao tác giúp thông tin không bị mất khi tắt phần mềm.","e":"Muốn giữ lại bức tranh để xem sau, em cần lưu tranh thành một tệp trong máy tính.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong Scratch, khối lệnh 'lặp lại 10' có tác dụng gì?","o":["Lặp lại các khối lệnh bên trong đúng 10 lần","Dừng chương trình ngay lập tức","Thay đổi nhân vật khác","Xoá toàn bộ sân khấu"],"a":"Lặp lại các khối lệnh bên trong đúng 10 lần","h":"Số 10 trong tên khối lệnh chính là số lần thực hiện.","e":"Khối 'lặp lại 10' là khối vòng lặp, giúp các lệnh bên trong được thực hiện lặp lại 10 lần.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong Scratch, khối lệnh 'nếu ... thì ...' được dùng khi nào?","o":["Để nhân vật luôn luôn thực hiện lệnh","Để chỉ thực hiện các lệnh bên trong khi điều kiện đúng","Để xoá một biến số","Để tăng âm lượng của nhân vật"],"a":"Để chỉ thực hiện các lệnh bên trong khi điều kiện đúng","h":"Đây là khối điều kiện: có đúng thì mới làm, sai thì bỏ qua.","e":"Khối 'nếu ... thì ...' là khối điều kiện, các lệnh bên trong chỉ chạy khi điều kiện được thoả mãn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong một trò chơi Scratch, muốn ghi nhớ điểm số của người chơi đang thay đổi trong lúc chơi, em dùng thành phần nào?","o":["Trang phục","Phông nền","Biến số","Âm thanh"],"a":"Biến số","h":"Thành phần này có thể chứa một giá trị và giá trị đó thay đổi được.","e":"Biến số dùng để lưu trữ giá trị thay đổi trong khi chương trình chạy, ví dụ như điểm số của người chơi.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn nhân vật Scratch nhảy lên nhảy xuống nhiều lần liên tục mà không phải kéo thả nhiều khối lệnh giống nhau, em nên dùng nhóm khối nào?","o":["Nhóm khối Sự kiện","Nhóm khối Âm thanh","Nhóm khối Bút vẽ","Nhóm khối Điều khiển có vòng lặp"],"a":"Nhóm khối Điều khiển có vòng lặp","h":"Vòng lặp giúp một hành động được thực hiện nhiều lần.","e":"Các khối vòng lặp trong nhóm Điều khiển giúp lặp lại hành động nhiều lần mà không cần viết lại lệnh.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Biến 'điểm' trong Scratch đang có giá trị là 5. Sau khi thực hiện lệnh 'thay đổi điểm thêm 1', biến 'điểm' có giá trị là bao nhiêu?","o":["6","5","1","51"],"a":"6","h":"Hãy cộng thêm 1 vào giá trị hiện tại của biến.","e":"Giá trị của biến điểm là 5, tăng thêm 1 sẽ thành 5 + 1 = 6.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Lưu trữ trên đám mây là hình thức lưu trữ như thế nào?","o":["Lưu dữ liệu vào thẻ nhớ cắm trong máy","Lưu dữ liệu trên các máy chủ thông qua Internet để truy cập được từ nhiều thiết bị","Lưu dữ liệu ra giấy rồi cất vào tủ","Lưu dữ liệu tạm thời rồi tự xoá sau 1 ngày"],"a":"Lưu dữ liệu trên các máy chủ thông qua Internet để truy cập được từ nhiều thiết bị","h":"Hãy nghĩ đến các dịch vụ như Google Drive mà em có thể mở tệp ở cả máy tính và điện thoại.","e":"Lưu trữ đám mây là lưu dữ liệu trên máy chủ qua Internet, giúp truy cập tệp từ nhiều thiết bị khác nhau.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Phần mềm bảng tính như Microsoft Excel được dùng chủ yếu để làm gì?","o":["Để vẽ tranh và tô màu","Để nghe nhạc và xem phim","Để làm việc với dữ liệu dạng bảng gồm hàng và cột, có thể tính toán","Để soạn thảo thư điện tử"],"a":"Để làm việc với dữ liệu dạng bảng gồm hàng và cột, có thể tính toán","h":"Tên gọi 'bảng tính' đã gợi ý về bảng và tính toán.","e":"Phần mềm bảng tính dùng để tổ chức dữ liệu theo hàng và cột và thực hiện các phép tính trên dữ liệu đó.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong bảng tính, mỗi vùng nhỏ nằm ở giao của một hàng và một cột được gọi là gì?","o":["Trang tính","Tệp tính","Thanh công thức","Ô tính"],"a":"Ô tính","h":"Đây là nơi em nhấp chuột vào để nhập một số liệu.","e":"Giao của một hàng và một cột trong bảng tính tạo thành một ô tính, là nơi chứa dữ liệu.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong Excel, ô tính nằm ở cột B và hàng 3 có địa chỉ là gì?","o":["B3","3B","B-3","Cột B hàng 3 không có địa chỉ"],"a":"B3","h":"Địa chỉ ô gồm chữ cái của cột viết trước, số của hàng viết sau.","e":"Địa chỉ ô tính được viết bằng chữ cái cột kết hợp số hàng, ô ở cột B hàng 3 có địa chỉ B3.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong Excel, muốn tính tổng các số trong một dãy ô, em dùng hàm nào?","o":["Hàm MAX","Hàm SUM","Hàm IF","Hàm LEFT"],"a":"Hàm SUM","h":"Tên hàm là một từ tiếng Anh có nghĩa là 'tổng'.","e":"Hàm SUM trong Excel dùng để tính tổng các số trong một dãy ô được chọn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Sau khi nhập xong số liệu vào bảng tính, việc làm cần thiết để lần sau mở lại được bảng tính là gì?","o":["Đóng bảng tính mà không lưu","In bảng tính ra giấy rồi xoá tệp","Lưu bảng tính thành một tệp","Đổi tên của máy tính"],"a":"Lưu bảng tính thành một tệp","h":"Thao tác này thường dùng tổ hợp phím Ctrl + S.","e":"Cần lưu bảng tính thành tệp thì lần sau mới mở lại và sử dụng tiếp được.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Từ khoá tìm kiếm trên Internet là gì?","o":["Mật khẩu của máy tìm kiếm","Tên của trang web đầu tiên hiện ra","Địa chỉ nhà của người tìm kiếm","Các từ quan trọng được gõ vào ô tìm kiếm để tìm đúng thông tin cần thiết"],"a":"Các từ quan trọng được gõ vào ô tìm kiếm để tìm đúng thông tin cần thiết","h":"Khi em gõ 'thời tiết Hà Nội hôm nay', các từ em gõ chính là thứ đang được hỏi.","e":"Từ khoá là các từ quan trọng người dùng nhập vào máy tìm kiếm để tìm thông tin mong muốn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi tìm thông tin để làm bài tập, nguồn thông tin nào sau đây đáng tin cậy hơn cả?","o":["Trang web chính thức của cơ quan nhà nước hoặc của trường học","Một bình luận không rõ người viết trên mạng xã hội","Trang web lạ không ghi nguồn và tác giả","Tin nhắn chuyển tiếp trong nhóm chat"],"a":"Trang web chính thức của cơ quan nhà nước hoặc của trường học","h":"Hãy chọn nguồn có cơ quan, tổ chức chịu trách nhiệm về nội dung.","e":"Trang web chính thức của cơ quan nhà nước, trường học có tổ chức chịu trách nhiệm nên thông tin đáng tin cậy hơn.","t":"tin-cap1","l":"thu-thach"},{"p":"Em đọc được một tin giật gân trên mạng xã hội nhưng chưa rõ đúng sai. Việc làm đúng nhất là gì?","o":["Chia sẻ ngay cho bạn bè cùng biết","Kiểm chứng thông tin ở nhiều nguồn đáng tin cậy trước khi tin và chia sẻ","Tin ngay vì tin có nhiều lượt thích","Coi như tin thật vì có kèm hình ảnh"],"a":"Kiểm chứng thông tin ở nhiều nguồn đáng tin cậy trước khi tin và chia sẻ","h":"Đừng vội tin hay chia sẻ khi chưa chắc chắn.","e":"Cần kiểm chứng thông tin từ nhiều nguồn đáng tin cậy trước khi tin và chia sẻ để tránh lan truyền tin sai.","t":"tin-cap2","l":"thu-thach"},{"p":"Khi tìm kiếm thông tin trên mạng, kết quả hiện ra đầu tiên thì sao?","o":["Chưa chắc đã đúng và đáng tin nhất, cần kiểm tra thêm","Luôn luôn là thông tin đúng nhất","Chỉ là quảng cáo, không bao giờ nên xem","Máy tính đã kiểm chứng đúng hết rồi"],"a":"Chưa chắc đã đúng và đáng tin nhất, cần kiểm tra thêm","h":"Thứ tự hiện ra không đồng nghĩa với độ tin cậy.","e":"Kết quả đầu tiên chưa chắc đáng tin nhất; cần đối chiếu với các nguồn uy tín khác.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Vì sao khi tìm kiếm thông tin, em không nên chỉ dựa vào kết quả đầu tiên hiện ra?","o":["Vì kết quả đầu tiên luôn luôn sai","Vì máy tìm kiếm không cho mở kết quả đầu tiên","Vì kết quả đầu tiên chỉ mở được trên điện thoại","Vì kết quả đầu tiên có thể là quảng cáo hoặc chưa chính xác, cần đối chiếu thêm các nguồn khác"],"a":"Vì kết quả đầu tiên có thể là quảng cáo hoặc chưa chính xác, cần đối chiếu thêm các nguồn khác","h":"Thứ tự xuất hiện không đồng nghĩa với độ chính xác.","e":"Kết quả tìm kiếm đầu tiên có thể là quảng cáo hoặc thông tin chưa được kiểm chứng, vì vậy cần xem và đối chiếu nhiều nguồn.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong Scratch, khối 'lặp lại liên tục' khác khối 'lặp lại 10' ở điểm nào?","o":["Khối 'lặp lại liên tục' chạy chậm hơn","Khối 'lặp lại liên tục' lặp không giới hạn số lần cho đến khi chương trình dừng, còn 'lặp lại 10' chỉ lặp đúng 10 lần","Khối 'lặp lại liên tục' chỉ dùng cho âm thanh","Hai khối hoàn toàn giống nhau"],"a":"Khối 'lặp lại liên tục' lặp không giới hạn số lần cho đến khi chương trình dừng, còn 'lặp lại 10' chỉ lặp đúng 10 lần","h":"Hãy chú ý đến số lần lặp của mỗi khối.","e":"Khối 'lặp lại liên tục' lặp vô hạn cho đến khi dừng chương trình, trong khi 'lặp lại 10' lặp với số lần xác định.","t":"tin-cap1","l":"thu-thach"},{"p":"Trong Scratch, khối lệnh 'khi phím cách được bấm' thuộc nhóm khối nào và có vai trò gì?","o":["Nhóm Chuyển động, giúp nhân vật di chuyển","Nhóm Hiển thị, giúp đổi trang phục","Nhóm Sự kiện, giúp chương trình phản ứng khi người dùng bấm phím cách","Nhóm Toán học, giúp tính toán số học"],"a":"Nhóm Sự kiện, giúp chương trình phản ứng khi người dùng bấm phím cách","h":"Các khối bắt đầu bằng từ 'khi...' thường nằm chung một nhóm.","e":"Khối 'khi phím cách được bấm' thuộc nhóm Sự kiện, dùng để bắt đầu một đoạn lệnh khi người dùng bấm phím.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Một thuật toán tốt cần bảo đảm điều gì?","o":["Các bước rõ ràng, có thứ tự, hữu hạn và thực hiện được","Càng nhiều bước càng tốt","Chỉ có máy tính mới hiểu được","Không cần sắp xếp thứ tự các bước"],"a":"Các bước rõ ràng, có thứ tự, hữu hạn và thực hiện được","h":"Thuật toán là dãy bước giải quyết một việc cụ thể.","e":"Thuật toán gồm các bước rõ ràng theo thứ tự, số bước hữu hạn và mỗi bước đều thực hiện được.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Khi mô tả thuật toán bằng sơ đồ khối, hình ô-van (hình bầu dục) thường thể hiện điều gì?","o":["Một phép tính cần thực hiện","Điểm bắt đầu hoặc kết thúc của thuật toán","Một điều kiện cần kiểm tra","Dữ liệu cần in ra giấy"],"a":"Điểm bắt đầu hoặc kết thúc của thuật toán","h":"Mỗi sơ đồ khối đều có điểm mở đầu và điểm kết thúc.","e":"Trong sơ đồ khối, hình ô-van quy ước dùng để thể hiện điểm bắt đầu hoặc kết thúc của thuật toán.","t":"tin-cap2","l":"thu-thach"},{"p":"Chương trình máy tính là gì?","o":["Danh sách các phần mềm bán trong cửa hàng","Bản hướng dẫn sử dụng máy tính bằng giấy","Dãy các lệnh được viết bằng ngôn ngữ lập trình để máy tính thực hiện theo một thuật toán","Tên gọi khác của màn hình máy tính"],"a":"Dãy các lệnh được viết bằng ngôn ngữ lập trình để máy tính thực hiện theo một thuật toán","h":"Thuật toán khi được viết ra bằng ngôn ngữ lập trình sẽ trở thành điều này.","e":"Chương trình là dãy lệnh viết bằng ngôn ngữ lập trình, thể hiện thuật toán để máy tính thực hiện.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Xét bài toán: nhập hai số a và b, tính và in ra tổng của chúng. Đầu vào và đầu ra của bài toán là gì?","o":["Đầu vào là tổng, đầu ra là a và b","Đầu vào là bàn phím, đầu ra là màn hình","Đầu vào là máy tính, đầu ra là chương trình","Đầu vào là hai số a và b, đầu ra là tổng của a và b"],"a":"Đầu vào là hai số a và b, đầu ra là tổng của a và b","h":"Đầu vào là dữ kiện được cho ban đầu, đầu ra là kết quả cần tìm.","e":"Bài toán nhận đầu vào là hai số a và b, xử lí cộng hai số và cho đầu ra là tổng của chúng.","t":"tin-cap2","l":"thu-thach"},{"p":"Máy tính điện tử ENIAC ra đời năm 1946, sử dụng bóng đèn điện tử chân không, thuộc thế hệ máy tính thứ mấy?","o":["Thế hệ thứ nhất","Thế hệ thứ hai","Thế hệ thứ ba","Thế hệ thứ tư"],"a":"Thế hệ thứ nhất","h":"Linh kiện bóng đèn điện tử chân không là đặc trưng của thế hệ đầu tiên.","e":"ENIAC dùng bóng đèn điện tử chân không nên thuộc thế hệ máy tính thứ nhất.","t":"tin-cap2","l":"thu-thach"},{"p":"Máy tính thế hệ thứ hai sử dụng linh kiện điện tử chính nào thay cho bóng đèn chân không?","o":["Vi mạch tích hợp IC","Bóng bán dẫn (transistor)","Bộ vi xử lí","Đĩa quang"],"a":"Bóng bán dẫn (transistor)","h":"Linh kiện này nhỏ gọn và ít tốn điện hơn bóng đèn chân không rất nhiều.","e":"Máy tính thế hệ thứ hai dùng bóng bán dẫn (transistor) làm linh kiện chính, giúp máy nhỏ hơn và nhanh hơn thế hệ thứ nhất.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Số 9 trong hệ thập phân được biểu diễn trong hệ nhị phân là gì?","o":["1000","1010","1001","1111"],"a":"1001","h":"Hãy phân tích 9 thành tổng của các luỹ thừa của 2: 8 + 1.","e":"9 = 8 + 1 = 1×2³ + 0×2² + 0×2¹ + 1×2⁰ nên biểu diễn nhị phân của 9 là 1001.","t":"tin-cap2","l":"thu-thach"},{"p":"Vì sao máy tính sử dụng hệ nhị phân để lưu trữ và xử lí thông tin?","o":["Vì hệ nhị phân có nhiều chữ số hơn hệ thập phân","Vì con người quen đếm bằng hai ngón tay","Vì máy tính chỉ hiểu được hai chữ số 0 và 1","Vì các linh kiện điện tử có hai trạng thái dễ phân biệt là bật/tắt (có điện/không có điện), ứng với 1 và 0"],"a":"Vì các linh kiện điện tử có hai trạng thái dễ phân biệt là bật/tắt (có điện/không có điện), ứng với 1 và 0","h":"Hãy nghĩ đến trạng thái của một công tắc điện.","e":"Linh kiện điện tử chỉ có hai trạng thái ổn định dễ biểu diễn là bật và tắt, tương ứng hai chữ số 0 và 1 của hệ nhị phân.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong Python, câu lệnh print(\"Xin chào\") thực hiện việc gì?","o":["Nhận dữ liệu từ bàn phím","In dòng chữ Xin chào ra màn hình","Tạo một biến tên Xin chào","Dừng chương trình ngay lập tức"],"a":"In dòng chữ Xin chào ra màn hình","h":"Từ 'print' trong tiếng Anh liên quan đến việc hiển thị ra.","e":"Hàm print trong Python dùng để đưa dữ liệu ra màn hình, ở đây là dòng chữ Xin chào.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong Python, câu lệnh x = 5 có nghĩa là gì?","o":["So sánh x với số 5","In số 5 ra màn hình","Gán giá trị 5 cho biến x","Xoá biến x khỏi chương trình"],"a":"Gán giá trị 5 cho biến x","h":"Dấu = trong lập trình thường là phép gán, không phải phép so sánh.","e":"Câu lệnh x = 5 là phép gán, lưu giá trị 5 vào biến x để sử dụng trong chương trình.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong Python, hàm input() được dùng để làm gì?","o":["In kết quả ra màn hình","Thực hiện phép tính cộng","Tạo một số ngẫu nhiên","Nhận dữ liệu do người dùng nhập vào từ bàn phím"],"a":"Nhận dữ liệu do người dùng nhập vào từ bàn phím","h":"Từ 'input' có nghĩa là đưa vào.","e":"Hàm input() giúp chương trình nhận dữ liệu người dùng gõ từ bàn phím, dữ liệu nhận được ở dạng chuỗi.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Cho đoạn chương trình Python: tuoi = 15; nếu tuoi >= 18 thì in 'Đủ tuổi', ngược lại (else) in 'Chưa đủ tuổi'. Chương trình sẽ in ra dòng nào?","o":["Chưa đủ tuổi","Đủ tuổi","In cả hai dòng","Không in dòng nào"],"a":"Chưa đủ tuổi","h":"Hãy so sánh giá trị 15 với điều kiện >= 18.","e":"Vì tuoi = 15 nhỏ hơn 18 nên điều kiện sai, chương trình thực hiện nhánh else và in 'Chưa đủ tuổi'.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong Python, giá trị \"2026\" viết trong dấu ngoặc kép khác giá trị 2026 không có ngoặc kép ở điểm nào?","o":["Hai giá trị hoàn toàn giống nhau","\"2026\" là một chuỗi kí tự, còn 2026 là một số nguyên","\"2026\" là một số thập phân","2026 là một chuỗi kí tự, còn \"2026\" là số nguyên"],"a":"\"2026\" là một chuỗi kí tự, còn 2026 là một số nguyên","h":"Dấu ngoặc kép trong Python dùng để bao quanh một loại dữ liệu đặc biệt.","e":"Trong Python, dữ liệu đặt trong dấu ngoặc kép là chuỗi (str), còn 2026 không có ngoặc kép là số nguyên (int).","t":"tin-cap2","l":"thu-thach"},{"p":"Xác thực hai lớp (2FA) giúp tăng an toàn tài khoản vì lí do nào?","o":["Làm cho mật khẩu dài hơn tự động","Ngoài mật khẩu, kẻ xấu còn cần thêm mã xác thực từ thiết bị của người dùng","Giúp đăng nhập nhanh hơn","Tự động đổi mật khẩu mỗi ngày"],"a":"Ngoài mật khẩu, kẻ xấu còn cần thêm mã xác thực từ thiết bị của người dùng","h":"Hãy nghĩ xem sau khi nhập mật khẩu, hệ thống còn yêu cầu thêm gì.","e":"Xác thực hai lớp yêu cầu thêm một yếu tố nữa (mã OTP hoặc ứng dụng xác thực) nên dù lộ mật khẩu, kẻ xấu vẫn khó vào được tài khoản.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong Excel, để sắp xếp danh sách học sinh theo cột Điểm từ cao xuống thấp, ta chọn vùng dữ liệu rồi dùng lệnh nào?","o":["Data → Filter","Home → Find & Select","Data → Sort, chọn cột Điểm và thứ tự Z to A (lớn đến nhỏ)","Insert → Chart"],"a":"Data → Sort, chọn cột Điểm và thứ tự Z to A (lớn đến nhỏ)","h":"Sắp xếp dữ liệu nằm trong nhóm lệnh của thẻ Data.","e":"Lệnh Sort trong thẻ Data cho phép sắp xếp theo một hoặc nhiều cột; với số, thứ tự giảm dần là từ lớn đến nhỏ.","t":"tin-cap2","l":"thu-thach"},{"p":"Tính năng lọc dữ liệu (Filter) trong Excel dùng để làm gì?","o":["Xoá vĩnh viễn các hàng không cần thiết","Đổi màu nền của bảng dữ liệu","Gộp nhiều ô thành một ô","Chỉ hiển thị các hàng thoả mãn điều kiện, các hàng còn lại tạm ẩn đi"],"a":"Chỉ hiển thị các hàng thoả mãn điều kiện, các hàng còn lại tạm ẩn đi","h":"Lọc không xoá dữ liệu, chỉ thay đổi cách hiển thị.","e":"Filter giúp xem nhanh nhóm dữ liệu theo điều kiện (ví dụ chỉ xem học sinh nữ); bỏ lọc thì toàn bộ dữ liệu lại hiện ra.","t":"tin-cap2","l":"thu-thach"},{"p":"Ô A1 chứa điểm 8. Công thức =IF(A1>=8,\"Giỏi\",\"Khá\") cho kết quả nào?","o":["Giỏi","Khá","8","Báo lỗi"],"a":"Giỏi","h":"Hãy xét điều kiện A1>=8 có đúng không.","e":"Điểm 8 thoả mãn điều kiện >=8 nên hàm IF trả về giá trị khi điều kiện đúng là \"Giỏi\".","t":"tin-cap2","l":"thu-thach"},{"p":"Để đếm số học sinh có điểm từ 8 trở lên trong vùng B2:B31, công thức đúng là:","o":["=SUMIF(B2:B31,\">=8\")","=COUNTIF(B2:B31,\">=8\")","=COUNT(B2:B31)","=AVERAGEIF(B2:B31,\">=8\")"],"a":"=COUNTIF(B2:B31,\">=8\")","h":"Đếm theo điều kiện thì dùng hàm có cả COUNT và IF.","e":"COUNTIF đếm số ô trong vùng thoả mãn điều kiện cho trước; ở đây điều kiện là \">=8\".","t":"tin-cap2","l":"thu-thach"},{"p":"Khi muốn so sánh trực quan số lượng học sinh của 4 lớp bằng biểu đồ trong Excel, sau khi chọn bảng dữ liệu ta thực hiện:","o":["Vào thẻ Data → chọn Sort","Vào thẻ Home → chọn Conditional Formatting","Vào thẻ Insert → chọn kiểu biểu đồ cột (Column)","Vào thẻ Formulas → chọn Insert Function"],"a":"Vào thẻ Insert → chọn kiểu biểu đồ cột (Column)","h":"Biểu đồ được chèn từ thẻ Insert.","e":"Thẻ Insert chứa nhóm Charts để chèn các kiểu biểu đồ; biểu đồ cột thích hợp để so sánh số lượng giữa các nhóm.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong cơ sở dữ liệu quan hệ, một bảng (table) được tổ chức gồm:","o":["Các tệp và thư mục","Các trang và các đoạn","Các ô tính và công thức","Các hàng và các cột"],"a":"Các hàng và các cột","h":"Hãy hình dung một bảng dữ liệu quen thuộc như danh sách lớp.","e":"Bảng trong CSDL quan hệ gồm các cột (thuộc tính) và các hàng (bản ghi) giao nhau tạo thành dữ liệu có cấu trúc.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong một bảng của CSDL quan hệ, 'trường' (field) và 'bản ghi' (record) tương ứng với:","o":["Cột và hàng","Hàng và cột","Tệp và thư mục","Khoá và quan hệ"],"a":"Cột và hàng","h":"Mỗi cột mô tả một thuộc tính chung cho mọi dòng dữ liệu.","e":"Trường là một cột, mô tả một thuộc tính (ví dụ Họ tên); bản ghi là một hàng, chứa dữ liệu của một đối tượng cụ thể.","t":"tin-cap3","l":"thu-thach"},{"p":"Khoá chính (primary key) của một bảng là gì?","o":["Cột chứa mật khẩu của bảng","Một trường (hoặc tập hợp trường) mà giá trị của nó xác định duy nhất mỗi bản ghi trong bảng","Cột đầu tiên của bảng","Trường dùng để sắp xếp bảng theo thứ tự bảng chữ cái"],"a":"Một trường (hoặc tập hợp trường) mà giá trị của nó xác định duy nhất mỗi bản ghi trong bảng","h":"Nhờ khoá chính ta phân biệt được hai bản ghi khác nhau.","e":"Khoá chính đảm bảo mỗi bản ghi là duy nhất: giá trị khoá không được trùng lặp và không được để trống (NULL).","t":"tin-cap3","l":"thu-thach"},{"p":"Bảng HOCSINH có trường MaLop, bảng LOP có khoá chính MaLop. Trường MaLop trong bảng HOCSINH đóng vai trò gì để tạo quan hệ giữa hai bảng?","o":["Khoá chính","Chỉ mục","Khoá ngoại","Trường tính toán"],"a":"Khoá ngoại","h":"Nó tham chiếu tới khoá chính của bảng khác.","e":"Khoá ngoại là trường trong một bảng chứa giá trị của khoá chính ở bảng khác, nhờ đó hai bảng liên kết được với nhau.","t":"tin-cap3","l":"thu-thach"},{"p":"Vì sao khi thiết kế CSDL, thông tin lớp học (tên lớp, giáo viên chủ nhiệm) được tách thành bảng LOP riêng thay vì ghi lặp lại trong mọi bản ghi học sinh?","o":["Để bảng học sinh trông ngắn hơn khi in","Vì Excel không cho ghi chữ trùng nhau","Để mỗi bảng chỉ có đúng 10 hàng","Tránh dư thừa dữ liệu và tránh mâu thuẫn khi cần sửa thông tin lớp"],"a":"Tránh dư thừa dữ liệu và tránh mâu thuẫn khi cần sửa thông tin lớp","h":"Nghĩ tới việc đổi tên giáo viên chủ nhiệm cho 40 học sinh cùng lớp.","e":"Tách bảng giúp mỗi thông tin chỉ lưu một nơi: khi sửa tên giáo viên chỉ sửa một bản ghi, tránh lặp lại và sai lệch dữ liệu.","t":"tin-cap3","l":"thu-thach"},{"p":"Điểm khác nhau cơ bản giữa ảnh bitmap và ảnh vector là gì?","o":["Ảnh bitmap lưu bằng các điểm ảnh (pixel), ảnh vector lưu bằng các đối tượng hình học và công thức toán học","Ảnh bitmap luôn có dung lượng nhỏ hơn ảnh vector","Ảnh vector không thể phóng to","Ảnh bitmap chỉ có hai màu đen trắng"],"a":"Ảnh bitmap lưu bằng các điểm ảnh (pixel), ảnh vector lưu bằng các đối tượng hình học và công thức toán học","h":"Khác biệt nằm ở cách máy tính lưu trữ hình ảnh.","e":"Ảnh bitmap ghép từ lưới pixel nên phóng to dễ bị vỡ hạt; ảnh vector mô tả bằng đường nét toán học nên phóng to vẫn nét.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong phần mềm chỉnh sửa ảnh, 'lớp' (layer) có tác dụng gì?","o":["Làm tăng dung lượng tệp ảnh lên gấp đôi","Cho phép chỉnh sửa từng phần của ảnh độc lập mà không ảnh hưởng tới phần khác","Tự động nén ảnh khi lưu","Chia ảnh thành các ô vuông bằng nhau"],"a":"Cho phép chỉnh sửa từng phần của ảnh độc lập mà không ảnh hưởng tới phần khác","h":"Hãy tưởng tượng các tấm kính trong suốt chồng lên nhau.","e":"Mỗi layer như một tấm phim trong suốt chứa một phần của bức ảnh; ta có thể sửa, ẩn hoặc di chuyển từng lớp riêng biệt.","t":"tin-cap3","l":"thu-thach"},{"p":"Thao tác nào sau đây thuộc về chỉnh sửa video cơ bản?","o":["Viết mã nguồn cho trang web","Thiết kế cơ sở dữ liệu cho ứng dụng","Cắt ghép các đoạn clip, chèn chữ, thêm nhạc nền và xuất video","Cài đặt hệ điều hành cho máy quay"],"a":"Cắt ghép các đoạn clip, chèn chữ, thêm nhạc nền và xuất video","h":"Chỉnh sửa video làm việc với các đoạn hình ảnh và âm thanh theo dòng thời gian.","e":"Biên tập video cơ bản gồm cắt, ghép clip trên timeline, thêm tiêu đề/phụ đề, âm thanh và xuất ra tệp video hoàn chỉnh.","t":"tin-cap3","l":"thu-thach"},{"p":"Âm thanh số được tạo ra bằng cách lấy mẫu (sampling) tín hiệu âm thanh liên tục. Tần số lấy mẫu càng cao thì:","o":["Âm thanh càng bị méo","Thời lượng âm thanh càng dài","Âm thanh chỉ còn một kênh mono","Chất lượng âm thanh càng tốt và dung lượng tệp càng lớn"],"a":"Chất lượng âm thanh càng tốt và dung lượng tệp càng lớn","h":"Lấy mẫu dày hơn thì ghi lại sóng âm chính xác hơn nhưng tốn nhiều dữ liệu hơn.","e":"Tần số lấy mẫu cao (ví dụ 44 100 Hz của CD) ghi lại sóng âm chi tiết hơn nên âm thanh trung thực hơn, đổi lại tệp lớn hơn.","t":"tin-cap3","l":"thu-thach"},{"p":"Ghép nối định dạng tệp với đúng loại nội dung: MP3, MP4, PNG lần lượt là:","o":["Âm thanh, video, hình ảnh","Hình ảnh, âm thanh, video","Video, hình ảnh, âm thanh","Âm thanh, hình ảnh, video"],"a":"Âm thanh, video, hình ảnh","h":"MP3 gắn liền với nhạc, MP4 gắn liền với phim.","e":"MP3 là định dạng âm thanh nén, MP4 là định dạng video phổ biến, PNG là định dạng hình ảnh hỗ trợ nền trong suốt.","t":"tin-cap3","l":"thu-thach"},{"p":"Công việc chính của lập trình viên (developer) là gì?","o":["Kiểm tra và sửa chữa đường truyền mạng","Phân tích yêu cầu, viết mã nguồn, kiểm tra và bảo trì phần mềm","Thiết kế giao diện đồ hoạ cho quảng cáo","Lắp ráp và sửa chữa phần cứng máy tính"],"a":"Phân tích yêu cầu, viết mã nguồn, kiểm tra và bảo trì phần mềm","h":"Tên gọi của nghề gắn với việc 'lập trình'.","e":"Lập trình viên biến yêu cầu bài toán thành chương trình bằng ngôn ngữ lập trình, đồng thời sửa lỗi và nâng cấp phần mềm theo thời gian.","t":"tin-cap3","l":"thu-thach"},{"p":"Người quản trị cơ sở dữ liệu (DBA) chịu trách nhiệm chính về việc nào sau đây?","o":["Viết nội dung quảng cáo cho website","Thiết kế logo cho hệ thống","Đảm bảo CSDL hoạt động ổn định, an toàn, sao lưu và phân quyền truy cập dữ liệu","Bán và phân phối phần mềm"],"a":"Đảm bảo CSDL hoạt động ổn định, an toàn, sao lưu và phân quyền truy cập dữ liệu","h":"Hãy nghĩ tới người 'giữ kho' dữ liệu của cả tổ chức.","e":"DBA quản lí toàn bộ vòng đời dữ liệu: tổ chức lưu trữ, bảo mật, phân quyền, sao lưu và khôi phục khi có sự cố.","t":"tin-cap3","l":"kho"},{"p":"Kiểm thử viên phần mềm (tester) thực hiện công việc nào?","o":["Quản lí lương cho nhân viên công ty","Cài đặt mạng LAN cho văn phòng","Viết tài liệu hướng dẫn sử dụng máy in","Thiết kế các trường hợp kiểm thử, chạy thử phần mềm để tìm lỗi và báo cáo cho đội phát triển"],"a":"Thiết kế các trường hợp kiểm thử, chạy thử phần mềm để tìm lỗi và báo cáo cho đội phát triển","h":"Công việc này diễn ra trước khi phần mềm đến tay người dùng.","e":"Tester xây dựng kịch bản kiểm thử (test case), thực thi và ghi nhận lỗi để đội phát triển sửa, giúp phần mềm đạt chất lượng trước khi phát hành.","t":"tin-cap3","l":"thu-thach"},{"p":"Điều kiện bắt buộc để áp dụng tìm kiếm nhị phân trên một danh sách là gì?","o":["Danh sách phải đã được sắp xếp","Danh sách phải có ít hơn 10 phần tử","Danh sách chỉ chứa các số nguyên dương","Danh sách phải lưu trong tệp văn bản"],"a":"Danh sách phải đã được sắp xếp","h":"Thuật toán so sánh với phần tử giữa rồi loại bỏ một nửa danh sách.","e":"Tìm kiếm nhị phân chỉ đúng trên dãy đã sắp xếp, vì sau mỗi lần so sánh với phần tử giữa ta loại được một nửa dãy khỏi vùng tìm.","t":"tin-cap3","l":"thu-thach"},{"p":"Với danh sách đã sắp xếp gồm 1 000 phần tử, tìm kiếm nhị phân cần tối đa khoảng bao nhiêu lần so sánh để tìm một phần tử?","o":["Khoảng 1 000 lần","Khoảng 10 lần","Khoảng 500 lần","Khoảng 100 lần"],"a":"Khoảng 10 lần","h":"Mỗi lần so sánh, vùng tìm kiếm giảm đi một nửa: 2 mũ mấy thì vượt 1 000?","e":"Mỗi bước vùng tìm giảm một nửa; 2^10 = 1 024 nên tối đa khoảng 10 lần so sánh, nhanh hơn hẳn tìm tuần tự (tối đa 1 000 lần).","t":"tin-cap3","l":"thu-thach"},{"p":"Thuật toán sắp xếp nổi bọt (bubble sort) hoạt động theo nguyên lí nào?","o":["Chia danh sách thành hai nửa rồi trộn lại","Chọn phần tử ở giữa làm chốt rồi phân hoạch","Lặp lại việc so sánh và đổi chỗ các cặp phần tử kề nhau sai thứ tự, phần tử lớn nhất 'nổi' dần về cuối","Đếm số lần xuất hiện của từng giá trị"],"a":"Lặp lại việc so sánh và đổi chỗ các cặp phần tử kề nhau sai thứ tự, phần tử lớn nhất 'nổi' dần về cuối","h":"Tên gọi của thuật toán gợi ý cách các phần tử di chuyển.","e":"Sắp xếp nổi bọt duyệt dãy nhiều lượt, đổi chỗ các cặp kề nhau nếu sai thứ tự, sau mỗi lượt phần tử lớn nhất về đúng vị trí cuối.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong Python, cho danh sách a = [3, 1, 4]. Sau khi thực hiện a.append(1) và a.sort(), danh sách a là:","o":["[3, 1, 4, 1]","[4, 3, 1, 1]","[1, 3, 4]","[1, 1, 3, 4]"],"a":"[1, 1, 3, 4]","h":"append thêm phần tử vào cuối, sort sắp xếp tăng dần tại chỗ.","e":"append(1) làm a thành [3, 1, 4, 1]; sort() sắp xếp tăng dần thành [1, 1, 3, 4].","t":"tin-cap3","l":"thu-thach"},{"p":"Cho xâu s = \"Tin hoc\". Kết quả của s.upper() và len(s) lần lượt là:","o":["\"TIN HOC\" và 7","\"tin hoc\" và 7","\"TIN HOC\" và 6","\"Tin Hoc\" và 8"],"a":"\"TIN HOC\" và 7","h":"upper() chuyển mọi chữ cái thành chữ hoa; len đếm cả dấu cách.","e":"s.upper() cho \"TIN HOC\"; xâu \"Tin hoc\" có 7 kí tự kể cả dấu cách ở giữa.","t":"tin-cap3","l":"thu-thach"},{"p":"Cho hàm: def f(n): return n * 2. Kết quả của biểu thức f(3) + f(\"A\") là gì?","o":["\"6AA\"","Báo lỗi TypeError vì không thể cộng số nguyên 6 với xâu \"AA\"","\"AA6\"","12"],"a":"Báo lỗi TypeError vì không thể cộng số nguyên 6 với xâu \"AA\"","h":"Hãy tính riêng f(3) và f(\"A\") rồi mới xét phép cộng.","e":"f(3) = 6; f(\"A\") = \"A\" * 2 = \"AA\" (nhân xâu với số nguyên là lặp lại xâu); phép cộng 6 + \"AA\" giữa số và xâu không thực hiện được nên Python báo lỗi TypeError.","t":"tin-cap3","l":"kho"},{"p":"Một thuật toán có độ phức tạp thời gian O(n²) và một thuật toán O(n) cùng giải một bài toán. Khi kích thước dữ liệu n tăng lên rất lớn, nhận định nào đúng?","o":["Thuật toán O(n²) luôn nhanh hơn","Hai thuật toán luôn tốn thời gian bằng nhau","Thuật toán O(n) tăng thời gian chậm hơn nên hiệu quả hơn với dữ liệu lớn","Độ phức tạp không ảnh hưởng tới thời gian chạy"],"a":"Thuật toán O(n) tăng thời gian chậm hơn nên hiệu quả hơn với dữ liệu lớn","h":"Hãy so sánh tốc độ tăng của n và n² khi n lớn dần.","e":"Độ phức tạp mô tả tốc độ tăng thời gian theo kích thước đầu vào; O(n) tăng tuyến tính nên với n lớn sẽ nhanh hơn hẳn O(n²).","t":"tin-cap3","l":"kho"},{"p":"Hàm đệ quy tính giai thừa được định nghĩa: f(0) = 1 và f(n) = n * f(n-1) với n > 0. Giá trị f(4) bằng bao nhiêu?","o":["10","16","12","24"],"a":"24","h":"Hãy tính lần lượt f(1), f(2), f(3) rồi f(4).","e":"f(1) = 1, f(2) = 2, f(3) = 6, f(4) = 4 × 6 = 24; điều kiện dừng f(0) = 1 giúp đệ quy kết thúc.","t":"tin-cap3","l":"thu-thach"},{"p":"Câu lệnh SQL nào lấy họ tên và điểm của tất cả học sinh trong bảng HOCSINH có điểm từ 8 trở lên?","o":["SELECT HoTen, Diem FROM HOCSINH WHERE Diem >= 8","GET HoTen, Diem FROM HOCSINH IF Diem >= 8","SELECT HoTen, Diem IN HOCSINH WHEN Diem >= 8","SHOW HoTen, Diem FROM HOCSINH WHERE Diem >= 8"],"a":"SELECT HoTen, Diem FROM HOCSINH WHERE Diem >= 8","h":"Cú pháp truy vấn gồm SELECT … FROM … WHERE …","e":"SELECT liệt kê các cột cần lấy, FROM chỉ bảng nguồn, WHERE đặt điều kiện lọc bản ghi (Diem >= 8).","t":"tin-cap3","l":"thu-thach"},{"p":"Để hiển thị danh sách học sinh theo điểm giảm dần, câu lệnh SQL cần thêm mệnh đề nào?","o":["GROUP BY Diem","ORDER BY Diem DESC","SORT BY Diem DOWN","ARRANGE Diem DESC"],"a":"ORDER BY Diem DESC","h":"Mệnh đề sắp xếp trong SQL bắt đầu bằng ORDER BY.","e":"ORDER BY Diem DESC sắp xếp kết quả theo cột Diem giảm dần; ASC (mặc định) là tăng dần.","t":"tin-cap3","l":"thu-thach"},{"p":"Câu lệnh nào thêm một học sinh mới vào bảng HOCSINH(MaHS, HoTen)?","o":["ADD INTO HOCSINH VALUES ('HS10', 'Lan')","PUT HOCSINH VALUES ('HS10', 'Lan')","INSERT INTO HOCSINH VALUES ('HS10', 'Lan')","NEW RECORD HOCSINH ('HS10', 'Lan')"],"a":"INSERT INTO HOCSINH VALUES ('HS10', 'Lan')","h":"Lệnh chèn bản ghi mới bắt đầu bằng INSERT INTO.","e":"INSERT INTO <bảng> VALUES (...) thêm một bản ghi mới; còn UPDATE dùng để sửa dữ liệu đã có, SELECT chỉ để truy vấn.","t":"tin-cap3","l":"thu-thach"},{"p":"Nhận định nào đúng về các câu lệnh SQL?","o":["SELECT dùng để sửa dữ liệu trong bảng","DELETE dùng để tạo bảng mới","INSERT dùng để sắp xếp kết quả truy vấn","UPDATE dùng để thay đổi giá trị của các bản ghi đã có, còn SELECT chỉ đọc dữ liệu mà không làm thay đổi bảng"],"a":"UPDATE dùng để thay đổi giá trị của các bản ghi đã có, còn SELECT chỉ đọc dữ liệu mà không làm thay đổi bảng","h":"Phân biệt nhóm lệnh truy vấn (đọc) với nhóm lệnh thay đổi dữ liệu.","e":"SELECT là lệnh truy vấn, không thay đổi dữ liệu; INSERT thêm, UPDATE sửa và DELETE xoá bản ghi trong bảng.","t":"tin-cap3","l":"thu-thach"},{"p":"Khi máy tính được kết nối với Internet, em có thể làm được việc nào sau đây?","o":["Xem bài giảng, đọc truyện và tìm thông tin ở khắp nơi trên thế giới","Máy tính tự chạy nhanh gấp đôi","Máy tính không cần dùng điện vẫn chạy được","Máy tính tự nói chuyện được với em"],"a":"Xem bài giảng, đọc truyện và tìm thông tin ở khắp nơi trên thế giới","h":"Internet nối các máy tính ở khắp nơi lại với nhau.","e":"Internet là mạng máy tính toàn cầu, giúp em học tập, đọc truyện và tìm thông tin từ khắp nơi trên thế giới.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Vì sao người ta gọi Internet là mạng máy tính toàn cầu?","o":["Vì Internet kết nối rất nhiều máy tính ở khắp nơi trên thế giới lại với nhau","Vì Internet chỉ có ở duy nhất một trường học","Vì máy tính nào cũng in hình quả địa cầu","Vì Internet là tên của một trò chơi"],"a":"Vì Internet chỉ có ở duy nhất một trường học","h":"Hãy nghĩ xem Internet có ở những nơi nào trên thế giới.","e":"Internet kết nối hàng tỉ máy tính và thiết bị ở khắp các nước trên thế giới nên được gọi là mạng máy tính toàn cầu.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Ở nhà em, điện thoại, máy tính bảng và tivi thông minh cùng kết nối vào mạng Wi-Fi của gia đình. Các thiết bị này được nối với nhau tạo thành gì?","o":["Một phần mềm vẽ tranh","Một mạng máy tính","Một thư mục lớn","Một chiếc máy in"],"a":"Một thư mục lớn","h":"Các thiết bị nối với nhau để chia sẻ thông tin với nhau.","e":"Khi các thiết bị được kết nối với nhau để liên lạc và chia sẻ thông tin, chúng tạo thành một mạng máy tính, dù là mạng nhỏ trong gia đình.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi đang xem video trên mạng, em thấy một video có nội dung xấu và đáng sợ. Em nên làm gì?","o":["Gửi video đó cho các bạn cùng xem","Bấm vào tất cả quảng cáo hiện trên màn hình","Tắt video đó đi và nói với bố mẹ hoặc thầy cô","Tiếp tục xem cho đến hết video"],"a":"Tiếp tục xem cho đến hết video","h":"Gặp điều không hay trên mạng, em hãy nhờ người lớn giúp.","e":"Khi gặp nội dung xấu trên mạng, em cần tắt ngay và báo cho bố mẹ hoặc thầy cô để được giúp đỡ.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em muốn xem phim hoạt hình trên mạng. Cách làm nào sau đây là an toàn nhất?","o":["Xem trên trang quen thuộc dành cho thiếu nhi và nhờ người lớn giúp khi cần","Bấm vào bất kì quảng cáo nào hiện ra trên màn hình","Tự tải mọi bộ phim từ các trang lạ về máy","Xem một mình và giấu không cho bố mẹ biết"],"a":"Bấm vào bất kì quảng cáo nào hiện ra trên màn hình","h":"Chỉ xem ở những nơi quen thuộc, đáng tin cậy.","e":"Xem phim ở các trang quen thuộc dành cho thiếu nhi và có người lớn bên cạnh giúp em tránh được nội dung xấu và quảng cáo lừa đảo.","t":"tin-cap1","l":"thu-thach"},{"p":"Trong máy tính, thư mục là gì?","o":["Là nơi dùng để chứa các tệp, giúp sắp xếp dữ liệu gọn gàng","Là một loại trò chơi trên máy tính","Là bộ phận phát ra âm thanh","Là sợi dây nối máy tính với ổ điện"],"a":"Là nơi dùng để chứa các tệp, giúp sắp xếp dữ liệu gọn gàng","h":"Thư mục giống như một ngăn tủ để cất đồ.","e":"Thư mục là nơi chứa các tệp và thư mục con, giúp em sắp xếp dữ liệu trong máy tính gọn gàng, ngăn nắp.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em vẽ được rất nhiều bức tranh bằng máy tính và muốn cất riêng chúng vào một chỗ cho dễ tìm. Em nên làm gì?","o":["Để các bức tranh rải rác khắp nơi trong máy tính","Tạo một thư mục mới và lưu các bức tranh vào thư mục đó","Xoá hết các bức tranh đi","Đổi tên cho chiếc máy tính"],"a":"Xoá hết các bức tranh đi","h":"Muốn đồ vật gọn gàng, em xếp chúng vào cùng một ngăn.","e":"Tạo một thư mục riêng để chứa các bức tranh giúp em cất giữ và tìm lại tranh nhanh chóng, không bị lẫn với tệp khác.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Hôm qua em đã lưu tệp tranh vào thư mục có tên 'Tranh của em'. Hôm nay muốn mở lại bức tranh đó, em tìm ở đâu?","o":["Vẽ lại một bức tranh hoàn toàn khác","Hỏi máy tính bằng cách hét thật to","Mở thư mục 'Tranh của em' và chọn tệp tranh đã lưu","Tìm trong thùng rác ở góc lớp học"],"a":"Tìm trong thùng rác ở góc lớp học","h":"Hãy nhớ lại hôm qua em đã lưu tệp vào đâu.","e":"Tệp được lưu ở thư mục nào thì em mở đúng thư mục đó để tìm và mở lại tệp.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi nhắn tin, trò chuyện với bạn qua mạng, em nên ứng xử như thế nào?","o":["Nói năng lịch sự, tôn trọng bạn như khi nói chuyện trực tiếp","Nói thế nào cũng được vì bạn không nhìn thấy mình","Dùng lời lẽ trêu chọc, chế giễu bạn","Giả làm người khác để nhắn tin trêu bạn"],"a":"Nói năng lịch sự, tôn trọng bạn như khi nói chuyện trực tiếp","h":"Dù ở trên mạng, em vẫn đang nói chuyện với người thật.","e":"Khi giao tiếp qua mạng, em cần nói năng lịch sự và tôn trọng người khác giống như khi nói chuyện trực tiếp.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em thấy một bạn trong lớp bị nhiều người nói xấu, trêu chọc trong nhóm trò chuyện trên mạng. Em nên làm gì?","o":["Không hùa theo và nói với thầy cô hoặc bố mẹ để giúp bạn","Cùng vào trêu chọc bạn cho vui","Chụp lại màn hình rồi gửi cho thật nhiều người xem","Mặc kệ vì chuyện đó không liên quan đến mình"],"a":"Cùng vào trêu chọc bạn cho vui","h":"Bắt nạt bạn trên mạng cũng là việc làm sai.","e":"Em không nên hùa theo việc trêu chọc bạn mà cần báo với thầy cô hoặc bố mẹ để kịp thời giúp đỡ bạn.","t":"tin-cap1","l":"thu-thach"},{"p":"Em thấy một bức tranh rất đẹp trên mạng do một bạn khác vẽ. Việc làm nào sau đây là đúng?","o":["Xoá tên của bạn đó trên bức tranh đi","Xin phép bạn đó và khi dùng thì ghi rõ tranh là của bạn","Tự ý lấy tranh về và nói đó là tranh của mình","Mang bức tranh đó bán lấy tiền"],"a":"Tự ý lấy tranh về và nói đó là tranh của mình","h":"Đồ của người khác, muốn dùng thì phải xin phép.","e":"Bức tranh là sản phẩm của người vẽ; em cần xin phép và ghi rõ tên người vẽ khi sử dụng, đó là tôn trọng bản quyền.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Bạn em chép nguyên một bài văn hay trên mạng rồi nộp cho cô giáo và nói là tự mình viết. Theo em, việc làm đó như thế nào?","o":["Đúng, vì chép như vậy sẽ được điểm cao","Không sao, miễn là bạn chép chữ thật đẹp","Sai, vì lấy bài của người khác rồi nhận là của mình là không trung thực","Đúng, vì bài văn trên mạng thì ai dùng cũng được"],"a":"Đúng, vì bài văn trên mạng thì ai dùng cũng được","h":"Em hãy nghĩ: bài văn đó thật sự là của ai?","e":"Chép bài của người khác rồi nhận là của mình là việc làm sai và không trung thực; em nên tự viết bài hoặc ghi rõ nguồn khi tham khảo.","t":"tin-cap1","l":"thu-thach"},{"p":"Muốn tạo một thư mục mới trên màn hình nền (Desktop), em nháy chuột phải vào vùng trống rồi chọn lệnh nào?","o":["Xoá (Delete)","Mới (New) rồi chọn Thư mục (Folder)","Mở (Open)","Đổi tên (Rename)"],"a":"Mở (Open)","h":"Hãy nhớ thực đơn hiện ra khi em nháy chuột phải.","e":"Để tạo thư mục mới, em nháy chuột phải vào vùng trống, chọn Mới (New) rồi chọn Thư mục (Folder) và đặt tên cho thư mục.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em muốn sao chép một tệp sang thư mục khác mà tệp gốc vẫn còn nguyên ở chỗ cũ. Em dùng cặp lệnh nào?","o":["Sao chép (Copy) rồi Dán (Paste)","Cắt (Cut) rồi Dán (Paste)","Xoá (Delete) rồi Dán (Paste)","Đổi tên (Rename) rồi Lưu (Save)"],"a":"Sao chép (Copy) rồi Dán (Paste)","h":"Sao chép nghĩa là tạo thêm một bản giống hệt.","e":"Lệnh Sao chép (Copy) tạo một bản sao của tệp và lệnh Dán (Paste) đặt bản sao vào thư mục mới, tệp gốc vẫn còn nguyên.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em muốn di chuyển hẳn một tệp sang thư mục khác, để thư mục cũ không còn tệp đó nữa. Em dùng cặp lệnh nào?","o":["Cắt (Cut) rồi Dán (Paste)","Chỉ chọn lệnh Dán (Paste)","Sao chép (Copy) rồi Dán (Paste)","Đổi tên (Rename) cho tệp đó"],"a":"Chỉ chọn lệnh Dán (Paste)","h":"Di chuyển khác sao chép ở chỗ tệp gốc có còn hay không.","e":"Lệnh Cắt (Cut) rồi Dán (Paste) sẽ chuyển hẳn tệp sang thư mục mới và thư mục cũ không còn tệp đó nữa.","t":"tin-cap1","l":"thu-thach"},{"p":"Em chọn một tệp không cần dùng nữa rồi nhấn phím Delete trên bàn phím. Tệp đó sẽ được chuyển đến đâu?","o":["Bay lên mạng Internet","Vào chiếc USB của bạn ngồi bên cạnh","Vào Thùng rác (Recycle Bin) trên màn hình nền","Vào thư mục Âm nhạc"],"a":"Vào thư mục Âm nhạc","h":"Trên màn hình nền có một biểu tượng hình thùng rác.","e":"Tệp bị xoá được chuyển vào Thùng rác (Recycle Bin); khi cần, em vẫn có thể khôi phục lại tệp từ đó.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em muốn tìm cách trồng cây đậu trên Internet. Em nên gõ từ khoá nào vào ô tìm kiếm để có kết quả đúng ý nhất?","o":["Cách trồng cây đậu","Cây","Cách","Đậu"],"a":"Cách trồng cây đậu","h":"Từ khoá cần nói rõ đúng điều em muốn tìm.","e":"Từ khoá gồm các từ chính, rõ ràng như 'cách trồng cây đậu' sẽ giúp máy tìm kiếm cho kết quả đúng ý nhất.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi làm bài tập, em tìm được nhiều trang web cùng nói về một nội dung. Em nên ưu tiên đọc trang nào?","o":["Trang không ghi rõ là của ai, ở đâu","Trang của trường học, thư viện hoặc báo, đài chính thống","Trang có thật nhiều quảng cáo trúng thưởng","Trang bắt em nhập số điện thoại mới cho đọc"],"a":"Trang có thật nhiều quảng cáo trúng thưởng","h":"Hãy chọn nguồn thông tin mà em có thể tin cậy.","e":"Các trang của trường học, thư viện, báo và đài chính thống thường có thông tin được kiểm chứng nên đáng tin cậy hơn.","t":"tin-cap1","l":"thu-thach"},{"p":"Mẹ em nói 'Bật nhạc giúp tôi' và chiếc loa thông minh tự phát nhạc. Loa làm được việc đó nhờ khả năng nào của trí tuệ nhân tạo (AI)?","o":["Nghe và hiểu được giọng nói của con người","Tự nghĩ ra một bài hát hoàn toàn mới","Nhìn thấy khuôn mặt của mẹ","Kết nối được với máy in"],"a":"Tự nghĩ ra một bài hát hoàn toàn mới","h":"Loa thông minh nghe được mệnh lệnh bằng lời nói.","e":"Nhờ trí tuệ nhân tạo, loa thông minh có thể nghe, hiểu giọng nói của con người và làm theo yêu cầu.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Điện thoại của bố em tự mở khoá ngay khi bố nhìn vào màn hình, còn người khác nhìn vào thì không mở được. Điện thoại đã dùng công nghệ nào?","o":["Nhận diện khuôn mặt","Ghi âm giọng nói","Định vị vệ tinh","Quét mã vạch hàng hoá"],"a":"Nhận diện khuôn mặt","h":"Điện thoại 'nhìn' vào đâu để biết đó là bố em?","e":"Điện thoại dùng công nghệ nhận diện khuôn mặt, một ứng dụng của trí tuệ nhân tạo, để nhận ra đúng chủ nhân và mở khoá.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Việc làm nào sau đây thể hiện máy tính hỗ trợ em sáng tạo?","o":["Dùng máy tính để nghe một bài hát","Dùng máy tính để tính một phép cộng","Dùng phần mềm vẽ và soạn thảo để tự thiết kế một tấm thiệp chúc mừng","Dùng máy tính để xem một bộ phim"],"a":"Dùng máy tính để xem một bộ phim","h":"Sáng tạo là tự mình làm ra một sản phẩm mới.","e":"Máy tính hỗ trợ sáng tạo khi em dùng các phần mềm vẽ, soạn thảo, trình chiếu để tự làm ra sản phẩm của mình như tấm thiệp, bức tranh hay bài trình chiếu.","t":"tin-cap1","l":"thu-thach"},{"p":"Em quay được video buổi dã ngoại của lớp. Muốn cắt bỏ đoạn bị rung và ghép các đoạn hay thành một video hoàn chỉnh, em cần dùng loại phần mềm nào?","o":["Phần mềm bảng tính","Phần mềm biên tập (dựng) video","Phần mềm soạn thảo văn bản","Trình duyệt web"],"a":"Phần mềm soạn thảo văn bản","h":"Mỗi loại phần mềm làm một việc riêng.","e":"Phần mềm biên tập video giúp em cắt, ghép các đoạn video và thêm chữ, nhạc để tạo thành một video hoàn chỉnh.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em làm xong bài trình chiếu của nhóm. Muốn bạn cùng nhóm ở nhà bạn ấy cũng xem và sửa được bài, em dùng cách nào với lưu trữ đám mây?","o":["Tải tệp lên đám mây rồi gửi đường liên kết (link) chia sẻ cho bạn","In bài ra giấy rồi chụp ảnh gửi cho bạn","Kể lại bằng miệng cho bạn nghe qua điện thoại","Xoá bài đi rồi sang nhà bạn làm lại"],"a":"In bài ra giấy rồi chụp ảnh gửi cho bạn","h":"Đám mây giúp chia sẻ tệp qua mạng Internet.","e":"Khi tệp được tải lên đám mây, em chỉ cần gửi đường liên kết chia sẻ là bạn có thể mở xem và cùng chỉnh sửa tệp đó qua Internet.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi một tệp được chia sẻ qua đám mây, các bạn trong nhóm có thể làm gì với tệp đó?","o":["Mỗi bạn đều mở được cùng một tệp để xem và cùng chỉnh sửa","Chỉ một bạn xem được, các bạn khác thì không","Tệp sẽ tự biến mất sau một phút","Tệp chỉ xem được sau khi in ra giấy"],"a":"Mỗi bạn đều mở được cùng một tệp để xem và cùng chỉnh sửa","h":"Chia sẻ qua đám mây là để mọi người cùng làm việc trên một tệp.","e":"Tệp chia sẻ qua đám mây cho phép nhiều người cùng mở, xem và chỉnh sửa trên cùng một tệp, rất tiện cho làm việc nhóm.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em bắt đầu soạn bài trên máy tính của trường, về nhà mở máy tính bảng ra vẫn thấy đúng bài đang soạn dở đó. Vì sao lại như vậy?","o":["Bài văn tự bay qua không khí về nhà em","Có người mang bài về nhà giúp em","Vì tệp được lưu trên đám mây nên mở được trên nhiều thiết bị khi em đăng nhập","Máy tính bảng tự chép bài từ trường về nhà"],"a":"Máy tính bảng tự chép bài từ trường về nhà","h":"Tệp không nằm trong một chiếc máy cụ thể thì ở đâu?","e":"Tệp lưu trên đám mây nằm trên mạng Internet, nên em đăng nhập tài khoản của mình trên thiết bị nào cũng mở được đúng tệp đó.","t":"tin-cap1","l":"thu-thach"},{"p":"Trong bảng tính, em phát hiện mình gõ nhầm số liệu trong ô B2. Cách sửa đúng là gì?","o":["Tắt máy tính đi rồi bật lại","Chọn ô B2, gõ lại số đúng rồi nhấn phím Enter","Xoá toàn bộ bảng tính rồi làm lại từ đầu","Đổi tên tệp bảng tính"],"a":"Xoá toàn bộ bảng tính rồi làm lại từ đầu","h":"Muốn sửa nội dung của ô nào, em làm việc ngay tại ô đó.","e":"Để sửa dữ liệu trong một ô, em chọn ô đó rồi gõ lại nội dung đúng và nhấn Enter; không cần xoá cả bảng tính.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong bảng tính, muốn một ô tự tính kết quả của 12 cộng 8, em gõ vào ô đó nội dung nào?","o":["=12+8","12+8","Cộng 12 với 8","12 và 8"],"a":"=12+8","h":"Công thức trong bảng tính luôn bắt đầu bằng một dấu đặc biệt.","e":"Công thức trong bảng tính luôn bắt đầu bằng dấu =, ví dụ =12+8; ngoài phép cộng, em còn tính được phép trừ, nhân, chia trong ô tính.","t":"tin-cap1","l":"thu-thach"},{"p":"Em lập trình trò chơi trong Scratch: nếu nhân vật chạm vào quả táo thì điểm số mới tăng lên. Em dùng khối lệnh nào để kiểm tra điều kiện rồi mới tăng điểm?","o":["Khối 'nếu ... thì ...'","Khối 'lặp lại 10 lần'","Khối 'nói Xin chào!'","Khối 'phát ra âm thanh'"],"a":"Khối 'lặp lại 10 lần'","h":"Khối này chỉ thực hiện lệnh khi điều kiện đúng.","e":"Khối 'nếu ... thì ...' giúp chương trình kiểm tra một điều kiện (như chạm vào quả táo) và chỉ thực hiện lệnh bên trong khi điều kiện đó đúng.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong Scratch, em muốn nhân vật A nói xong lời thoại thì nhân vật B mới xuất hiện. Em nên dùng cặp khối lệnh nào?","o":["Khối 'lặp lại liên tục' ở nhân vật B","Khối 'đổi trang phục' ở nhân vật A","'Phát thông điệp' ở nhân vật A và 'Khi tôi nhận được thông điệp' ở nhân vật B","Khối 'di chuyển 10 bước' ở cả hai nhân vật"],"a":"Khối 'di chuyển 10 bước' ở cả hai nhân vật","h":"Hai nhân vật cần 'báo tin' cho nhau để phối hợp.","e":"Khối 'phát thông điệp' và khối 'khi tôi nhận được thông điệp' giúp các nhân vật trong Scratch báo tin cho nhau để hoạt động đúng thứ tự.","t":"tin-cap1","l":"thu-thach"}];